#
# host.ps1 - WebView2 UI shell.
#
# Hosts a borderless WPF window containing a WebView2 control. The UI
# (HTML/CSS/JS) is rendered via NavigateToString. The PowerShell packaging
# engine is embedded in this file as base64 and dot-sourced at startup.
# UI <-> PowerShell communication uses the WebView2 postMessage bridge.
# =============================================================================

param(
  [string]$Wv2AssemblyDir = (Join-Path $PSScriptRoot 'wv2')
)
$__UiHtml = @'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>AppUpdater</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=IBM+Plex+Sans:wght@400;450;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
:root{
  --void:#07070F; --panel:#0D0E1A; --panel-2:#111327;
  --edge:#1C1E33; --edge-hi:#2A2D4A;
  --ink:#E4E6F2; --dim:#6C6F8E; --faint:#3D4060;
  --signal:#5EA2FF; --signal-2:#8B7CFF;
  --ok:#4ADE9B; --warn:#FFB454; --bad:#FF6B6B;
  --ok-tint-bd:rgba(74,222,155,.3); --ok-tint-bg:rgba(74,222,155,.07);
  --warn-tint-bd:rgba(255,180,84,.3); --warn-tint-bg:rgba(255,180,84,.07);
  --grad:linear-gradient(135deg,var(--signal),var(--signal-2));
  --r:10px; --r-sm:7px;
  --ease:cubic-bezier(.2,.8,.2,1);
  --font-d:'Space Grotesk',sans-serif; --font-b:'IBM Plex Sans',sans-serif; --font-m:'IBM Plex Mono',monospace;
}
*{margin:0;padding:0;box-sizing:border-box}
html,body{height:100%}
body{background:var(--void);color:var(--ink);font-family:var(--font-b);font-size:13.5px;line-height:1.5;overflow:hidden}
body::before{content:'';position:fixed;inset:0;pointer-events:none;
  background:radial-gradient(600px 400px at 12% -8%, rgba(94,162,255,.055), transparent 60%),
             radial-gradient(700px 500px at 105% 110%, rgba(139,124,255,.05), transparent 60%)}
::selection{background:rgba(94,162,255,.28)}
button{font:inherit;color:inherit;background:none;border:none;cursor:pointer}
input,textarea,select{font:inherit;color:inherit}

.app{display:grid;grid-template-columns:64px 1fr;grid-template-rows:calc(100vh - 6px);height:calc(100vh - 6px)}
.rail{border-right:1px solid var(--edge);background:rgba(13,14,26,.6);display:flex;flex-direction:column;align-items:center;padding:14px 0 20px;gap:6px;z-index:5}
.logo{width:36px;height:36px;border-radius:9px;background:var(--grad);display:grid;place-items:center;margin-bottom:14px;box-shadow:0 0 24px rgba(94,162,255,.35);cursor:pointer}
.logo svg{transition:none}
.logo.spin svg{animation:logospin .6s cubic-bezier(.3,.1,.3,1)}
@keyframes logospin{to{transform:rotate(360deg)}}
.nav-btn{width:40px;height:40px;border-radius:9px;display:grid;place-items:center;color:var(--dim);
  transition:background .18s var(--ease),color .18s var(--ease),transform .18s var(--ease);position:relative}
.nav-btn:hover{background:var(--panel-2);color:var(--ink);transform:translateY(-1px)}
  #win-minimize:hover{background:var(--panel-2);color:var(--ink)}
  #win-close:hover{background:#e5484d;color:#fff}
.nav-btn.on{background:var(--panel-2);color:var(--signal)}
.nav-btn.on::before{content:'';position:absolute;left:-13px;top:9px;bottom:9px;width:2.5px;border-radius:2px;background:var(--grad)}
.nav-btn svg{width:19px;height:19px}
.rail .spacer{flex:1}
.nav-tip{position:absolute;left:52px;top:50%;translate:0 -50%;background:var(--panel-2);border:1px solid var(--edge);
  padding:4px 10px;border-radius:6px;font-size:11.5px;white-space:nowrap;opacity:0;pointer-events:none;
  transition:opacity .15s var(--ease),translate .15s var(--ease);z-index:50}
.nav-btn:hover .nav-tip{opacity:1;translate:4px -50%}

.stage{display:flex;flex-direction:column;min-width:0;height:calc(100vh - 6px);min-height:0}
.rail{height:calc(100vh - 6px)}
.topbar{height:64px;border-bottom:1px solid var(--edge);display:flex;align-items:center;gap:22px;padding:0 26px;flex-shrink:0}
.crumb{font-family:var(--font-d);font-weight:600;font-size:15px;letter-spacing:.01em}

.pipe{display:flex;align-items:center;gap:0;margin-left:auto}
.pnode{display:flex;align-items:center}
.pdot{width:26px;height:26px;border-radius:50%;border:1.5px solid var(--edge-hi);display:grid;place-items:center;
  font-family:var(--font-m);font-size:10px;color:var(--faint);position:relative;background:var(--panel);
  transition:border-color .4s var(--ease),color .4s var(--ease),box-shadow .4s var(--ease)}
.pdot .tick{position:absolute;inset:0;display:grid;place-items:center;opacity:0;transform:scale(.4);transition:opacity .3s var(--ease),transform .35s var(--ease)}
.pdot .tick svg{width:11px;height:11px;stroke:#0A0B14;stroke-width:3;fill:none}
.pnode.done .pdot{background:var(--grad);border-color:transparent;color:transparent;box-shadow:0 0 14px rgba(94,162,255,.35)}
.pnode.done .pdot .tick{opacity:1;transform:scale(1)}
.pnode.live .pdot{border-color:var(--signal);color:var(--signal);animation:livepulse 1.6s var(--ease) infinite}
@keyframes livepulse{0%,100%{box-shadow:0 0 0 0 rgba(94,162,255,.35)}50%{box-shadow:0 0 0 6px rgba(94,162,255,0)}}
.plabel{font-size:10px;color:var(--faint);letter-spacing:.1em;text-transform:uppercase;margin-left:7px;transition:color .4s var(--ease)}
.pnode.done .plabel,.pnode.live .plabel{color:var(--dim)}
.pnode.live .plabel{color:var(--signal)}
.pline{width:34px;height:1.5px;background:var(--edge-hi);margin:0 10px;position:relative;overflow:hidden}
.pline i{position:absolute;inset:0;background:var(--grad);transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.pnode.done + .pline i{transform:scaleX(1)}
.pline.flow::after{content:'';position:absolute;top:-1.5px;width:10px;height:4.5px;border-radius:3px;background:var(--signal);
  filter:blur(.5px);box-shadow:0 0 8px var(--signal);animation:packet 1.1s linear infinite}
@keyframes packet{from{left:-12px}to{left:100%}}

/* Guided tour spotlight overlay. */
#tour-overlay{position:fixed;inset:0;z-index:200;display:none}
#tour-spot{position:absolute;border-radius:10px;box-shadow:0 0 0 9999px rgba(4,4,10,.82);
  border:1.5px solid var(--signal);transition:top .35s var(--ease),left .35s var(--ease),width .35s var(--ease),height .35s var(--ease);pointer-events:none}
#tour-card{position:absolute;width:300px;background:var(--panel);border:1px solid var(--edge-hi);border-radius:12px;
  padding:18px;box-shadow:0 12px 40px rgba(0,0,0,.6);transition:top .35s var(--ease),left .35s var(--ease)}

/* Reduced-motion mode: disables animations and transitions app-wide. */
body.reduce-motion *, body.reduce-motion *::before, body.reduce-motion *::after{
  animation-duration:.001ms!important;animation-delay:0s!important;animation-iteration-count:1!important;
  transition-duration:.001ms!important;transition-delay:0s!important;scroll-behavior:auto!important}

/* High-contrast mode. */
body.high-contrast{
  --ink:#FFFFFF; --dim:#C7C9DC; --faint:#8A8DB0;
  --edge:#4A4D70; --edge-hi:#7276A8; --panel:#0A0A14; --panel-2:#14152A}
body.high-contrast .card, body.high-contrast .field, body.high-contrast .btn{border-width:1.5px}

/* Colour-blind-safe palette (Okabe-Ito) with shape-coded status indicators. */
body.colorblind-safe{
  --ok:#0072B2; --warn:#E69F00; --bad:#D55E00;
  --ok-tint-bd:rgba(0,114,178,.3); --ok-tint-bg:rgba(0,114,178,.07);
  --warn-tint-bd:rgba(230,159,0,.3); --warn-tint-bg:rgba(230,159,0,.07);
}
body.colorblind-safe .badge.ok i, body.colorblind-safe .chip.g i{border-radius:50%}
body.colorblind-safe .badge.wn i, body.colorblind-safe .chip.w i{border-radius:1px;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}
body.colorblind-safe .toast.err b i{border-radius:1px}

/* Keyboard focus indicator. */
:focus-visible{outline:2px solid var(--signal)!important;outline-offset:2px}

.screens{flex:1;position:relative;overflow:hidden}
.screen{position:absolute;inset:0;padding:26px 28px 32px;overflow-y:auto;
  opacity:0;pointer-events:none;transform:translateY(10px);transition:opacity .28s var(--ease),transform .28s var(--ease)}
.screen.on{opacity:1;pointer-events:auto;transform:none}
.screen::-webkit-scrollbar{width:9px}
.screen::-webkit-scrollbar-thumb{background:var(--edge);border-radius:5px;border:2px solid var(--void)}
.screen.on .rise{animation:rise .5s var(--ease) both}
.screen.on .rise:nth-child(2){animation-delay:.05s}
.screen.on .rise:nth-child(3){animation-delay:.1s}
.screen.on .rise:nth-child(4){animation-delay:.15s}
@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}

.card{background:var(--panel);border:1px solid var(--edge);border-radius:var(--r);transition:border-color .2s var(--ease)}
.card:hover{border-color:var(--edge-hi)}
.build-cta{position:relative;border-color:rgba(94,162,255,.35);background:linear-gradient(180deg,rgba(94,162,255,.06),rgba(139,124,255,.03));
  transition:transform .18s var(--ease),border-color .18s var(--ease),box-shadow .18s var(--ease)}
.build-cta:hover{border-color:var(--signal);transform:translateY(-2px);box-shadow:0 10px 30px rgba(94,162,255,.18)}
.build-cta:hover .build-cta-arrow{transform:translateX(3px)}
.build-cta-arrow{transition:transform .18s var(--ease)}
.card-h{padding:14px 18px 0}
.eyebrow{font-family:var(--font-m);font-size:9.5px;letter-spacing:.16em;color:var(--faint);text-transform:uppercase}
.card-t{font-family:var(--font-d);font-weight:600;font-size:15px;margin-top:3px}
.card-b{padding:16px 18px 18px}
.lbl{font-size:11.5px;color:var(--dim);margin:0 0 5px;display:block}
.field{width:100%;background:var(--panel-2);border:1px solid var(--edge);border-radius:var(--r-sm);
  padding:9px 12px;font-size:12.5px;outline:none;transition:border-color .18s var(--ease),box-shadow .18s var(--ease)}
.field:hover{border-color:var(--edge-hi)}
.field:focus{border-color:var(--signal);box-shadow:0 0 0 3px rgba(94,162,255,.16),0 0 18px rgba(94,162,255,.10)}
.field.mono{font-family:var(--font-m);font-size:11.5px}
.hint{font-size:10.5px;color:var(--faint);margin-top:5px}
.row{display:grid;gap:14px}
.row.c2{grid-template-columns:1fr 1fr}
.mt{margin-top:14px}

.btn{display:inline-flex;align-items:center;gap:8px;padding:9px 16px;border-radius:var(--r-sm);
  background:var(--panel-2);border:1px solid var(--edge);color:var(--dim);font-size:12.5px;font-weight:500;transition:all .16s var(--ease)}
.btn:hover{color:var(--ink);border-color:var(--edge-hi);transform:translateY(-1px)}
.btn:active{transform:translateY(0) scale(.98)}
.btn.primary{background:var(--grad);border:none;color:#0A0B14;font-weight:600;box-shadow:0 2px 14px rgba(94,162,255,.25)}
.btn.primary:hover{box-shadow:0 4px 22px rgba(94,162,255,.4);filter:brightness(1.06)}
.btn.big{padding:12px 26px;font-size:13.5px;border-radius:9px}
.btn.ghost{background:transparent}
.btn.danger{background:transparent;border-color:#4a1a1a;color:#cc6666}
.btn.sm{padding:6px 13px;font-size:11.5px}
.btn:disabled{opacity:.4;cursor:default;pointer-events:none}

.seg{position:relative;display:inline-flex;background:var(--panel-2);border:1px solid var(--edge);border-radius:9px;padding:3px;gap:2px}
.seg button{position:relative;z-index:1;padding:7px 16px;border-radius:6px;font-size:12px;font-weight:500;color:var(--dim);transition:color .2s var(--ease);white-space:nowrap}
.seg button.on{color:var(--ink)}
.seg .thumb{position:absolute;top:3px;bottom:3px;border-radius:6px;background:var(--void);border:1px solid var(--edge-hi);
  box-shadow:0 1px 6px rgba(0,0,0,.4);transition:left .22s var(--ease),width .22s var(--ease)}
.seg.accent .thumb{background:linear-gradient(135deg,rgba(94,162,255,.16),rgba(139,124,255,.16));border-color:rgba(94,162,255,.4)}
.seg.accent button.on{color:var(--signal)}

.drop{border:1.5px dashed var(--edge-hi);border-radius:var(--r);padding:30px 20px;text-align:center;transition:all .2s var(--ease);cursor:pointer;position:relative;overflow:hidden}
.drop:hover{border-color:var(--signal);background:rgba(94,162,255,.035)}
.drop:hover .drop-ico{transform:translateY(-3px);color:var(--signal)}
.drop-ico{color:var(--faint);transition:all .25s var(--ease);margin-bottom:8px}
.drop-ico svg{width:30px;height:30px}
.drop b{display:block;font-family:var(--font-d);font-weight:600;font-size:14px}
.drop span{font-size:11.5px;color:var(--dim)}

.chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}
.chip{display:inline-flex;align-items:center;gap:6px;background:var(--panel-2);border:1px solid var(--edge);
  border-radius:20px;padding:4px 11px;font-family:var(--font-m);font-size:10.5px;color:var(--dim);animation:chipin .4s var(--ease) both}
.chip:nth-child(2){animation-delay:.06s}.chip:nth-child(3){animation-delay:.12s}.chip:nth-child(4){animation-delay:.18s}
@keyframes chipin{from{opacity:0;transform:scale(.85)}to{opacity:1;transform:none}}
.chip i{width:6px;height:6px;border-radius:50%;background:var(--signal)}
.chip.g i{background:var(--ok)} .chip.w i{background:var(--warn)}

.tgl{position:relative;width:36px;height:20px;border-radius:20px;background:var(--panel-2);border:1px solid var(--edge);transition:all .2s var(--ease);flex-shrink:0}
.tgl::after{content:'';position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:var(--dim);transition:all .22s var(--ease)}
.tgl.on{background:rgba(94,162,255,.2);border-color:rgba(94,162,255,.5)}
.tgl.on::after{left:18px;background:var(--signal);box-shadow:0 0 8px rgba(94,162,255,.6)}
.tglrow{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 0}
.tglrow + .tglrow{border-top:1px solid var(--edge)}
.tglrow b{font-weight:500;font-size:12.5px;display:block}
.tglrow small{color:var(--faint);font-size:10.5px}

.buildbar{border-top:1px solid var(--edge);background:rgba(13,14,26,.85);backdrop-filter:blur(10px);padding:14px 28px;display:flex;align-items:center;gap:18px;flex-shrink:0}
.summary{font-family:var(--font-m);font-size:11px;color:var(--dim);flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.summary b{color:var(--signal);font-weight:500}
.summary .sep{color:var(--faint);margin:0 7px}

.fleet{width:100%;border-collapse:collapse}
.fleet th{font-family:var(--font-m);font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--faint);text-align:left;padding:0 14px 10px;font-weight:400}
.fleet td{padding:13px 14px;border-top:1px solid var(--edge);font-size:12.5px}
.fleet tr.r{transition:background .15s var(--ease)}
.fleet tr.r:hover{background:rgba(94,162,255,.04)}
.fleet .mono{font-family:var(--font-m);font-size:11px;color:var(--dim)}
.badge{display:inline-flex;align-items:center;gap:6px;font-size:10.5px;font-family:var(--font-m);padding:3px 10px;border-radius:20px;border:1px solid}
.badge.ok{color:var(--ok);border-color:var(--ok-tint-bd);background:var(--ok-tint-bg)}
.badge.wn{color:var(--warn);border-color:var(--warn-tint-bd);background:var(--warn-tint-bg)}
.badge i{width:5px;height:5px;border-radius:50%;background:currentColor}

.phase{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--edge);color:var(--faint);transition:color .3s var(--ease)}
.phase:last-child{border-bottom:none}
.phase .pi{width:20px;height:20px;border-radius:50%;border:1.5px solid var(--edge-hi);display:grid;place-items:center;flex-shrink:0;transition:all .3s var(--ease)}
.phase .pi svg{width:9px;height:9px;stroke:#0A0B14;stroke-width:3.5;fill:none;opacity:0;transform:scale(.4);transition:all .25s var(--ease)}
.phase.doing{color:var(--ink)}
.phase.doing .pi{border-color:var(--signal)}
.phase.doing .pi::after{content:'';width:8px;height:8px;border-radius:50%;background:var(--signal);animation:livepulse 1.4s infinite}
.phase.did{color:var(--dim)}
.phase.did .pi{background:var(--grad);border-color:transparent}
.phase.did .pi svg{opacity:1;transform:scale(1)}
.log{background:#05050B;border:1px solid var(--edge);border-radius:var(--r-sm);font-family:var(--font-m);font-size:11px;line-height:1.75;padding:14px 16px;height:260px;overflow-y:auto}
.log div{opacity:0;animation:logline .3s var(--ease) forwards}
@keyframes logline{from{opacity:0;transform:translateX(-6px)}to{opacity:1;transform:none}}
.log .t{color:var(--faint);margin-right:10px}
.log .ok{color:var(--ok)} .log .in{color:var(--dim)} .log .ac{color:var(--signal)} .log .wr{color:var(--warn)}
.log::-webkit-scrollbar{width:8px}.log::-webkit-scrollbar-thumb{background:var(--edge);border-radius:4px}

.pbar{height:5px;border-radius:3px;background:var(--panel-2);overflow:hidden;position:relative}
.pbar i{display:block;height:100%;width:0;border-radius:3px;background:var(--grad);transition:width .5s var(--ease);position:relative;overflow:hidden}
.pbar i::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);animation:shimmer 1.4s linear infinite}
@keyframes shimmer{from{transform:translateX(-100%)}to{transform:translateX(100%)}}

.done-ring{width:76px;height:76px;margin:0 auto 18px;position:relative}
.done-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.done-ring .rg{fill:none;stroke:var(--edge);stroke-width:3}
.done-ring .rp{fill:none;stroke:url(#gradstroke);stroke-width:3;stroke-linecap:round;stroke-dasharray:213;stroke-dashoffset:213;animation:ring .8s var(--ease) .1s forwards}
@keyframes ring{to{stroke-dashoffset:0}}
.done-ring .chk{position:absolute;inset:0;display:grid;place-items:center}
.done-ring .chk svg{width:30px;height:30px;transform:none;stroke:var(--ok);stroke-width:2.5;fill:none;stroke-dasharray:30;stroke-dashoffset:30;animation:ring .45s var(--ease) .75s forwards}
.sheet{background:var(--panel-2);border:1px solid var(--edge);border-radius:var(--r-sm);font-family:var(--font-m);font-size:11px}
.sheet .srow{display:flex;align-items:center;gap:12px;padding:10px 14px;border-bottom:1px solid var(--edge)}
.sheet .srow:last-child{border-bottom:none}
.sheet .sk{color:var(--faint);width:110px;flex-shrink:0;font-size:10px;letter-spacing:.08em;text-transform:uppercase}
.sheet .sv{color:var(--ink);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.copybtn{color:var(--faint);padding:4px;border-radius:5px;transition:all .15s var(--ease);flex-shrink:0}
.copybtn:hover{color:var(--signal);background:rgba(94,162,255,.1)}
.copybtn svg{width:13px;height:13px;display:block}

.toasts{position:fixed;bottom:22px;right:22px;display:flex;flex-direction:column;gap:10px;z-index:100}
.toast{background:var(--panel-2);border:1px solid var(--edge-hi);border-radius:9px;padding:12px 16px;min-width:280px;
  box-shadow:0 8px 32px rgba(0,0,0,.5);position:relative;overflow:hidden;animation:toastin .38s var(--ease)}
.toast.out{animation:toastout .3s var(--ease) forwards}
@keyframes toastin{from{opacity:0;transform:translateX(30px) scale(.96)}to{opacity:1;transform:none}}
@keyframes toastout{to{opacity:0;transform:translateX(30px) scale(.96)}}
.toast b{font-size:12.5px;font-weight:600;display:flex;align-items:center;gap:8px}
.toast b i{width:7px;height:7px;border-radius:50%;background:var(--ok);box-shadow:0 0 8px var(--ok)}
.toast.err b i{background:var(--bad);box-shadow:0 0 8px var(--bad)}
.toast p{font-size:11.5px;color:var(--dim);margin-top:3px}
.toast .life{position:absolute;bottom:0;left:0;height:2px;background:var(--grad);animation:life 4s linear forwards}
@keyframes life{from{width:100%}to{width:0}}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
/* Build screen only: denser spacing so the whole screen fits the 640-800px
   window without scrolling - scoped to #screen-build so other screens (which
   don't have this many stacked cards) keep the normal roomier spacing. */
#screen-build{padding-top:16px;padding-bottom:16px}
#screen-build .card-h{padding:8px 18px 0}
#screen-build .card-b{padding:9px 18px 11px}
#screen-build .hint{margin-top:4px}
#screen-build .tglrow{padding:7px 0}
#bp-disclosure{display:flex;align-items:center;gap:6px;margin-top:8px;padding-top:8px;border-top:1px solid var(--edge);cursor:pointer;user-select:none;background:none;border-left:none;border-right:none;border-bottom:none;width:100%;text-align:left;color:var(--ink);font:inherit}
#bp-disclosure svg{width:12px;height:12px;transition:transform .15s var(--ease);flex-shrink:0}
#bp-disclosure.open svg{transform:rotate(90deg)}
#bp-disclosure.tour-click-sim{animation:tourClickSim .42s var(--ease)}
@keyframes tourClickSim{0%{box-shadow:0 0 0 0 rgba(94,162,255,.55)}30%{transform:scale(.96);box-shadow:0 0 0 6px rgba(94,162,255,.28)}100%{transform:scale(1);box-shadow:0 0 0 0 rgba(94,162,255,0)}}
</style>
</head>
<body>
<svg width="0" height="0"><defs><linearGradient id="gradstroke" x1="0" y1="0" x2="1" y2="1">
<stop offset="0" stop-color="#5EA2FF"/><stop offset="1" stop-color="#8B7CFF"/></linearGradient></defs></svg>

<div class="app">
  <nav class="rail">
    <div class="logo" title="AppUpdater"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="#0A0B14" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12a8 8 0 0 1 14-5.2M20 12a8 8 0 0 1-14 5.2"/><path d="M17.5 4.5v3h-3M6.5 19.5v-3h3"/></svg></div>
    <button class="nav-btn on" data-go="home"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 12l9-8 9 8M5 10v10h5v-6h4v6h5V10"/></svg><span class="nav-tip">Home</span></button>
    <button class="nav-btn" data-go="build"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><path d="M3.3 7l8.7 5 8.7-5M12 22V12"/></svg><span class="nav-tip">Package builder</span></button>
    <button class="nav-btn" data-go="fleet"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="7" height="7" rx="1.3"/><path d="M13 5h8M13 8.5h8M3 15h18M3 18.5h12"/></svg><span class="nav-tip">App fleet</span></button>
    <button class="nav-btn" data-go="profiles"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="7" height="7" rx="1.5"/><rect x="14" y="4" width="7" height="7" rx="1.5"/><rect x="3" y="15" width="7" height="7" rx="1.5"/><rect x="14" y="15" width="7" height="7" rx="1.5"/></svg><span class="nav-tip">Client profiles</span></button>
    <button class="nav-btn" data-go="history"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 3v5h5"/><path d="M3.05 13a9 9 0 1 0 2.13-7.83L3 8"/><path d="M12 7v5l4 2"/></svg><span class="nav-tip">History</span></button>
    <button class="nav-btn" data-go="worker"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg><span class="nav-tip">Worker &amp; settings</span></button>
    <div class="spacer"></div>
    <button class="nav-btn" data-go="accessibility" title="Accessibility"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="4" r="1.6" fill="currentColor" stroke="none"/><path d="M5 8.5c3.5 1 10.5 1 14 0M12 6v6l-3 8M12 12l3 8"/></svg><span class="nav-tip">Accessibility</span></button>
    <button class="nav-btn" data-go="docs" title="Docs &amp; help"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 1.5-2.5 1.8-2.5 3.5"/><circle cx="12" cy="17" r=".6" fill="currentColor" stroke="none"/></svg><span class="nav-tip">Docs &amp; help</span></button>
  </nav>

  <div class="stage">
    <div class="topbar" id="drag-region" style="cursor:move">
      <div class="crumb" id="crumb">AppUpdater</div>
      <div class="pipe" id="pipe" style="display:none"></div>
      <div style="display:flex;align-items:center;gap:4px;margin-left:16px">
        <button id="win-minimize" title="Minimize" style="width:30px;height:26px;border-radius:6px;display:grid;place-items:center;color:var(--dim);background:none;border:none;cursor:pointer">
          <svg viewBox="0 0 12 12" width="11" height="11"><rect x="1" y="5.5" width="10" height="1.2" fill="currentColor"/></svg>
        </button>
        <button id="win-close" title="Close" style="width:30px;height:26px;border-radius:6px;display:grid;place-items:center;color:var(--dim);background:none;border:none;cursor:pointer">
          <svg viewBox="0 0 12 12" width="11" height="11" stroke="currentColor" stroke-width="1.3"><path d="M1.5 1.5l9 9M10.5 1.5l-9 9"/></svg>
        </button>
      </div>
    </div>

    <div class="screens" id="screens">

      <!-- ========== HOME ========== -->
      <section class="screen on" data-screen="home" id="screen-home">
        <div style="max-width:980px;margin:0 auto;padding-bottom:20px">
          <div class="rise" style="margin:20px 0 16px">
            <div class="eyebrow">packaging console</div>
            <h1 style="font-family:var(--font-d);font-weight:700;font-size:28px;letter-spacing:-.01em;margin-top:4px">Good afternoon.</h1>
            <p style="color:var(--dim);margin-top:4px;font-size:13px" id="fleet-summary">Loading fleet&hellip;</p>
          </div>

          <div class="rise" id="home-stats" style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px">
            <div class="card" style="padding:11px 14px">
              <div class="eyebrow">apps tracked</div>
              <div style="font-family:var(--font-d);font-weight:700;font-size:22px;margin-top:3px" id="stat-total">0</div>
            </div>
            <div class="card" style="padding:11px 14px">
              <div class="eyebrow">deployed</div>
              <div style="font-family:var(--font-d);font-weight:700;font-size:22px;margin-top:3px;color:var(--ok)" id="stat-deployed">0</div>
            </div>
            <div class="card" style="padding:11px 14px">
              <div class="eyebrow">updates available</div>
              <div style="font-family:var(--font-d);font-weight:700;font-size:22px;margin-top:3px;color:var(--warn)" id="stat-updates">0</div>
            </div>
            <div class="card" style="padding:11px 14px">
              <div class="eyebrow">not yet deployed</div>
              <div style="font-family:var(--font-d);font-weight:700;font-size:22px;margin-top:3px;color:var(--signal)" id="stat-pending">0</div>
            </div>
          </div>

          <div class="card rise" id="getting-started-card" style="display:none;padding:14px 16px;margin-bottom:12px">
            <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
              <div><div class="eyebrow">getting started</div><div class="card-t" style="margin-top:2px">A few things to try</div></div>
              <div style="display:flex;gap:8px">
                <button class="btn primary sm" id="getting-started-tour">Take the guided tour</button>
                <button class="btn ghost sm" id="getting-started-dismiss">Dismiss</button>
              </div>
            </div>
            <div id="getting-started-list"></div>
          </div>

          <div class="card rise" id="release-banner" style="display:none;padding:12px 16px;margin-bottom:14px;border-color:rgba(94,162,255,.3);background:rgba(94,162,255,.06);align-items:center;gap:10px">
            <span style="font-family:var(--font-m);font-size:12px;color:var(--signal);flex:1" id="release-banner-text"></span>
            <button class="btn sm" id="release-banner-github">View</button>
            <button class="btn ghost sm" id="release-banner-dismiss">Dismiss</button>
          </div>

          <div class="card rise" id="worker-banner" style="padding:11px 16px;display:flex;align-items:center;gap:10px;margin-bottom:10px">
            <span style="width:8px;height:8px;border-radius:50%;background:var(--faint);flex-shrink:0" id="worker-dot"></span>
            <span style="font-family:var(--font-m);font-size:12px;color:var(--dim)" id="worker-banner-text">Checking worker&hellip;</span>
          </div>

          <!-- Shown instead of the banner above when no worker is connected yet.
               Deliberately muted/greyed (not a hard block) - building packages
               works fully standalone, so this is an invitation, not a gate. -->
          <div class="card rise" id="connect-card" style="display:none;padding:14px 16px;margin-bottom:12px;opacity:.72;transition:opacity .2s var(--ease)">
            <div style="display:flex;align-items:center;gap:14px">
              <div style="width:40px;height:40px;border-radius:10px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--faint)">
                <svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M4 12a8 8 0 0 1 14-5.2M20 12a8 8 0 0 1-14 5.2"/><path d="M17.5 4.5v3h-3M6.5 19.5v-3h3"/></svg>
              </div>
              <div style="flex:1">
                <div style="font-family:var(--font-d);font-weight:600;font-size:14.5px;color:var(--dim)">Not connected to Cloudflare</div>
                <div style="font-size:12px;color:var(--faint);margin-top:2px">Building packages works fine without this. Connecting adds: a live fleet view that updates as devices check in, automatic update checks so you're not rebuilding manually, and a password-protected status page you can check from anywhere.</div>
              </div>
              <button class="btn sm" id="connect-preview-btn">See what it does</button>
              <button class="btn primary sm" id="connect-btn">Connect</button>
              <button class="btn ghost sm" id="connect-card-dismiss" title="Hide this - bring it back any time from Worker &amp; settings">Dismiss</button>
            </div>

            <div id="connect-demo" style="display:none;margin-top:16px;padding-top:16px;border-top:1px solid var(--edge)">
              <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">
                <span style="width:7px;height:7px;border-radius:50%;background:var(--ok);animation:livepulse 1.6s infinite"></span>
                <span style="font-family:var(--font-m);font-size:10.5px;color:var(--dim)">preview - your fleet dashboard once connected</span>
              </div>
              <div style="background:var(--panel-2);border:1px solid var(--edge);border-radius:8px;padding:14px 16px;font-family:var(--font-m);font-size:11px">
                <div class="demo-row" style="display:flex;align-items:center;gap:10px;padding:6px 0;animation:rise .4s var(--ease) both">
                  <span class="badge ok" style="animation:livepulse 2s infinite"><i></i>online</span>
                  <span style="color:var(--ink);flex:1">VLC media player</span>
                  <span style="color:var(--faint)">3.0.20 &#8594; 3.0.21</span>
                </div>
                <div class="demo-row" style="display:flex;align-items:center;gap:10px;padding:6px 0;animation:rise .4s var(--ease) .08s both">
                  <span class="badge ok"><i></i>online</span>
                  <span style="color:var(--ink);flex:1">7-Zip</span>
                  <span style="color:var(--faint)">up to date</span>
                </div>
                <div class="demo-row" style="display:flex;align-items:center;gap:10px;padding:6px 0;animation:rise .4s var(--ease) .16s both">
                  <span class="badge wn"><i></i>checking</span>
                  <span style="color:var(--ink);flex:1">Notepad++</span>
                  <span style="color:var(--faint)">last seen 4m ago</span>
                </div>
              </div>
              <div class="hint" style="margin-top:10px">Live, updates automatically as devices check in - password-protected, only you can see it.</div>
            </div>
          </div>

          <div class="card rise build-cta" id="home-build-cta" style="cursor:pointer" data-go="build" role="button" tabindex="0">
            <div class="card-b" style="display:flex;align-items:center;gap:18px;padding:22px 24px">
              <div style="width:58px;height:58px;border-radius:14px;background:var(--grad);display:grid;place-items:center;flex-shrink:0;box-shadow:0 0 30px rgba(94,162,255,.45)">
                <svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="#0A0B14" stroke-width="2"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>
              </div>
              <div>
                <div class="eyebrow">start here</div>
                <div style="font-family:var(--font-d);font-weight:700;font-size:19px;margin-top:2px">Build app package</div>
                <div style="color:var(--dim);font-size:12.5px;margin-top:3px">Drop an installer, pick a profile, ship it.</div>
              </div>
              <div class="build-cta-arrow" style="margin-left:auto;color:var(--signal);font-size:26px">&#8250;</div>
            </div>
          </div>

          <div class="rise" style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:12px">
            <div class="card">
              <div class="card-h" style="display:flex;align-items:baseline;justify-content:space-between">
                <div><div class="eyebrow">activity</div><div class="card-t">Recent history</div></div>
                <button class="btn ghost" data-go="history" style="font-size:11.5px">View all &#8250;</button>
              </div>
              <div class="card-b" style="padding-top:10px" id="home-recent-activity">
                <p class="hint" style="margin:0">Nothing yet - build, deploy, or remove an app to see activity here.</p>
              </div>
            </div>
            <div class="card">
              <div class="card-h" style="display:flex;align-items:baseline;justify-content:space-between">
                <div><div class="eyebrow">fleet</div><div class="card-t">Tracked in local manifest</div></div>
                <button class="btn ghost" data-go="fleet" style="font-size:11.5px">View all &#8250;</button>
              </div>
              <div class="card-b" style="padding-top:10px">
                <table class="fleet" id="home-fleet-table"></table>
              </div>
            </div>
          </div>
        </div>
      </section>

      <!-- ========== BUILDER ========== -->
      <section class="screen" data-screen="build" id="screen-build">
        <div style="max-width:980px;margin:0 auto;padding-bottom:8px">
          <div style="display:grid;grid-template-columns:1fr 1.15fr;gap:12px;align-items:start">
            <div style="display:grid;gap:12px">
              <div class="card rise">
                <div class="card-h" style="padding-top:11px"><div class="eyebrow">00 &middot; kind</div><div class="card-t">What are you packaging?</div></div>
                <div class="card-b" style="padding-top:12px;padding-bottom:14px">
                  <div class="seg" id="segKind">
                    <div class="thumb"></div>
                    <button class="on" data-val="app">App (.exe/.msi)</button>
                    <button data-val="printer">Printer</button>
                  </div>
                  <div class="hint" id="kindHint">Standard installer package - drop an exe or msi below.</div>
                </div>
              </div>

              <div class="card rise" id="app-source-card">
                <div class="card-h" style="padding-top:11px"><div class="eyebrow">01 &middot; source</div><div class="card-t">Installer</div></div>
                <div class="card-b" style="padding-top:12px;padding-bottom:14px">
                  <div class="drop" id="drop">
                    <div class="drop-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M17 8l-5-5-5 5M12 3v12"/></svg></div>
                    <b>Drop installer here</b>
                    <span>or click to browse &middot; exe, msi</span>
                  </div>
                  <div id="inspect" style="display:none">
                    <div style="display:flex;align-items:center;gap:12px">
                      <div style="width:38px;height:38px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;font-family:var(--font-m);font-size:9px;color:var(--signal)" id="inspect-ext">EXE</div>
                      <div style="flex:1;min-width:0">
                        <div style="font-weight:600;font-size:12.5px" id="inspect-name">&nbsp;</div>
                        <div style="font-family:var(--font-m);font-size:10px;color:var(--faint)" id="inspect-sub">&nbsp;</div>
                      </div>
                      <button class="btn ghost" style="padding:5px 9px;font-size:11px" id="reDrop">Change</button>
                    </div>
                    <div class="chips" id="inspect-chips"></div>
                  </div>
                </div>
              </div>

              <div class="card rise" id="printer-source-card" style="display:none">
                <div class="card-h" style="padding-top:11px"><div class="eyebrow">01 &middot; source</div><div class="card-t">Printer &amp; driver</div></div>
                <div class="card-b" style="padding-top:12px;padding-bottom:14px">
                  <label class="lbl">Printer name</label>
                  <input class="field" id="f-printername" placeholder="Finance-3F-HP4200">
                  <label class="lbl" style="margin-top:10px">Driver</label>
                  <select class="field" id="f-driverid"><option value="">&mdash; none, use path below &mdash;</option></select>
                  <div style="margin-top:8px;display:none" id="driver-model-row">
                    <label class="lbl">Model</label>
                    <select class="field" id="f-drivermodel"></select>
                    <div class="hint">This driver package covers multiple printer models — pick the one being deployed.</div>
                  </div>
                  <label class="lbl" style="margin-top:10px">Driver name</label>
                  <input class="field" id="f-drivername" placeholder="HP Universal Printing PCL6 (auto-filled from library, or type it for a one-off path-based driver)">
                  <div style="display:flex;align-items:center;gap:6px;margin:10px 0 6px;flex-wrap:wrap">
                    <button type="button" class="btn ghost sm" id="driver-lib-add-toggle" style="padding-left:0">+ Add driver to library</button>
                    <button type="button" class="btn ghost sm" id="driver-lib-import-builtin">Import built-in driver families</button>
                  </div>
                  <div class="hint" id="builtin-import-status" style="margin-bottom:6px"></div>
                  <div id="driver-lib-add-panel" style="display:none;margin-bottom:10px;padding:10px;border:1px solid var(--edge);border-radius:var(--r-sm)">
                    <div class="row c2">
                      <div><label class="lbl">Driver ID</label><input class="field mono" id="dl-id" placeholder="hp-universal-pcl6-x64"></div>
                      <div><label class="lbl">Display name</label><input class="field" id="dl-displayname" placeholder="HP Universal Printing PCL6"></div>
                    </div>
                    <div class="row c2" style="margin-top:8px">
                      <div><label class="lbl">Manufacturer</label><input class="field" id="dl-manufacturer" placeholder="HP Inc."></div>
                      <div><label class="lbl">Driver type</label><input class="field" id="dl-drivertype" placeholder="PCL6"></div>
                    </div>
                    <div class="row c2" style="margin-top:8px">
                      <div><label class="lbl">Architecture</label><input class="field" id="dl-arch" placeholder="x64"></div>
                      <div><label class="lbl">Version</label><input class="field" id="dl-version" placeholder="61.270.0.0"></div>
                    </div>
                    <label class="lbl" style="margin-top:8px">Source (https:// URL, .zip, or folder path)</label>
                    <input class="field mono" id="dl-source" placeholder="https://... or C:\Drivers\hp-pcl6.zip">
                    <div class="row c2" style="margin-top:8px">
                      <div><label class="lbl">INF relative path</label><input class="field mono" id="dl-inf" placeholder="hpcu270u.inf"></div>
                      <div><label class="lbl">Expected publisher</label><input class="field" id="dl-publisher" placeholder="HP Inc."></div>
                    </div>
                    <label class="lbl" style="margin-top:8px">Models (one per line, optional)</label>
                    <textarea class="field mono" id="dl-models" rows="3" placeholder="Brother HL-2290&#10;Brother HL-L2350DW&#10;Brother HL-L2385DW" style="resize:vertical"></textarea>
                    <div class="hint">Leave blank for a single-model driver. Fill in when one INF/driver package covers a whole product family.</div>
                    <div style="display:flex;gap:8px;margin-top:10px">
                      <button class="btn primary sm" id="dl-save">Add to library</button>
                      <button class="btn ghost sm" id="dl-cancel">Cancel</button>
                    </div>
                    <div class="hint" id="dl-status" style="margin-top:6px"></div>
                  </div>
                  <div class="hint" id="driver-source-hint">Pick a driver from the library above, or fill in a local driver path/INF below for a one-off build not worth importing.</div>
                  <div class="row c2" style="margin-top:10px">
                    <div><label class="lbl">Driver source path</label><input class="field mono" id="f-driversourcepath" placeholder="C:\Drivers\hp-pcl6 or .zip"></div>
                    <div><label class="lbl">Driver INF (relative)</label><input class="field mono" id="f-driverinf" placeholder="hpcu270u.inf"></div>
                  </div>
                  <div><label class="lbl">Expected driver publisher</label><input class="field" id="f-driverpublisher" placeholder="HP Inc. (optional but recommended)"></div>
                  <div class="row c2" style="margin-top:10px">
                    <div><label class="lbl">Port host address</label><input class="field mono" id="f-porthost" placeholder="10.20.4.55"></div>
                    <div><label class="lbl">Port number</label><input class="field mono" id="f-portnumber" placeholder="9100"></div>
                  </div>
                  <div><label class="lbl">Location</label><input class="field" id="f-printerlocation" placeholder="3rd Floor - Finance"></div>
                  <div class="hint">Detection checks the printer actually exists with this driver and port, not just that it once ran.</div>
                </div>
              </div>

              <div class="card rise">
                <div class="card-h" style="padding-top:11px"><div class="eyebrow">identity</div><div class="card-t">How Intune sees it</div></div>
                <div class="card-b" style="padding-top:12px;padding-bottom:14px">
                  <label class="lbl">Display name</label>
                  <input class="field" id="f-displayname">
                  <div class="row c2" style="margin-top:10px">
                    <div><label class="lbl">App ID</label><input class="field mono" id="f-appid"></div>
                    <div><label class="lbl">Registry display name</label><input class="field mono" id="f-registryname"></div>
                  </div>
                  <div class="hint">Registry name must match Add/Remove Programs exactly â€” used for detection.</div>
                </div>
              </div>

              <div class="card rise">
                <div class="card-h" style="padding-top:11px"><div class="eyebrow">behaviour</div><div class="card-t">On the endpoint</div></div>
                <div class="card-b" style="padding-top:10px;padding-bottom:12px">
                  <div class="tglrow"><div><b>Close blocking apps</b><small id="close-apps-hint">Detected process to close on install</small></div><button class="tgl on" data-val="closeAppsOn"></button></div>
                  <div class="tglrow"><div><b>Allow deferral</b><small>Users may postpone 3 times</small></div><button class="tgl on" data-val="allowDefer"></button></div>
                </div>
              </div>
            </div>

            <div style="display:grid;gap:12px">
              <div class="card rise">
                <div class="card-h" style="padding-top:11px"><div class="eyebrow">package type</div><div class="card-t">Wrap &amp; behaviour</div></div>
                <div class="card-b" style="padding-top:12px;padding-bottom:14px">
                  <div id="mode-explainer" style="display:none;margin-bottom:10px;padding:10px;border:1px solid var(--signal);border-radius:var(--r-sm);background:rgba(94,162,255,.08)">
                    <div style="font-size:12.5px;line-height:1.6" id="mode-explainer-text"></div>
                    <button type="button" class="btn ghost sm" id="mode-explainer-dismiss" style="margin-top:8px">Got it, stop guiding me</button>
                  </div>
                  <div style="display:flex;align-items:center;gap:8px">
                    <label class="lbl" style="margin:0">Package mode</label>
                    <button type="button" class="btn sm" id="mode-explainer-toggle" style="padding:3px 10px;font-size:11px;color:var(--signal);border:1px solid var(--signal);border-radius:20px;background:rgba(94,162,255,.1)">&#9432; What's this?</button>
                  </div>
                  <div class="seg" id="segMode">
                    <div class="thumb"></div>
                    <button class="on" data-val="runtime">AppUpdater Runtime</button>
                    <button data-val="simple">Simple Package</button>
                  </div>
                  <div class="hint" id="modeHint">Installs auto-update task, scripts and desktop shortcut on every device.</div>

                  <div style="margin-top:10px">
                    <label class="lbl">Output</label>
                    <div class="seg accent" id="segTarget">
                      <div class="thumb"></div>
                      <button class="on" data-val="intunewin">.intunewin</button>
                      <button data-val="psadt">PSADT package</button>
                    </div>
                    <div class="hint" id="targetHint">Package for Intune Win32 app upload.</div>
                  </div>

                  <div style="margin-top:10px;display:none" id="psadt-version-row">
                    <label class="lbl">PSADT version</label>
                    <div class="seg" id="segPsadtVersion">
                      <div class="thumb"></div>
                      <button class="on" data-val="v3">v3</button>
                      <button data-val="v4">v4</button>
                      <button data-val="both">Both</button>
                    </div>
                    <div class="hint">v4 uses the module-based PSAppDeployToolkit with Fluent dialogs; v3 is the classic frontend. "Both" exports each.</div>
                  </div>

                  <label class="lbl" style="margin-top:10px">Client profile</label>
                  <select class="field" id="f-profile"><option value="">Default (uses Settings organisation name)</option></select>
                  <div class="hint" id="profile-hint" style="margin-bottom:6px">Determines the branding used for this build - manage profiles from the nav rail.</div>
                  <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">
                    <button type="button" class="btn ghost sm" id="build-new-profile" style="padding-left:0">+ New profile</button>
                    <button type="button" class="btn ghost sm" id="build-override-toggle" style="display:none">Override for this build &#9662;</button>
                  </div>
                  <div id="build-override-panel" style="display:none;margin-bottom:10px;padding:10px;border:1px solid var(--edge);border-radius:var(--r-sm)">
                    <label class="lbl">Organisation name</label>
                    <input class="field" id="ov-orgname" style="margin-bottom:8px">
                    <label class="lbl">Logo image</label>
                    <div style="display:flex;gap:8px;margin-bottom:8px">
                      <input class="field mono" id="ov-logo" readonly style="flex:1;font-size:10.5px">
                      <button class="btn sm" id="ov-logo-browse">Browse&hellip;</button>
                    </div>
                    <label class="lbl">Banner image</label>
                    <div style="display:flex;gap:8px">
                      <input class="field mono" id="ov-banner" readonly style="flex:1;font-size:10.5px">
                      <button class="btn sm" id="ov-banner-browse">Browse&hellip;</button>
                    </div>
                    <div class="hint" style="margin-top:8px">Applies to this build only - you'll be asked whether to save it back to the profile afterward.</div>
                  </div>

                  <div style="display:none;align-items:center;gap:6px;margin-top:10px" id="bp-header">
                    <button type="button" id="bp-disclosure"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 6l6 6-6 6"/></svg><span class="lbl" style="margin:0" data-version-label>Preview branding</span></button>
                    <div class="seg" id="segBpSwap" style="display:none;transform:scale(.82);transform-origin:left center;margin-left:-6px">
                      <div class="thumb"></div>
                      <button class="on" data-val="v3">v3</button>
                      <button data-val="v4">v4</button>
                    </div>
                  </div>
                  <div id="bp-panel" style="display:none;margin-top:8px;padding-top:12px;border-top:1px solid var(--edge)">
                    <div class="hint" style="margin-bottom:8px">This is what the real install dialog looks like - logo goes on Fluent (v4) dialogs, banner on Classic (v3) dialogs.</div>

                    <!-- v3 Classic: real proportions from the actual PSADT banner (900x125) - white
                         WinForms dialog, banner full-width at top, Segoe UI body text below. -->
                    <div id="bp-preview-v3" style="border-radius:6px;overflow:hidden;background:#F0F0F0;border:1px solid #ACACAC;box-shadow:0 6px 20px rgba(0,0,0,.35);font-family:'Segoe UI',var(--font-b)">
                      <div id="bp-v3-banner-wrap" style="width:100%;aspect-ratio:900/125;background:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden;border-bottom:1px solid #ACACAC">
                        <img id="bp-v3-banner" style="width:100%;height:100%;object-fit:cover">
                      </div>
                      <div style="padding:12px 14px;background:#F0F0F0">
                        <div style="font-weight:600;font-size:12.5px;color:#1a1a1a" id="bp-v3-title">Welcome to the this app Setup</div>
                        <div style="font-size:10.5px;color:#444;margin-top:4px">Please close the following programs before continuing:</div>
                        <div style="background:#fff;border:1px solid #ACACAC;border-radius:2px;margin-top:6px;padding:5px 8px;font-size:10px;color:#333">Microsoft Word</div>
                        <div style="display:flex;gap:6px;margin-top:10px;justify-content:flex-end">
                          <div style="background:#E1E1E1;border:1px solid #ADADAD;border-radius:2px;padding:4px 12px;font-size:10.5px;color:#1a1a1a">Close &amp; Continue</div>
                        </div>
                      </div>
                    </div>

                    <!-- v4 Fluent: iNKORE.UI.WPF.Modern - rounded card, accent button (default
                         Windows accent #0078D7 unless FluentAccentColor is set), Title+SubTitle. -->
                    <div id="bp-preview-v4" style="display:none;border-radius:12px;overflow:hidden;background:#202020;border:1px solid #3a3a3a;box-shadow:0 6px 24px rgba(0,0,0,.4);font-family:var(--font-b)">
                      <div style="padding:20px 20px 16px;display:flex;gap:14px;align-items:flex-start">
                        <div id="bp-v4-icon-wrap" style="width:44px;height:44px;border-radius:10px;overflow:hidden;flex-shrink:0;background:#2d2d2d;display:grid;place-items:center">
                          <img id="bp-v4-icon" style="width:100%;height:100%;object-fit:cover">
                        </div>
                        <div style="min-width:0">
                          <div style="font-weight:600;font-size:14px;color:#fff" id="bp-v4-title">this app</div>
                          <div style="font-size:11px;color:#a0a0a0;margin-top:2px" id="bp-v4-subtitle">Please close the following applications to continue.</div>
                        </div>
                      </div>
                      <div style="padding:0 20px 18px">
                        <div style="background:#2d2d2d;border-radius:6px;padding:8px 12px;font-size:11px;color:#ddd">Microsoft Word</div>
                        <div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end">
                          <div id="bp-v4-accent-btn" style="background:#0078D7;border-radius:5px;padding:6px 16px;font-size:11.5px;color:#fff;font-weight:600">Close apps &amp; install</div>
                        </div>
                      </div>
                    </div>

                    <div class="hint" id="bp-no-assets-hint" style="display:none;margin-top:8px">Real PSADT assets aren't cached on this machine yet - build a PSADT package once and this preview will use the actual banner/icon.</div>
                  </div>
                </div>
              </div>

            </div>
          </div>
        </div>
      </section>

      <!-- ========== PROGRESS ========== -->
      <section class="screen" data-screen="progress" id="screen-progress">
        <div style="max-width:760px;margin:0 auto">
          <div class="rise" style="margin:20px 0 22px;text-align:center">
            <div class="eyebrow">building</div>
            <h2 style="font-family:var(--font-d);font-weight:600;font-size:21px;margin-top:4px" id="progress-title">Package</h2>
            <div class="pbar" style="max-width:420px;margin:16px auto 0"><i id="progress-bar"></i></div>
          </div>
          <div id="progress-error" class="rise" style="display:none;margin-bottom:16px;padding:14px 16px;border-radius:var(--r);background:rgba(255,90,90,.08);border:1px solid rgba(255,90,90,.35)">
            <div style="font-weight:600;font-size:13.5px;color:var(--bad)">Build failed</div>
            <div id="progress-error-msg" style="font-size:12.5px;color:var(--dim);margin-top:4px;line-height:1.5"></div>
            <button class="btn ghost sm" id="progress-error-back" style="margin-top:10px">Back to Build</button>
          </div>
          <div style="display:grid;grid-template-columns:260px 1fr;gap:16px" class="rise">
            <div class="card"><div class="card-b" style="padding-top:12px" id="step-list"></div></div>
            <div class="log" id="log"></div>
          </div>
        </div>
      </section>

      <!-- ========== DONE ========== -->
      <section class="screen" data-screen="done" id="screen-done">
        <div style="max-width:640px;margin:0 auto;text-align:center;padding-top:24px">
          <div class="done-ring rise">
            <svg viewBox="0 0 76 76"><circle class="rg" cx="38" cy="38" r="34"/><circle class="rp" cx="38" cy="38" r="34"/></svg>
            <div class="chk"><svg viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg></div>
          </div>
          <h2 class="rise" style="font-family:var(--font-d);font-weight:600;font-size:22px">Package ready</h2>
          <p class="rise" style="color:var(--dim);font-size:12.5px;margin-top:4px" id="done-path">&nbsp;</p>
          <div class="sheet rise" style="margin-top:22px;text-align:left" id="done-sheet"></div>
          <div class="rise" style="display:flex;gap:10px;justify-content:center;margin-top:22px">
            <button class="btn" data-go="fleet">View fleet</button>
            <button class="btn primary" data-go="home">Done</button>
          </div>
        </div>
      </section>

      <!-- ========== FLEET ========== -->
      <section class="screen" data-screen="fleet" id="screen-fleet">
        <div style="max-width:980px;margin:0 auto">
          <div class="rise" style="margin:10px 0 18px;display:flex;align-items:center;gap:14px">
            <h2 style="font-family:var(--font-d);font-weight:600;font-size:20px">App fleet</h2>
            <span id="fleet-demo-badge" style="display:none;font-family:var(--font-m);font-size:10.5px;color:var(--warn);border:1px solid rgba(255,180,84,.35);background:rgba(255,180,84,.08);padding:3px 9px;border-radius:20px">example data - tour only</span>
            <input class="field" id="fleet-filter" placeholder="Filter apps&hellip;" style="max-width:240px;padding:7px 12px">
            <button class="btn primary" style="margin-left:auto" data-go="build">New package</button>
          </div>
          <div class="card rise"><div class="card-b" style="padding-top:6px">
            <div id="fleet-bulk-bar" style="display:none;align-items:center;gap:12px;padding:8px 4px;margin-bottom:6px;border-bottom:1px solid var(--edge)">
              <span id="fleet-bulk-count" style="font-size:12px;color:var(--dim)"></span>
              <button class="btn sm primary" id="fleet-bulk-mark-deployed">Mark deployed</button>
              <button class="btn sm ghost" id="fleet-bulk-clear">Clear selection</button>
            </div>
            <table class="fleet" id="fleet-table"></table>
          </div></div>
        </div>

        <!-- Local sanity check - runs the REAL detect/install/uninstall
             scripts (or PSADT's own test invocation) on this machine, no
             Intune needed. Separate from "Preview". -->
        <div id="test-modal" style="display:none;position:fixed;inset:0;background:rgba(5,5,10,.65);z-index:90;align-items:center;justify-content:center">
          <div class="card" style="width:560px;max-height:80vh;display:flex;flex-direction:column;padding:0">
            <div style="padding:18px 22px 0"><div class="eyebrow">local sanity check</div><div class="card-t" id="test-modal-title" style="margin-top:4px">Test locally</div></div>
            <div style="padding:12px 22px">
              <p class="hint" style="margin:0 0 10px">Decrypts the real <b>.intunewin</b> file if one exists and tests that (not just loose scripts) - it will actually install (and optionally uninstall) the app on <b style="color:var(--warn)">this machine</b>. No Intune required.</p>
              <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--dim);cursor:pointer;margin-bottom:6px">
                <input type="checkbox" id="test-simulate-system" checked> Simulate Intune deployment (run as SYSTEM, silent)
              </label>
              <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--dim);cursor:pointer">
                <input type="checkbox" id="test-also-uninstall"> Also test uninstall afterwards
              </label>
            </div>
            <div class="log" id="test-log" style="margin:0 22px;flex:1;min-height:180px;max-height:320px"></div>
            <div style="display:flex;justify-content:flex-end;gap:10px;padding:16px 22px">
              <button class="btn" id="test-modal-close">Close</button>
              <button class="btn primary" id="test-modal-start">Start test</button>
            </div>
          </div>
        </div>
      </section>

      <!-- ========== WORKER & SETTINGS ========== -->
      <section class="screen" data-screen="worker" id="screen-worker">
        <div style="max-width:760px;margin:0 auto;padding-bottom:24px">
          <h2 class="rise" style="font-family:var(--font-d);font-weight:600;font-size:20px;margin:8px 0 14px">Worker &amp; settings</h2>

          <!-- Worker stays its own card - it has real distinct actions, not just toggles -->
          <div class="card rise" id="worker-connect-card" style="margin-bottom:12px;padding:16px 20px">
            <div style="display:flex;align-items:center;gap:14px;margin-bottom:12px">
              <div style="width:38px;height:38px;border-radius:10px;background:var(--grad);display:grid;place-items:center;flex-shrink:0;box-shadow:0 0 18px rgba(94,162,255,.3)">
                <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="#0A0B14" stroke-width="2"><path d="M4 12a8 8 0 0 1 14-5.2M20 12a8 8 0 0 1-14 5.2"/><path d="M17.5 4.5v3h-3M6.5 19.5v-3h3"/></svg>
              </div>
              <div>
                <div class="card-t" style="margin:0">Cloudflare worker</div>
                <div id="worker-status" style="margin-top:2px;color:var(--dim);font-size:12px">Loading&hellip;</div>
              </div>
            </div>
            <div id="worker-actions-connected" style="display:none;gap:10px">
              <button class="btn" id="btn-open-status">Open /status dashboard</button>
              <button class="btn" id="btn-worker-options">More worker options&hellip;</button>
              <button class="btn danger" id="btn-disconnect">Disconnect</button>
            </div>
            <div id="worker-actions-disconnected" style="display:none">
              <button class="btn primary" id="btn-worker-connect">Connect to Cloudflare</button>
            </div>
            <p class="hint" id="worker-actions-hint" style="margin-top:10px;display:none">
              "More worker options" covers re-deploy, custom domain, password reset, MFA and token rotation -
              still the existing dialog for now while those get ported into the shell individually.
            </p>
          </div>

          <!-- One consolidated preferences card instead of 4 near-identical
               stacked boxes - everything below saves itself the instant you
               change it (no separate Save button; a small "Saved" flash
               confirms it, the same way most modern settings screens work). -->
          <div class="card rise" style="margin-bottom:14px">
            <div style="padding:18px 22px 4px;display:flex;align-items:center;justify-content:space-between">
              <div class="card-t" style="margin:0">Preferences</div>
              <span id="settings-saved-flash" style="font-size:11px;color:var(--ok);opacity:0;transition:opacity .3s">Saved</span>
            </div>

            <div style="padding:14px 22px">
              <label class="lbl">Default organisation name</label>
              <small style="color:var(--faint);font-size:10.5px;display:block;margin-bottom:6px">Used whenever a build has no client profile selected - backed by a Client Profile, managed from the nav rail.</small>
              <select class="field" id="f-orgname-settings" style="max-width:320px"><option value="">Not set</option></select>
              <div id="f-orgname-not-set-hint" style="display:none;margin-top:6px">
                <span class="hint" style="margin:0">Not set - </span>
                <button type="button" class="btn ghost sm" id="f-orgname-guide-btn" style="padding:0;display:inline;font-size:11px;color:var(--signal)">set up a client profile instead &#8250;</button>
              </div>
            </div>

            <div style="padding:0 22px">
              <div class="tglrow"><div><b>Check GitHub for new releases</b><small>Off = no outbound call is ever made. Recommended off for air-gapped machines.</small></div><button class="tgl on" id="tgl-release-check"></button></div>
              <div class="tglrow"><div><b>Show Cloudflare connection promo</b><small>The "Not connected to Cloudflare" card on Home and the fleet empty-state tip. Off if you dismissed it, or if you're offline-only by design.</small></div><button class="tgl on" id="tgl-cf-advert"></button></div>
              <div class="tglrow"><div><b>Show getting-started checklist</b><small>The "A few things to try" card on Home. Off if you dismissed it or it's not needed anymore.</small></div><button class="tgl on" id="tgl-getting-started"></button></div>
            </div>

            <div style="padding:14px 22px 20px;border-top:1px solid var(--edge);margin-top:4px">
              <label class="lbl" style="margin-bottom:8px;display:block">Folders &amp; log</label>
              <div style="display:flex;gap:10px">
                <button class="btn sm" id="btn-open-output">Output</button>
                <button class="btn sm" id="btn-open-cache">Toolkit cache</button>
                <button class="btn sm" id="btn-open-log">Log</button>
                <button class="btn sm" id="btn-open-github" style="margin-left:auto">GitHub releases</button>
              </div>
              <div id="settings-release" style="font-size:11px;color:var(--dim);margin-top:10px">&nbsp;</div>
            </div>
          </div>

          <!-- Recovery kept visually distinct - these are the two genuinely
               destructive/consequential actions on this screen. -->
          <div class="card rise" style="border-color:rgba(255,180,84,.25)">
            <div class="card-b">
              <div style="display:flex;align-items:center;gap:8px"><span class="eyebrow" style="color:var(--warn)">recovery</span></div>
              <p class="hint" style="margin:8px 0 12px">A passphrase-protected backup of your config, token, client profiles and manifest. Restores only on THIS machine - for a new machine, reconnect to the Worker and re-run setup.</p>
              <div style="display:flex;gap:10px">
                <button class="btn primary" id="btn-export-recovery">Export recovery bundle&hellip;</button>
                <button class="btn" id="btn-import-recovery">Import bundle&hellip;</button>
              </div>
            </div>
          </div>

          <div id="settings-version" style="text-align:center;margin-top:16px;font-size:11px;color:var(--faint)">&nbsp;</div>
        </div>
      </section>

      <!-- ========== CLIENT PROFILES ========== -->
      <section class="screen" data-screen="profiles" id="screen-profiles">
        <div style="max-width:980px;margin:0 auto">
          <div class="rise" style="margin:10px 0 14px;display:flex;align-items:center;gap:14px">
            <h2 style="font-family:var(--font-d);font-weight:600;font-size:20px">Client profiles</h2>
            <p class="hint" style="margin:0">Branding + defaults applied to every build for a client.</p>
          </div>
          <div id="profiles-strip" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px"></div>

          <div id="profile-editor" style="max-width:980px;margin:0 auto">
          <div class="card rise" style="display:flex;overflow:hidden">
            <div style="width:320px;flex-shrink:0;padding:20px;overflow-y:auto;border-right:1px solid var(--edge)">
              <div class="eyebrow" style="margin-bottom:10px" id="pf-editing-label">new profile</div>
              <label class="lbl">Name</label>
              <input class="field" id="pf-name" style="margin-bottom:10px">
              <label class="lbl">Organisation override</label>
              <input class="field" id="pf-orgname" style="margin-bottom:10px">
              <label class="lbl">Default output target</label>
              <div class="seg" id="pf-target-seg" style="margin-bottom:10px">
                <div class="thumb"></div>
                <button class="on" data-val="intunewin">.intunewin</button>
                <button data-val="psadt">PSADT</button>
              </div>
              <label class="lbl">Logo image</label>
              <div style="display:flex;gap:8px;margin-bottom:10px">
                <input class="field mono" id="pf-logo" readonly style="flex:1;font-size:10.5px">
                <button class="btn sm" id="pf-logo-browse">Browse&hellip;</button>
              </div>
              <label class="lbl">Banner image</label>
              <div style="display:flex;gap:8px;margin-bottom:14px">
                <input class="field mono" id="pf-banner" readonly style="flex:1;font-size:10.5px">
                <button class="btn sm" id="pf-banner-browse">Browse&hellip;</button>
              </div>
              <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:14px">
                <button class="btn danger" id="pf-delete" style="display:none;margin-right:auto">Delete</button>
                <button class="btn" id="pf-cancel">Cancel</button>
                <button class="btn primary" id="pf-save">Save profile</button>
              </div>
            </div>

            <div style="flex:1;padding:20px;overflow-y:auto;background:var(--void);min-width:0">
              <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">
                <div class="eyebrow" style="margin:0">preview - what a real build with this profile looks like</div>
                <div class="seg" id="segPfSwap" style="transform:scale(.82);transform-origin:left center;margin-left:-6px">
                  <div class="thumb"></div>
                  <button class="on" data-val="v3">v3 classic</button>
                  <button data-val="v4">v4 fluent</button>
                </div>
              </div>
              <p class="hint" style="margin-bottom:12px">Click the logo, banner, or text below to edit that field directly - or use the fields on the left.</p>

              <div id="pf-preview-v3" style="border-radius:6px;overflow:hidden;background:#F0F0F0;border:1px solid #ACACAC;box-shadow:0 6px 20px rgba(0,0,0,.35);font-family:'Segoe UI',var(--font-b);max-width:380px">
                <div id="pf-v3-banner-wrap" class="pf-click-target" data-pf-click="pf-banner-browse" title="Click to set the banner image" style="width:100%;aspect-ratio:900/125;background:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden;border-bottom:1px solid #ACACAC;cursor:pointer">
                  <img id="pf-v3-banner" style="width:100%;height:100%;object-fit:cover;display:none">
                  <span id="pf-v3-banner-placeholder" style="font-size:10px;color:#888">Click to set a banner (900&times;125 recommended)</span>
                </div>
                <div style="padding:12px 14px;background:#F0F0F0">
                  <div class="pf-click-target" data-pf-click="pf-name" title="Click to edit the app name" style="font-weight:600;font-size:12.5px;color:#1a1a1a;cursor:pointer" id="pf-v3-title">Welcome to the Example App Setup</div>
                  <div style="font-size:10.5px;color:#444;margin-top:4px">Please close the following programs before continuing:</div>
                  <div style="background:#fff;border:1px solid #ACACAC;border-radius:2px;margin-top:6px;padding:5px 8px;font-size:10px;color:#333">Microsoft Word</div>
                  <div style="display:flex;gap:6px;margin-top:10px;justify-content:flex-end">
                    <div style="background:#E1E1E1;border:1px solid #ADADAD;border-radius:2px;padding:4px 12px;font-size:10.5px;color:#1a1a1a">Close &amp; Continue</div>
                  </div>
                </div>
              </div>

              <div id="pf-preview-v4" style="display:none;border-radius:12px;overflow:hidden;background:#202020;border:1px solid #3a3a3a;box-shadow:0 6px 24px rgba(0,0,0,.4);font-family:var(--font-b);max-width:380px">
                <div style="padding:20px 20px 16px;display:flex;gap:14px;align-items:flex-start">
                  <div id="pf-v4-icon-wrap" class="pf-click-target" data-pf-click="pf-logo-browse" title="Click to set the logo image" style="width:44px;height:44px;border-radius:10px;overflow:hidden;flex-shrink:0;background:#2d2d2d;display:grid;place-items:center;cursor:pointer">
                    <img id="pf-v4-icon" style="width:100%;height:100%;object-fit:cover;display:none">
                    <span id="pf-v4-icon-placeholder" style="font-size:8px;color:#999;text-align:center">logo</span>
                  </div>
                  <div style="min-width:0">
                    <div class="pf-click-target" data-pf-click="pf-name" title="Click to edit the app name" style="font-weight:600;font-size:14px;color:#fff;cursor:pointer" id="pf-v4-title">Example App</div>
                    <div class="pf-click-target" data-pf-click="pf-orgname" title="Click to edit the organisation name" style="font-size:11px;color:#a0a0a0;margin-top:2px;cursor:pointer" id="pf-v4-subtitle">Acme Corp - please close the following applications to continue.</div>
                  </div>
                </div>
                <div style="padding:0 20px 18px">
                  <div style="background:#2d2d2d;border-radius:6px;padding:8px 12px;font-size:11px;color:#ddd">Microsoft Word</div>
                  <div style="display:flex;gap:8px;margin-top:14px;justify-content:flex-end">
                    <div style="background:#0078D7;border-radius:5px;padding:6px 16px;font-size:11.5px;color:#fff;font-weight:600">Close apps &amp; install</div>
                  </div>
                </div>
              </div>
              <p class="hint" style="margin-top:10px" id="pf-no-assets-hint">Real PSADT stock assets aren't cached on this machine yet - build a PSADT package once and this preview will use the actual banner/icon as fallback.</p>
            </div>
          </div>
          </div>
        </div>
      </section>

      <!-- ========== HISTORY ========== -->
      <section class="screen" data-screen="history" id="screen-history">
        <div style="max-width:980px;margin:0 auto">
          <div class="rise" style="margin:10px 0 18px;display:flex;align-items:center;gap:14px">
            <h2 style="font-family:var(--font-d);font-weight:600;font-size:20px">History</h2>
            <span id="history-demo-badge" style="display:none;font-family:var(--font-m);font-size:10.5px;color:var(--warn);border:1px solid rgba(255,180,84,.35);background:rgba(255,180,84,.08);padding:3px 9px;border-radius:20px">example data - tour only</span>
            <p class="hint" style="margin:0">Every build, deploy-mark, and removal recorded on this machine, most recent first.</p>
          </div>
          <div class="card rise"><div class="card-b" style="padding-top:6px">
            <table class="fleet" id="history-table"></table>
            <div id="history-empty" style="display:none;text-align:center;padding:44px 20px">
              <svg viewBox="0 0 24 24" width="34" height="34" fill="none" stroke="var(--faint)" stroke-width="1.5" style="margin-bottom:14px">
                <path d="M3 3v5h5"/><path d="M3.05 13a9 9 0 1 0 2.13-7.83L3 8"/><path d="M12 7v5l4 2"/>
              </svg>
              <div style="font-family:var(--font-d);font-weight:600;font-size:15px;margin-bottom:6px">No history yet</div>
