          <div class="rise" style="margin:20px 0 12px"><div class="eyebrow">screen by screen</div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 12l9-8 9 8M5 10v10h5v-6h4v6h5V10"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">Home</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">Your fleet at a glance, and whether the Cloudflare worker is connected. "Build app package" starts a new package; the table below shows the last few tracked apps.</p>
            </div>
          </div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>
            </div>
            <div style="flex:1">
              <div class="card-t" style="margin-top:2px">Build</div>
              <div style="display:grid;gap:8px;margin-top:10px">
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">01</span><span style="font-size:13px;color:var(--dim)">Drop or browse to an installer (.exe/.msi) - version, publisher and silent args are detected automatically.</span></div>
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">02</span><span style="font-size:13px;color:var(--dim)">Confirm identity fields - registry name must match Add/Remove Programs exactly for detection to work.</span></div>
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">03</span><span style="font-size:13px;color:var(--dim)">Choose Runtime (auto-updates itself) or Simple, and an output target - .intunewin, or PSADT v3/v4/both.</span></div>
                <div style="display:flex;gap:10px;align-items:baseline"><span class="mono" style="color:var(--faint);font-size:11px;flex-shrink:0">04</span><span style="font-size:13px;color:var(--dim)">Review behaviour toggles, then Build.</span></div>
              </div>
            </div>
          </div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">App fleet</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">Every app tracked in your local manifest. "Rebuild" re-opens the builder pre-filled for that app; "Mark deployed" records that you've pushed it live (tracked locally by the shell, separate from the manifest itself).</p>
            </div>
          </div></div>

          <div class="card rise" style="margin-bottom:14px"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="7" height="7" rx="1.5"/><rect x="14" y="4" width="7" height="7" rx="1.5"/><rect x="3" y="15" width="7" height="7" rx="1.5"/><rect x="14" y="15" width="7" height="7" rx="1.5"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">Client profiles</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">A profile bundles a client's organisation name, logo/banner, and default output target so every build for that client is branded consistently. Pick one on the Build screen before building.</p>
            </div>
          </div></div>

          <div class="card rise"><div class="card-b" style="display:flex;gap:16px">
            <div style="width:34px;height:34px;border-radius:9px;background:var(--panel-2);border:1px solid var(--edge);display:grid;place-items:center;flex-shrink:0;color:var(--signal)">
              <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82"/></svg>
            </div>
            <div>
              <div class="card-t" style="margin-top:2px">Worker &amp; settings</div>
              <p style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.6">Connect to Cloudflare for auto-updates and a live status dashboard, or stay fully offline - packaging always works standalone. Recovery bundles back up your config/profiles/manifest with a passphrase; they restore only on the machine that made them.</p>
            </div>
          </div></div>

        </div>
      </section>

    </div>
    <div class="buildbar" id="buildbar" style="display:none">
      <div class="summary" id="build-summary">Select an installer to begin.</div>
      <button class="btn ghost" data-go="home">Cancel</button>
      <button class="btn primary big" id="btn-build" disabled>Build package&ensp;&#8250;</button>
    </div>
  </div>
</div>
<div class="toasts" id="toasts"></div>

<div id="tour-overlay">
  <div id="tour-spot"></div>
  <div id="tour-card">
    <div class="eyebrow" id="tour-step-count"></div>
    <div style="font-family:var(--font-d);font-weight:600;font-size:15px;margin:6px 0 8px" id="tour-title"></div>
    <p style="font-size:12.5px;color:var(--dim);margin-bottom:14px;line-height:1.5" id="tour-text"></p>
    <div id="tour-cf-choice" style="display:none;margin-bottom:14px">
      <div style="display:flex;gap:8px;margin-bottom:10px">
        <button class="btn primary sm" id="tour-cf-yes" style="flex:1">Set up now</button>
        <button class="btn sm" id="tour-cf-no" style="flex:1">Not now</button>
      </div>
      <label style="display:flex;align-items:center;gap:8px;font-size:11.5px;color:var(--dim);cursor:pointer">
        <input type="checkbox" id="tour-cf-keep-visible"> Keep these pages visible anyway
      </label>
    </div>
    <div style="display:flex;align-items:center;gap:8px" id="tour-nav-buttons">
      <button class="btn ghost sm" id="tour-skip">Skip tour</button>
      <div style="flex:1"></div>
      <button class="btn sm" id="tour-back">Back</button>
      <button class="btn primary sm" id="tour-next">Next</button>
    </div>
  </div>
</div>

<script>
  const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
  const bridge = window.chrome && window.chrome.webview;
  function send(action, payload) {
    if (bridge) bridge.postMessage({ action, payload });
    else console.warn('WebView2 bridge unavailable â€” running outside host?', action, payload);
  }
  // DevTools are disabled in production (AreDevToolsEnabled = $false), so an
  // uncaught exception anywhere in this script would otherwise be completely
  // silent - no console, no log, nothing - and could leave e.g. "Loadingâ€¦"
  // placeholders stuck forever if it fires before later setup code runs.
  // This is the only way to ever see what actually happened.
  window.addEventListener('error', e => {
    try { send('client-error', { message: e.message, stack: (e.error && e.error.stack) || '', source: e.filename + ':' + e.lineno }); } catch (_) {}
  });
  window.addEventListener('unhandledrejection', e => {
    try { send('client-error', { message: 'Unhandled promise rejection: ' + (e.reason && e.reason.message || e.reason), stack: (e.reason && e.reason.stack) || '' }); } catch (_) {}
  });

  /* ---------- toasts ---------- */
  function toast(title, msg, isErr) {
    const t = document.createElement('div');
    t.className = 'toast' + (isErr ? ' err' : '');
    t.innerHTML = `<b><i></i>${title}</b><p>${msg}</p><span class="life"></span>`;
    $('#toasts').appendChild(t);
    setTimeout(() => { t.classList.add('out'); setTimeout(() => t.remove(), 320); }, 4000);
  }

  /* ---------- segmented control w/ sliding thumb ---------- */
  function segInit(seg, onChange) {
    const th = seg.querySelector('.thumb'), btns = [...seg.querySelectorAll('button')];
    function place(b) { th.style.left = b.offsetLeft + 'px'; th.style.width = b.offsetWidth + 'px'; }
    btns.forEach(b => b.addEventListener('click', () => {
      btns.forEach(x => x.classList.remove('on')); b.classList.add('on'); place(b);
      onChange && onChange(b.dataset.val);
    }));
    requestAnimationFrame(() => place(seg.querySelector('button.on') || btns[0]));
    new ResizeObserver(() => place(seg.querySelector('button.on') || btns[0])).observe(seg);
  }

  /* ---------- pipeline rail ---------- */
  const pipeLabels = ['Source', 'Identity', 'Configure', 'Wrap', 'Deliver'];
  function renderPipe(activeIdx, doneUpTo, flowIdx) {
    const pipe = $('#pipe');
    if (activeIdx == null) { pipe.style.display = 'none'; return; }
    pipe.style.display = 'flex';
    pipe.innerHTML = pipeLabels.map((label, i) => {
      const st = i < doneUpTo ? 'done' : i === activeIdx ? 'live' : '';
      const flow = flowIdx === i ? ' flow' : '';
      const line = i < pipeLabels.length - 1 ? `<div class="pline${flow}"><i></i></div>` : '';
      return `<div class="pnode ${st}"><div class="pdot">${i + 1}<span class="tick"><svg viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg></span></div><span class="plabel">${label}</span></div>${line}`;
    }).join('');
  }

  /* ---------- custom title bar: drag, minimize, close ---------- */
  document.getElementById('drag-region').addEventListener('mousedown', (e) => {
    if (e.target.closest('#win-minimize, #win-close')) return;
    if (e.button !== 0) return;
    send('drag-window', {});
  });
  document.getElementById('win-minimize').addEventListener('click', () => send('minimize-window', {}));
  document.getElementById('win-close').addEventListener('click', () => send('close-window', {}));
  document.querySelector('.logo').addEventListener('click', function(){
    this.classList.remove('spin'); void this.offsetWidth; this.classList.add('spin');
  });

  const screens = ['home', 'build', 'progress', 'done', 'fleet', 'profiles', 'history', 'worker', 'accessibility', 'docs'];
  const crumbs = { home: 'AppUpdater', build: 'Package builder', progress: 'Building', done: 'Package ready', fleet: 'App fleet', profiles: 'Client profiles', history: 'History', worker: 'Worker & settings', accessibility: 'Accessibility', docs: 'Docs & help' };
  function goTo(id) {
    screens.forEach(s => $('#screen-' + s).classList.toggle('on', s === id));
    $$('.nav-btn[data-go]').forEach(b => b.classList.toggle('on', b.dataset.go === id || (['build','progress','done'].includes(id) && b.dataset.go === 'build')));
    $('#crumb').textContent = crumbs[id] || 'AppUpdater';
    $('#buildbar').style.display = (id === 'build') ? 'flex' : 'none';
    if (id === 'build') {
      renderPipe(0, inspected ? 2 : 0);
      // Skipped while the guided tour is active - the tour's own step text
      // already covers this, and this panel would render invisibly behind
      // the tour's dimming overlay (z-index below #tour-overlay) if shown here.
      if (!window._tourActive && !window._modeExplainerSeen && !window._modeExplainerShownThisSession) {
        window._modeExplainerShownThisSession = true;
        updateModeExplainerText();
        $('#mode-explainer').style.display = 'block';
      }
    }
    else if (id === 'progress') renderPipe(2, 2, 2);
    else if (id === 'done') renderPipe(4, 5);
    else renderPipe(null);
    if (id === 'fleet') send('get-fleet', {});
    if (id === 'profiles') { send('get-profiles', {}); if (!window._profileEditorInit) { window._profileEditorInit = true; openProfileEditor(null); } }
    if (id === 'history') send('get-history', {});
    if (id === 'worker') { send('get-config', {}); send('get-settings', {}); send('get-fleet', {}); }
  }
  document.addEventListener('click', e => { const g = e.target.closest('[data-go]'); if (g) goTo(g.dataset.go); });
  // Enter/Space activates any [data-go] element, including non-<button> ones
  // (e.g. the home build-CTA card, recent-activity rows) that only carry
  // role="button" tabindex="0" - native <button>s already get this for free
  // but handling it here too is harmless and keeps the logic in one place.
  document.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
      const g = e.target.closest('[data-go][role="button"]');
      if (g) { e.preventDefault(); goTo(g.dataset.go); return; }
    }
    if (e.key === 'Escape') {
      // Close whichever overlay/panel is currently open, most-specific first.
      const testModal = $('#test-modal');
      if (testModal && testModal.style.display !== 'none') { testModal.style.display = 'none'; return; }
      const drAdd = $('#driver-lib-add-panel');
      if (drAdd && drAdd.style.display === 'block') { drAdd.style.display = 'none'; return; }
      const ovPanel = $('#build-override-panel');
      if (ovPanel && ovPanel.style.display === 'block') { ovPanel.style.display = 'none'; window._overridePanelOpened = false; return; }
      const explainer = $('#mode-explainer');
      if (explainer && explainer.style.display === 'block') { explainer.style.display = 'none'; return; }
    }
  });

  /* ---------- form state (field names match Invoke-PackageBuilder / Export-PSADTPackage) ---------- */
  const form = { Kind: 'app', Mode: 'runtime', SimplePkgTarget: 'intunewin', PSADTVersion: 'v3', ProfileName: '', closeAppsOn: true, allowDefer: true, ProcessesToKill: '' };
  let inspected = false;

  segInit($('#segKind'), v => {
    form.Kind = v;
    $('#app-source-card').style.display = v === 'app' ? 'block' : 'none';
    $('#printer-source-card').style.display = v === 'printer' ? 'block' : 'none';
    $('#kindHint').textContent = v === 'app'
      ? 'Standard installer package - drop an exe or msi below.'
      : 'Deploys a printer/driver via native Windows printer cmdlets - no installer needed.';
    $('#btn-build').disabled = v === 'printer' ? !$('#f-printername').value.trim() : !inspected;
    if (v === 'printer' && !window._driverLibraryRequested) {
      window._driverLibraryRequested = true;
      send('get-driver-library', {});
    }
    updateSummary();
  });

  function renderDriverLibrary(drivers) {
    window._driverLibrary = drivers || [];
    const sel = $('#f-driverid');
    const prev = sel.value;
    sel.innerHTML = '<option value="">&mdash; none, use path below &mdash;</option>' + window._driverLibrary.map(d => {
      const noFiles = !d.HasFiles ? ' - driver files not yet supplied' : '';
      return `<option value="${d.DriverID}">${d.DisplayName}${d.Manufacturer ? ' Â· ' + d.Manufacturer : ''}${d.Architecture ? ' (' + d.Architecture + ')' : ''}${noFiles}</option>`;
    }).join('');
    if (window._driverLibrary.some(d => d.DriverID === prev)) sel.value = prev;
    updateDriverModelRow();
  }
  function updateDriverModelRow() {
    const d = (window._driverLibrary || []).find(x => x.DriverID === $('#f-driverid').value);
    const row = $('#driver-model-row');
    const modelSel = $('#f-drivermodel');
    if (d && Array.isArray(d.Models) && d.Models.length > 1) {
      modelSel.innerHTML = d.Models.map(m => `<option value="${m}">${m}</option>`).join('');
      row.style.display = 'block';
      $('#f-drivername').value = modelSel.value || d.DisplayName || '';
    } else {
      row.style.display = 'none';
      modelSel.innerHTML = '';
    }
  }
  $('#f-driverid').addEventListener('change', (e) => {
    const d = (window._driverLibrary || []).find(x => x.DriverID === e.target.value);
    updateDriverModelRow();
    if (d && !(Array.isArray(d.Models) && d.Models.length > 1)) $('#f-drivername').value = d.DisplayName || '';
  });
  $('#f-drivermodel').addEventListener('change', (e) => {
    $('#f-drivername').value = e.target.value;
  });
  $('#driver-lib-add-toggle').addEventListener('click', () => {
    const panel = $('#driver-lib-add-panel');
    panel.style.display = panel.style.display === 'block' ? 'none' : 'block';
    $('#dl-status').textContent = '';
  });
  $('#driver-lib-import-builtin').addEventListener('click', () => {
    $('#driver-lib-import-builtin').disabled = true;
    $('#builtin-import-status').textContent = 'Importing built-in driver families...';
    send('import-builtin-driver-families', {});
  });
  $('#dl-cancel').addEventListener('click', () => { $('#driver-lib-add-panel').style.display = 'none'; });
  $('#dl-save').addEventListener('click', () => {
    const driverId = $('#dl-id').value.trim();
    const displayName = $('#dl-displayname').value.trim();
    const source = $('#dl-source').value.trim();
    const inf = $('#dl-inf').value.trim();
    if (!driverId || !displayName || !source || !inf) {
      $('#dl-status').textContent = 'Driver ID, Display name, Source, and INF relative path are all required.';
      return;
    }
    $('#dl-save').disabled = true;
    $('#dl-status').textContent = 'Importing - downloading/verifying, this may take a moment...';
    send('add-driver-to-library', {
      driverId, displayName, sourcePath: source, infRelativePath: inf,
      manufacturer: $('#dl-manufacturer').value.trim(),
      driverType: $('#dl-drivertype').value.trim(),
      architecture: $('#dl-arch').value.trim(),
      expectedPublisher: $('#dl-publisher').value.trim(),
      version: $('#dl-version').value.trim(),
      models: $('#dl-models').value.split('\n').map(m => m.trim()).filter(m => m)
    });
  });
  ['f-printername', 'f-drivername', 'f-porthost'].forEach(id => {
    $('#' + id).addEventListener('input', () => {
      if (form.Kind === 'printer') $('#btn-build').disabled = !$('#f-printername').value.trim();
    });
  });

  $('#mode-explainer-toggle').addEventListener('click', () => {
    const el = $('#mode-explainer');
    el.style.display = el.style.display === 'block' ? 'none' : 'block';
  });
  $('#mode-explainer-dismiss').addEventListener('click', () => {
    $('#mode-explainer').style.display = 'none';
    if (!window._modeExplainerSeen) {
      window._modeExplainerSeen = true;
      send('mark-mode-explainer-seen', {});
    }
  });
  // Explains whichever mode/target is CURRENTLY selected, not a generic
  // combined blurb - reads live from `form` so it's accurate whenever shown.
  function updateModeExplainerText() {
    const modeText = form.Mode === 'runtime'
      ? '<b>AppUpdater Runtime</b> (selected) installs the app plus a small background task that keeps checking for new versions and updates it automatically - "set it and forget it".'
      : '<b>Simple Package</b> (selected) just installs the app once, nothing extra - use this when something else (e.g. Intune\'s own update detection) will handle updates instead.';
    const targetText = form.SimplePkgTarget === 'psadt'
      ? '<b>PSADT package</b> (selected) wraps the install with PSAppDeployToolkit, adding a branded "please close these apps" prompt and the option to let users defer.'
      : '<b>.intunewin</b> (selected) packages straight for Intune Win32 upload as-is, with no extra install-time prompts.';
    $('#mode-explainer-text').innerHTML = modeText + '<br><br>' + targetText;
  }
  // Guides the user to the explainer each time they change mode/target - until
  // they permanently dismiss it via "Got it, stop guiding me". Never fires
  // during the guided tour (tour already explains this via its own steps).
  function guideToModeExplainer() {
    updateModeExplainerText();
    if (!window._tourActive && !window._modeExplainerSeen) {
      window._modeExplainerShownThisSession = true;
      $('#mode-explainer').style.display = 'block';
    }
  }
  segInit($('#segMode'), v => {
    form.Mode = v;
    $('#modeHint').textContent = v === 'runtime'
      ? 'Installs auto-update task, scripts and desktop shortcut on every device.'
      : 'Installs the app directly with no AppUpdater runtime or auto-update task.';
    updateSummary();
    guideToModeExplainer();
  });
  segInit($('#segTarget'), v => {
    form.SimplePkgTarget = v;
    $('#targetHint').textContent = v === 'intunewin'
      ? 'Package for Intune Win32 app upload.'
      : 'Wrap with PSAppDeployToolkit for enterprise close-apps prompts.';
    $('#psadt-version-row').style.display = v === 'psadt' ? 'block' : 'none';
    $('#bp-header').style.display = v === 'psadt' ? 'flex' : 'none';
    // Panel itself stays collapsed by default (toggled via #bp-disclosure) so
    // picking PSADT output doesn't by itself push the build screen taller.
    $('#bp-panel').style.display = (v === 'psadt' && window._bpExpanded) ? 'block' : 'none';
    if (v === 'psadt') updateBuildBrandingPreview();
    updateSummary();
    guideToModeExplainer();
  });
  segInit($('#segPsadtVersion'), v => { form.PSADTVersion = v; updateBuildBrandingPreview(); });
  segInit($('#segBpSwap'), v => { window._bpSwapVersion = v; updateBuildBrandingPreview(); });
  $('#bp-disclosure').addEventListener('click', () => {
    window._bpExpanded = !window._bpExpanded;
    $('#bp-disclosure').classList.toggle('open', window._bpExpanded);
    $('#bp-panel').style.display = window._bpExpanded ? 'block' : 'none';
    if (window._bpExpanded) updateBuildBrandingPreview();
  });

  $('#f-profile').addEventListener('change', (e) => {
    form.ProfileName = e.target.value;
    $('#build-override-toggle').style.display = form.ProfileName ? 'inline-flex' : 'none';
    $('#build-override-panel').style.display = 'none';
    window._overridePanelOpened = false;
    updateSummary();
    refreshBuildProfileImage();
  });
  $('#build-new-profile').addEventListener('click', () => {
    window._returnToBuildAfterProfile = true;
    goTo('profiles');
    openProfileEditor(null);
  });
  $('#build-override-toggle').addEventListener('click', () => {
    const panel = $('#build-override-panel');
    const opening = panel.style.display !== 'block';
    panel.style.display = opening ? 'block' : 'none';
    if (opening) {
      const p = (window._profiles || []).find(pp => pp.Name === form.ProfileName);
      $('#ov-orgname').value = (p && p.OrgName) || '';
      $('#ov-logo').value = (p && p.LogoImagePath) || '';
      $('#ov-banner').value = (p && p.BannerImagePath) || '';
      window._overridePanelOpened = true;
    } else {
      // Closed without building - the "offer to save" prompt on build-done
      // should only fire for an override that was actually staged/applied.
      window._overridePanelOpened = false;
    }
  });
  $('#ov-logo-browse').addEventListener('click', () => send('browse-image', { field: 'ov-logo' }));
  $('#ov-banner-browse').addEventListener('click', () => send('browse-image', { field: 'ov-banner' }));
  $('#ov-orgname').addEventListener('input', updateBuildBrandingPreview);
  function refreshBuildProfileImage() {
    const p = (window._profiles || []).find(p => p.Name === form.ProfileName);
    if (p && p.LogoImagePath) send('get-image-preview', { field: 'bp-logo', path: p.LogoImagePath });
    else setImagePreview('bp-logo', null);
    if (p && p.BannerImagePath) send('get-image-preview', { field: 'bp-banner', path: p.BannerImagePath });
    else setImagePreview('bp-banner', null);
    updateBuildBrandingPreview();
  }
  function resolveBuildOrgName() {
    const p = (window._profiles || []).find(p => p.Name === form.ProfileName);
    const overrideOrg = window._overridePanelOpened ? $('#ov-orgname').value.trim() : '';
    return (overrideOrg || (p && p.OrgName) || window._defaultOrgName || '').trim();
  }
  function updateBuildBrandingPreview() {
    const appName = $('#f-displayname').value.trim() || 'this app';
    const org = resolveBuildOrgName();
    const showSwap = form.PSADTVersion === 'both';
    $('#segBpSwap').style.display = showSwap ? 'inline-flex' : 'none';
    const shown = showSwap ? (window._bpSwapVersion || 'v3') : (form.PSADTVersion === 'v4' ? 'v4' : 'v3');
    $('[data-version-label]').textContent = `Preview branding (PSADT ${shown})`;
    $('#bp-preview-v3').style.display = shown === 'v3' ? 'block' : 'none';
    $('#bp-preview-v4').style.display = shown === 'v4' ? 'block' : 'none';

    const stock = window._psadtStockAssets;
    $('#bp-no-assets-hint').style.display = stock ? 'none' : 'block';
    const bannerSrc = window._bpBannerDataUrl || (stock && stock.banner) || '';
    const iconSrc = window._bpLogoDataUrl || (stock && stock.icon) || '';
    $('#bp-v3-banner').src = bannerSrc;
    $('#bp-v3-banner-wrap').style.opacity = bannerSrc ? '1' : '.15';
    $('#bp-v4-icon').src = iconSrc;
    $('#bp-v4-icon-wrap').style.opacity = iconSrc ? '1' : '.4';

    $('#bp-v3-title').textContent = `Welcome to the ${appName} Setup`;
    $('#bp-v4-title').textContent = org ? `${appName}` : appName;
    $('#bp-v4-subtitle').textContent = org ? `${org} - please close the following applications to continue.` : 'Please close the following applications to continue.';
  }
  $('#f-displayname').addEventListener('input', updateBuildBrandingPreview);

  $$('.tgl').forEach(btn => btn.addEventListener('click', () => {
    const key = btn.dataset.val;
    form[key] = !form[key];
    btn.classList.toggle('on', form[key]);
  }));

  ['f-displayname','f-appid','f-registryname'].forEach(id => $('#' + id).addEventListener('input', updateSummary));

  $('#drop').addEventListener('click', () => send('browse-installer', {}));
  $('#reDrop').addEventListener('click', e => { e.stopPropagation(); resetInstaller(); });

  function resetInstaller() {
    inspected = false; window._selectedInstaller = null;
    $('#inspect').style.display = 'none'; $('#drop').style.display = 'block';
    $('#btn-build').disabled = true;
    if ($('#screen-build').classList.contains('on')) renderPipe(0, 0);
    updateSummary();
  }

  function updateSummary() {
    const mode = form.Mode === 'runtime' ? '<b>AppUpdater Runtime</b>' : '<b>Simple Package</b>';
    const target = form.SimplePkgTarget === 'intunewin' ? '.intunewin' : 'PSADT package';
    const org = resolveBuildOrgName();
    let name;
    if (form.Kind === 'printer') {
      name = $('#f-printername').value.trim();
      if (!name) { $('#build-summary').textContent = 'Enter a printer name to begin.'; return; }
    } else {
      name = window._selectedInstaller ? window._selectedInstaller.split(/[\\/]/).pop() : null;
      if (!name) { $('#build-summary').textContent = 'Select an installer to begin.'; return; }
    }
    const parts = [name, mode, org ? `${org} branding` : null, `&#8594; ${target}`].filter(Boolean);
    $('#build-summary').innerHTML = parts.join('<span class="sep">&middot;</span>');
  }

  $('#progress-error-back').addEventListener('click', () => goTo('build'));
  $('#btn-build').addEventListener('click', () => {
    if (form.Kind === 'printer') {
      if (!$('#f-printername').value.trim()) { toast('Missing printer name', 'Fill in the printer name first'); return; }
      const driverId = $('#f-driverid').value.trim();
      if (driverId) {
        const libEntry = (window._driverLibrary || []).find(x => x.DriverID === driverId);
        if (libEntry && !libEntry.HasFiles) {
          toast('Driver files not yet supplied', `"${libEntry.DisplayName}" is metadata only - add the real driver package via "+ Add driver to library" first, or pick a different driver.`);
          return;
        }
      } else if (!$('#f-driversourcepath').value.trim() || !$('#f-driverinf').value.trim()) {
        toast('Missing driver', 'Pick a driver from the library, or fill in a driver source path and INF below');
        return;
      }
    } else if (!inspected) {
      toast('No installer', 'Drop or browse to an installer first'); return;
    }
    goTo('progress');
    $('#log').innerHTML = '';
    $('#progress-bar').style.width = '0%';
    $('#progress-title').textContent = $('#f-displayname').value || $('#f-printername').value || 'Package';
    $('#step-list').innerHTML = '';
    $('#progress-error').style.display = 'none';
    const payload = {
      AppID: $('#f-appid').value,
      DisplayName: $('#f-displayname').value,
      PackageKind: form.Kind === 'printer' ? 'Printer' : 'App',
      Mode: form.Mode,
      SimplePkgTarget: form.SimplePkgTarget,
      PSADTVersion: form.PSADTVersion,
      ProfileName: form.ProfileName,
      OverrideOrgName: window._overridePanelOpened ? $('#ov-orgname').value.trim() : '',
      OverrideLogoImagePath: window._overridePanelOpened ? $('#ov-logo').value.trim() : '',
      OverrideBannerImagePath: window._overridePanelOpened ? $('#ov-banner').value.trim() : ''
    };
    if (form.Kind === 'printer') {
      Object.assign(payload, {
        AppID: payload.AppID || $('#f-printername').value.trim().replace(/[^A-Za-z0-9._-]/g, ''),
        DisplayName: payload.DisplayName || $('#f-printername').value.trim(),
        PrinterName: $('#f-printername').value.trim(),
        DriverName: $('#f-drivername').value.trim(),
        DriverID: $('#f-driverid').value.trim(),
        DriverSourcePath: $('#f-driversourcepath').value.trim(),
        DriverInfRelativePath: $('#f-driverinf').value.trim(),
        ExpectedDriverPublisher: $('#f-driverpublisher').value.trim(),
        Location: $('#f-printerlocation').value.trim(),
        PortHostAddress: $('#f-porthost').value.trim(),
        PortNumber: $('#f-portnumber').value.trim()
      });
    } else {
      Object.assign(payload, {
        RegistryName: $('#f-registryname').value,
        InstallerPath: window._selectedInstaller,
        ProcessesToKill: form.closeAppsOn ? form.ProcessesToKill : '',
        ExpectedPublisher: ''
      });
    }
    send('build-package', payload);
  });

  /* ---------- host bridge messages ---------- */
  if (bridge) {
    bridge.addEventListener('message', (e) => {
      const { type, payload } = e.data;
      switch (type) {
        case 'browse-installer-result':
          if (payload.ok) {
            window._selectedInstaller = payload.path;
            inspected = true;
            const base = payload.path.split(/[\\/]/).pop();
            const stem = base.replace(/\.(exe|msi)$/i, '');
            const ext = (base.match(/\.(exe|msi)$/i) || ['', 'exe'])[1].toUpperCase();
            $('#drop').style.display = 'none';
            $('#inspect').style.display = 'block';
            $('#inspect-ext').textContent = ext;
            $('#inspect-name').textContent = base;
            $('#inspect-sub').textContent = payload.detected ? payload.detected.summary || '' : 'Inspectingâ€¦';
            $('#inspect-chips').innerHTML = (payload.detected && payload.detected.chips || []).map(c =>
              `<span class="chip ${c.tone||''}"><i></i>${c.label}</span>`).join('');
            if (!$('#f-appid').value) $('#f-appid').value = (payload.detected && payload.detected.appId) || stem.replace(/[^A-Za-z0-9._-]/g, '');
            if (!$('#f-displayname').value) $('#f-displayname').value = (payload.detected && payload.detected.displayName) || stem;
            if (!$('#f-registryname').value) $('#f-registryname').value = (payload.detected && payload.detected.registryName) || $('#f-displayname').value;
            form.ProcessesToKill = (payload.detected && payload.detected.processesToKill) || '';
            $('#close-apps-hint').textContent = form.ProcessesToKill || 'No blocking process detected';
            $('#btn-build').disabled = false;
            renderPipe(0, 2);
            updateSummary();
            toast('Installer inspected', payload.detected ? 'Details pre-filled from the installer' : 'Fill in the identity fields to continue');
          }
          break;
        case 'history-data':
          window._realHistoryEvents = payload.events || [];
          renderHistory(payload.events);
          renderRecentActivity(payload.events);
          break;
        case 'fleet-data':
          window._gotFleetData = true;
          window._workerUrl = payload.workerUrl;
          renderFleet(payload.apps);
          resetWorkerOptionsButtons();
          break;
        case 'driver-library-data':
          renderDriverLibrary(payload.drivers);
          break;
        case 'driver-added':
          $('#dl-save').disabled = false;
          if (payload.ok) {
            $('#dl-status').textContent = '';
            $('#driver-lib-add-panel').style.display = 'none';
            ['dl-id','dl-displayname','dl-manufacturer','dl-drivertype','dl-arch','dl-version','dl-source','dl-inf','dl-publisher','dl-models']
              .forEach(id => { $('#' + id).value = ''; });
            send('get-driver-library', {});
            toast('Driver added', (payload.entry && payload.entry.DisplayName) + ' is now in the library');
          } else {
            $('#dl-status').textContent = payload.message || 'Import failed.';
          }
          break;
        case 'builtin-families-imported':
          $('#driver-lib-import-builtin').disabled = false;
          $('#builtin-import-status').textContent = payload.ok
            ? `Done - ${payload.added} added, ${payload.updated} already present (${payload.total} total). Driver files still need supplying via "+ Add driver to library" before a build can use them.`
            : (payload.message || 'Import failed.');
          break;
        case 'config-data':
          window._defaultOrgName = payload.orgName || '';
          renderOrgNameSettingsSelect();
          updateBuildBrandingPreview();
          updateSummary();
          resetWorkerOptionsButtons();
          break;
        case 'build-progress': {
          const [stepNum] = String(payload.step).split('/').map(Number);
          const total = 5;
          $('#progress-bar').style.width = `${Math.min(100, (stepNum / total) * 100)}%`;
          renderStepList(payload.step, payload.label);
          logLine(payload.label, 'ac');
          break;
        }
        case 'build-log':
          logLine(payload.line, 'in');
          break;
        case 'build-done':
          $('#progress-bar').style.width = '100%';
          $('#done-path').textContent = payload.path || '';
          renderDoneSheet(payload);
          goTo('done');
          toast('Package ready', 'Built â€” check the output folder or view it in the fleet');
          if (window._overridePanelOpened && form.ProfileName) {
            const ovP = (window._profiles || []).find(pp => pp.Name === form.ProfileName);
            if (ovP) {
              const newOrg = $('#ov-orgname').value.trim();
              const newLogo = $('#ov-logo').value.trim();
              const newBanner = $('#ov-banner').value.trim();
              const changed = newOrg !== (ovP.OrgName || '') || newLogo !== (ovP.LogoImagePath || '') || newBanner !== (ovP.BannerImagePath || '');
              if (changed && confirm('Save these overridden fields to the "' + ovP.Name + '" profile for future builds?')) {
                send('save-profile', { Name: ovP.Name, OrgName: newOrg, LogoImagePath: newLogo, BannerImagePath: newBanner, DefaultTarget: ovP.DefaultTarget || 'intunewin' });
              }
            }
            window._overridePanelOpened = false;
          }
          resetInstaller();
          break;
        case 'error':
          toast('Something went wrong', payload.message, true);
          resetWorkerOptionsButtons();
          if ($('#screen-progress').classList.contains('on')) {
            $('#progress-error-msg').textContent = payload.message || 'Unknown error.';
            $('#progress-error').style.display = 'block';
          }
          break;
        case 'profiles-data':
          window._profiles = payload.profiles || [];
          window._lastUsedProfile = payload.lastUsed;
          renderProfiles(payload.profiles || [], payload.lastUsed);
          renderOrgNameSettingsSelect();
          if (payload.saveOk === false) toast('Save failed', 'Could not write profiles.json', true);
          else if (payload.saveOk === true) {
            toast('Profile saved', '');
            if (window._returnToBuildAfterProfile) {
              window._returnToBuildAfterProfile = false;
              const savedName = window._lastSavedProfileName;
              goTo('build');
              if (savedName) {
                form.ProfileName = savedName;
                $('#f-profile').value = savedName;
                $('#build-override-toggle').style.display = 'inline-flex';
                refreshBuildProfileImage();
                updateSummary();
              }
            }
          }
          renderGettingStarted();
          break;
        case 'browse-image-result':
          if (payload.ok) {
            $('#' + payload.field).value = payload.path;
            setImagePreview(payload.field, payload.dataUrl);
            if (payload.field === 'ov-logo') { window._bpLogoDataUrl = payload.dataUrl; updateBuildBrandingPreview(); }
            else if (payload.field === 'ov-banner') { window._bpBannerDataUrl = payload.dataUrl; updateBuildBrandingPreview(); }
          }
          break;
        case 'image-preview-result':
          if (payload.field === 'bp-logo') { window._bpLogoDataUrl = payload.dataUrl; updateBuildBrandingPreview(); }
          else if (payload.field === 'bp-banner') { window._bpBannerDataUrl = payload.dataUrl; updateBuildBrandingPreview(); }
          else if (payload.field === 'pf-logo') { window._pfLogoDataUrl = payload.dataUrl; updateProfilePreview(); }
          else if (payload.field === 'pf-banner') { window._pfBannerDataUrl = payload.dataUrl; updateProfilePreview(); }
          else setImagePreview(payload.field, payload.dataUrl);
          break;
        case 'psadt-stock-assets':
          window._psadtStockAssets = payload.ok ? { banner: payload.banner, icon: payload.icon } : null;
          updateProfilePreview();
          updateBuildBrandingPreview();
          break;
        case 'settings-data':
          window._defaultOrgName = payload.orgName || '';
          renderOrgNameSettingsSelect();
          window._modeExplainerSeen = !!payload.modeExplainerSeen;
          updateBuildBrandingPreview();
          updateSummary();
          $('#tgl-reduce-motion').classList.toggle('on', !!payload.reduceMotion);
          document.body.classList.toggle('reduce-motion', !!payload.reduceMotion);
          $('#tgl-high-contrast').classList.toggle('on', !!payload.highContrast);
          document.body.classList.toggle('high-contrast', !!payload.highContrast);
          $('#tgl-colorblind').classList.toggle('on', !!payload.colorblindSafe);
          document.body.classList.toggle('colorblind-safe', !!payload.colorblindSafe);
          $('#tgl-release-check').classList.toggle('on', !!payload.releaseCheckEnabled);
          $('#tgl-cf-advert').classList.toggle('on', payload.showCloudflareAdvert !== false);
          window._showCfAdvert = payload.showCloudflareAdvert !== false;
          $('#tgl-getting-started').classList.toggle('on', payload.showGettingStarted !== false);
          window._showGettingStarted = payload.showGettingStarted !== false;
          $('#tgl-cf-nav').classList.toggle('on', payload.showCloudflareNav !== false);
          window._showCfNav = payload.showCloudflareNav !== false;
          applyCfNavVisibility();
          renderFleet(lastFleet);
          renderGettingStarted();
          if (!payload.onboardingSeen && !window._tourAutoStarted) {
            window._tourAutoStarted = true;
            setTimeout(startTour, 600);
          }
          $('#settings-version').textContent = 'AppUpdater v' + payload.version + ' - BUSL-1.1';
          $('#settings-release').textContent = payload.releaseInfo || '';
          
          if (payload.newerAvailable && !sessionStorage.getItem('releaseBannerDismissed')) {
            $('#release-banner-text').textContent = 'v' + payload.latestVersion + ' is available on GitHub';
            $('#release-banner').style.display = 'flex';
          }
          break;
        case 'settings-saved':
          if (!payload.ok) toast('Save failed', 'Could not write the config file.', true);
          break;
        case 'recovery-export-result':
          toast(payload.ok ? 'Bundle exported' : 'Export failed', payload.ok ? payload.path : 'Bundle could not be written.', !payload.ok);
          break;
        case 'recovery-import-result':
          toast(payload.ok ? 'Restored' : 'Restore failed', payload.ok ? 'Restart AppUpdater for everything to reload cleanly.' : payload.message, !payload.ok);
          break;
        case 'remove-from-fleet-result':
          if (payload.cancelled) { /* user cancelled the delete-choice dialog, nothing to report */ }
          else if (payload.ok) toast('Removed', payload.everything ? 'Manifest entry and local machine artifacts removed.' : 'Manifest entry removed.');
          else toast('Remove failed', payload.message || 'Could not update the manifest.', true);
          break;
        case 'test-log':
          if (payload.line) logTestLine(payload.line);
          if (payload.done) logTestLine(payload.ok ? '\u2713 Done' : '\u2717 Failed', payload.ok ? 'ok' : 'wr');
          break;
      }
    });
  }

  /* ---------- client profiles ---------- */
  function renderProfiles(profiles, lastUsed) {
    const grid = $('#profiles-strip');
    const sel = $('#f-profile');
    sel.innerHTML = '<option value="">Default (uses Settings organisation name)</option>' +
      profiles.map(function(p){ return '<option value="' + p.Name + '">' + p.Name + '</option>'; }).join('');
    // Compact chip strip - clicking a chip loads that profile straight into
    // the builder below, which is always visible on this screen.
    grid.innerHTML = profiles.map(function(p){
      var active = p.Name === editingProfile ? ' style="border-color:var(--signal);color:var(--signal)"' : '';
      return '<button class="btn sm" data-edit-profile="' + p.Name + '"' + active + '>' + p.Name +
        (p.Name === lastUsed ? ' <span style="color:var(--faint);font-size:10px">&middot; last used</span>' : '') + '</button>';
    }).join('') +
      '<button class="btn sm primary" id="new-profile-card">+ New profile</button>';
  }
  // Default-org select on Worker & Settings is backed by Client Profiles -
  // picking one copies that profile's org name in as the fallback used when
  // a build has no profile selected. Preserves a legacy/custom value (typed
  // before this was profile-backed) as its own option so it isn't silently lost.
  function renderOrgNameSettingsSelect() {
    const sel = $('#f-orgname-settings');
    if (!sel) return;
    const current = window._defaultOrgName || '';
    const profiles = window._profiles || [];
    let html = '<option value="">Not set</option>' +
      profiles.map(function(p){ return '<option value="' + p.OrgName + '">' + p.Name + ' (' + (p.OrgName || 'no org name set') + ')</option>'; }).join('');
    if (current && !profiles.some(function(p){ return p.OrgName === current; })) {
      html += '<option value="' + current + '">' + current + ' (custom)</option>';
    }
    sel.innerHTML = html;
    sel.value = current;
    $('#f-orgname-not-set-hint').style.display = current ? 'none' : 'block';
  }

  var editingProfile = null;
  function setImagePreview(field, dataUrl) {
    var img = $('#' + field + '-preview'), placeholder = $('#' + field + '-placeholder');
    if (!img) return;
    if (dataUrl) { img.src = dataUrl; img.style.display = 'block'; if (placeholder) placeholder.style.display = 'none'; }
    else { img.style.display = 'none'; img.removeAttribute('src'); if (placeholder) placeholder.style.display = ''; }
  }
  function openProfileEditor(p) {
    editingProfile = p ? p.Name : null;
    $('#pf-editing-label').textContent = p ? 'editing: ' + p.Name : 'new profile';
    $('#pf-delete').style.display = p ? 'inline-flex' : 'none';
    $('#pf-name').value = p ? p.Name : '';
    $('#pf-name').disabled = !!p;
    $('#pf-orgname').value = p ? p.OrgName || '' : '';
    $('#pf-logo').value = p ? p.LogoImagePath || '' : '';
    $('#pf-banner').value = p ? p.BannerImagePath || '' : '';
    var target = p ? p.DefaultTarget || 'intunewin' : 'intunewin';
    $$('#pf-target-seg button').forEach(function(b){ b.classList.toggle('on', b.dataset.val === target); });
    window._pfLogoDataUrl = null;
    window._pfBannerDataUrl = null;
    if (p && p.LogoImagePath) send('get-image-preview', { field: 'pf-logo', path: p.LogoImagePath });
    if (p && p.BannerImagePath) send('get-image-preview', { field: 'pf-banner', path: p.BannerImagePath });
    updateProfilePreview();
    renderProfiles(window._profiles || [], window._lastUsedProfile);
  }
  // Renders the branding preview for the profile editor.
  function updateProfilePreview() {
    const name = $('#pf-name').value.trim() || 'Example App';
    const org = $('#pf-orgname').value.trim() || 'Acme Corp';
    const shown = window._pfSwapVersion || 'v3';
    $('#pf-preview-v3').style.display = shown === 'v3' ? 'block' : 'none';
    $('#pf-preview-v4').style.display = shown === 'v4' ? 'block' : 'none';
    $('#pf-v3-title').textContent = `Welcome to the ${name} Setup`;
    $('#pf-v4-title').textContent = name;
    $('#pf-v4-subtitle').textContent = `${org} - please close the following applications to continue.`;

    const stock = window._psadtStockAssets;
    $('#pf-no-assets-hint').style.display = stock ? 'none' : 'block';
    const bannerSrc = window._pfBannerDataUrl || (stock && stock.banner) || '';
    const iconSrc = window._pfLogoDataUrl || (stock && stock.icon) || '';
    $('#pf-v3-banner').style.display = bannerSrc ? 'block' : 'none';
    $('#pf-v3-banner-placeholder').style.display = bannerSrc ? 'none' : 'block';
    if (bannerSrc) $('#pf-v3-banner').src = bannerSrc;
    $('#pf-v4-icon').style.display = iconSrc ? 'block' : 'none';
    $('#pf-v4-icon-placeholder').style.display = iconSrc ? 'none' : 'block';
    if (iconSrc) $('#pf-v4-icon').src = iconSrc;
  }
  $('#pf-name').addEventListener('input', updateProfilePreview);
  $('#pf-orgname').addEventListener('input', updateProfilePreview);
  segInit($('#segPfSwap'), v => { window._pfSwapVersion = v; updateProfilePreview(); });
  document.addEventListener('click', function(e) {
    const clk = e.target.closest('.pf-click-target');
    if (!clk) return;
    const targetId = clk.dataset.pfClick;
    const btn = $('#' + targetId);
    if (!btn) return;
    if (targetId === 'pf-logo-browse' || targetId === 'pf-banner-browse') btn.click();
    else { btn.focus(); btn.select && btn.select(); }
  });
  function closeProfileEditor() { openProfileEditor(null); }
  document.addEventListener('click', function(e) {
    if (e.target.closest('#new-profile-card')) openProfileEditor(null);
    var editBtn = e.target.closest('[data-edit-profile]');
    if (editBtn) openProfileEditor((window._profiles || []).find(function(p){ return p.Name === editBtn.dataset.editProfile; }));
    if (e.target.id === 'pf-delete' && editingProfile && confirm('Delete profile "' + editingProfile + '"?')) {
      send('delete-profile', { name: editingProfile });
      closeProfileEditor();
    }
    if (e.target.id === 'pf-cancel') {
      closeProfileEditor();
      if (window._returnToBuildAfterProfile) { window._returnToBuildAfterProfile = false; goTo('build'); }
    }
    if (e.target.id === 'pf-logo-browse') send('browse-image', { field: 'pf-logo' });
    if (e.target.id === 'pf-banner-browse') send('browse-image', { field: 'pf-banner' });
  });
  segInit($('#pf-target-seg'), function(){});
  $('#pf-save').addEventListener('click', function() {
    var name = $('#pf-name').value.trim();
    if (!name) { toast('Name required', 'Give the profile a name first.'); return; }
    var onBtn = $('#pf-target-seg button.on');
    window._lastSavedProfileName = name;
    send('save-profile', {
      Name: name, OrgName: $('#pf-orgname').value,
      LogoImagePath: $('#pf-logo').value, BannerImagePath: $('#pf-banner').value,
      DefaultTarget: onBtn ? onBtn.dataset.val : 'intunewin'
    });
  });

  /* ---------- settings: everything auto-saves the instant it changes ---------- */
  function saveSettingsNow() {
    send('save-settings', {
      orgName: $('#f-orgname-settings').value,
      reduceMotion: $('#tgl-reduce-motion').classList.contains('on'),
      highContrast: $('#tgl-high-contrast').classList.contains('on'),
      colorblindSafe: $('#tgl-colorblind').classList.contains('on'),
      releaseCheckEnabled: $('#tgl-release-check').classList.contains('on'),
      showCloudflareAdvert: $('#tgl-cf-advert').classList.contains('on'),
      showGettingStarted: $('#tgl-getting-started').classList.contains('on'),
      showCloudflareNav: $('#tgl-cf-nav').classList.contains('on')
    });
  }
  // Returns 0 when reduced motion is on, otherwise the given delay.
  function motionMs(ms) { return document.body.classList.contains('reduce-motion') ? 0 : ms; }
  function flashSaved() {
    var el = $('#settings-saved-flash');
    if (!el) return;
    el.style.opacity = '1';
    clearTimeout(el._t);
    el._t = setTimeout(function(){ el.style.opacity = '0'; }, 1400);
  }
  $('#tgl-reduce-motion').addEventListener('click', function(){
    $('#tgl-reduce-motion').classList.toggle('on');
    document.body.classList.toggle('reduce-motion', $('#tgl-reduce-motion').classList.contains('on'));
    saveSettingsNow(); flashSaved();
  });
  $('#tgl-high-contrast').addEventListener('click', function(){
    $('#tgl-high-contrast').classList.toggle('on');
    document.body.classList.toggle('high-contrast', $('#tgl-high-contrast').classList.contains('on'));
    saveSettingsNow(); flashSaved();
  });
  $('#tgl-colorblind').addEventListener('click', function(){
    $('#tgl-colorblind').classList.toggle('on');
    document.body.classList.toggle('colorblind-safe', $('#tgl-colorblind').classList.contains('on'));
    saveSettingsNow(); flashSaved();
  });
  $('#tgl-release-check').addEventListener('click', function(){ $('#tgl-release-check').classList.toggle('on'); saveSettingsNow(); flashSaved(); });
  $('#tgl-cf-advert').addEventListener('click', function(){
    $('#tgl-cf-advert').classList.toggle('on');
    window._showCfAdvert = $('#tgl-cf-advert').classList.contains('on');
    saveSettingsNow(); flashSaved(); renderFleet(lastFleet);
  });
  $('#tgl-getting-started').addEventListener('click', function(){
    $('#tgl-getting-started').classList.toggle('on');
    window._showGettingStarted = $('#tgl-getting-started').classList.contains('on');
    saveSettingsNow(); flashSaved(); renderGettingStarted();
  });
  $('#f-orgname-settings').addEventListener('change', function(){
    window._defaultOrgName = this.value;
    send('set-org-name', { orgName: this.value });
    $('#f-orgname-not-set-hint').style.display = this.value ? 'none' : 'block';
    flashSaved();
    updateBuildBrandingPreview();
    updateSummary();
  });
  $('#f-orgname-guide-btn').addEventListener('click', () => showProfileGuide());
  $('#btn-open-output').addEventListener('click', function(){ send('open-folder', { which: 'output' }); });
  $('#btn-open-cache').addEventListener('click', function(){ send('open-folder', { which: 'cache' }); });
  $('#btn-open-log').addEventListener('click', function(){ send('open-folder', { which: 'log' }); });
  $('#btn-open-github').addEventListener('click', function(){ send('open-github-releases', {}); });
  var docsGithub = $('#docs-github-link');
  if (docsGithub) docsGithub.addEventListener('click', function(){ send('open-github-releases', {}); });
  $('#btn-export-recovery').addEventListener('click', function(){ send('export-recovery-bundle', {}); });
  $('#btn-import-recovery').addEventListener('click', function(){
    if (confirm('Import a recovery bundle? This replaces your current config, profiles, and manifest â€” it cannot be undone.')) send('import-recovery-bundle', {});
  });


  function logLine(text, cls) {
    const log = $('#log');
    const row = document.createElement('div');
    const t = (log.children.length * 0.3).toFixed(1);
    row.innerHTML = `<span class="t">${t}s</span><span class="${cls||'in'}">${text}</span>`;
    log.appendChild(row);
    log.scrollTop = log.scrollHeight;
  }

  const stepLabels = ['Generating deploy script', 'Generating detect script', 'Updating manifest', 'Packaging output', 'Finalizing'];
  function renderStepList(currentStep, label) {
    const [n] = String(currentStep).split('/').map(Number);
    $('#step-list').innerHTML = stepLabels.map((l, i) => {
      const idx = i + 1;
      const cls = idx < n ? 'did' : idx === n ? 'doing' : '';
      const icon = `<span class="pi"><svg viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg></span>`;
      return `<div class="phase ${cls}">${icon}${idx}/${stepLabels.length} &middot; ${idx === n ? label : l}</div>`;
    }).join('');
  }

  function renderDoneSheet(payload) {
    const rows = [
      ['Output', payload.path || ''],
      ['App ID', $('#f-appid').value],
      ['Type', form.Mode === 'runtime' ? 'AppUpdater Runtime' : 'Simple Package'],
      ['Target', form.SimplePkgTarget === 'intunewin' ? '.intunewin' : 'PSADT package'],
    ];
    $('#done-sheet').innerHTML = rows.map(([k, v]) => `
      <div class="srow"><span class="sk">${k}</span><span class="sv">${v}</span>
      <button class="copybtn" onclick="navigator.clipboard.writeText(${JSON.stringify(v)});toast('Copied','${k} on clipboard')">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
      </button></div>`).join('');
  }

  /* ---------- fleet ---------- */
  let lastFleet = [];
  window._realHistoryEvents = [];
  const DEMO_FLEET = [
    { id: 'demo-vlc', name: 'VLC media player (demo)', version: '3.0.21', type: 'Runtime', status: 'update available' },
    { id: 'demo-7zip', name: '7-Zip (demo)', version: '23.01', type: '.intunewin', status: 'built - not deployed' },
    { id: 'demo-slack', name: 'Slack (demo)', version: '4.39.0', type: 'PSADT', status: 'unknown' },
    { id: 'demo-printer', name: 'Finance-3F-HP4200 (demo)', version: 'n/a', type: 'Printer', status: 'deployed' }
  ];
  const DEMO_HISTORY = [
    { at: Date.now() - 3600e3, name: 'VLC media player (demo)', id: 'demo-vlc', event: 'built', target: '.intunewin', profile: '&mdash;' },
    { at: Date.now() - 7200e3, name: '7-Zip (demo)', id: 'demo-7zip', event: 'deployed', target: 'PSADT', profile: 'Contoso' },
    { at: Date.now() - 86400e3, name: 'Slack (demo)', id: 'demo-slack', event: 'removed', target: '&mdash;', profile: '&mdash;' },
    { at: Date.now() - 172800e3, name: 'Finance-3F-HP4200 (demo)', id: 'demo-printer', event: 'deployed', target: 'Printer', profile: '&mdash;' }
  ];
  const selectedFleetIds = new Set();
  window._showCfAdvert = true;
  window._showGettingStarted = true;
  window._showCfNav = true;
  function badgeHtml(status) {
    if (status === 'deployed') return `<span class="badge ok"><i></i>deployed</span>`;
    if (status === 'built - not deployed') return `<span class="badge" style="color:var(--signal);border-color:rgba(94,162,255,.3);background:rgba(94,162,255,.07)"><i style="background:currentColor"></i>built &middot; not deployed</span>`;
    if (status === 'unknown') return `<span class="badge" style="color:var(--faint);border-color:var(--edge)"><i style="background:currentColor"></i>untracked</span>`;
    return `<span class="badge wn"><i></i>update available</span>`;
  }
  function renderHomeStats(apps) {
    const total = apps.length;
    const deployed = apps.filter(a => a.status === 'deployed').length;
    const updates = apps.filter(a => a.status === 'update available').length;
    const pending = apps.filter(a => a.status === 'built - not deployed' || a.status === 'unknown').length;
    $('#stat-total').textContent = total;
    $('#stat-deployed').textContent = deployed;
    $('#stat-updates').textContent = updates;
    $('#stat-pending').textContent = pending;
  }
  function renderRecentActivity(events) {
    const el = $('#home-recent-activity');
    if (!el) return;
    const recent = (events || []).slice(0, 4);
    el.innerHTML = recent.length
      ? recent.map(ev => `
        <div class="tglrow" style="padding:7px 0">
          <div style="min-width:0"><b style="font-weight:600;font-size:12.5px">${ev.name}</b>
            <div class="mono" style="font-size:10px;color:var(--faint)">${new Date(ev.at).toLocaleString()}</div>
          </div>
          ${historyBadgeHtml(ev.event)}
        </div>`).join('')
      : `<p class="hint" style="margin:0">Nothing yet - build, deploy, or remove an app to see activity here.</p>`;
  }
  function renderGettingStarted() {
    const card = $('#getting-started-card');
    if (!card) return;
    if (!window._showGettingStarted) { card.style.display = 'none'; return; }
    const steps = [
      { done: lastFleet.length > 0, label: 'Build your first package', go: 'build' },
      { done: (window._profiles || []).length > 0, label: 'Create a client profile for custom branding', go: 'profiles' },
      { done: !!window._workerUrl, label: 'Connect to Cloudflare for a live fleet view (optional)', go: 'worker' }
    ];
    if (steps.every(s => s.done)) { card.style.display = 'none'; return; }
    card.style.display = 'block';
    $('#getting-started-list').innerHTML = steps.map(s => `
      <div class="tglrow" style="cursor:pointer" data-go="${s.go}" role="button" tabindex="0">
        <div style="display:flex;align-items:center;gap:10px">
          <span style="width:18px;height:18px;border-radius:5px;border:1.5px solid ${s.done ? 'transparent' : 'var(--edge-hi)'};background:${s.done ? 'var(--grad)' : 'transparent'};display:grid;place-items:center;flex-shrink:0">
            ${s.done ? '<svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="#0A0B14" stroke-width="3"><path d="M5 13l4 4L19 7"/></svg>' : ''}
          </span>
          <span style="font-size:12.5px;${s.done ? 'color:var(--faint);text-decoration:line-through' : ''}">${s.label}</span>
        </div>
      </div>`).join('');
  }

  /* ---------- guided tour ---------- */
  const TOUR_STEPS = [
    { screen: 'home', selector: '#screen-home h1', title: 'Welcome to AppUpdater', text: 'This is your packaging console. Fleet stats, recent activity, and quick actions all live on this Home screen.' },
    { screen: 'home', selector: '#home-stats', title: 'Fleet at a glance', text: 'How many apps you\'re tracking, how many are deployed, and which need attention - computed from your local records.' },
    { screen: 'home', selector: '#home-build-cta', title: 'Build a package', text: 'The main thing you\'ll do here: drop an installer, confirm its identity, and ship an Intune or PSADT package. The next few steps walk through exactly how.' },
    { screen: 'build', selector: '#segKind', title: 'App or printer?', text: 'Most packages are an app install - pick App and drop an installer below. Printer packaging is different: choose Printer here instead and the form below switches to printer name, driver, and port setup, with its own detect/install/uninstall scripts.' },
    { screen: 'build', selector: '#drop', title: 'Start with an installer', text: 'Drag an .exe or .msi here, or click to browse. AppUpdater reads its version, publisher, and silent-install flags automatically and fills in the identity fields for you.' },
    { screen: 'build', selector: '#segMode', title: 'AppUpdater Runtime vs Simple Package', text: 'AppUpdater Runtime installs the app plus an auto-update task and desktop shortcut, so it keeps itself current on every device from then on. Simple Package just installs the app - nothing extra. Pick Simple if updates will be managed another way, e.g. Intune\'s own update detection.' },
    { screen: 'build', selector: '#segTarget', title: 'Choose an output format', text: '.intunewin packages straight for Intune Win32 app upload. PSADT wraps the install with PSAppDeployToolkit instead - close-running-apps prompts, deferrals, and a branded install dialog your users actually see.', onShow: () => { $('#segTarget button[data-val="psadt"]').click(); } },
    { screen: 'build', selector: '#f-profile', title: 'Branding for this build', text: 'Pick a client profile to apply their logo, banner, and organisation name to this build - or leave it on Default to use your own Settings organisation name.' },
    { screen: 'build', selector: '#bp-panel', title: 'A real preview, not a guess', text: 'This mirrors the actual install dialog your PSADT choice produces - logo, banner, and app name all update live as you fill in the form above. If you picked "Both" versions, a small switch lets you flip between the v3 and v4 look.', onShow: () => {
      // Panel is collapsed by default (see #bp-disclosure), so there's
      // nothing to spotlight yet - play a simulated click on the toggle,
      // then let the real click handler expand it, before the spotlight
      // moves in. Returns the delay (ms) proceed() should wait for.
      if (window._bpExpanded) { updateBuildBrandingPreview(); return 0; }
      const disclosure = $('#bp-disclosure');
      disclosure.classList.add('tour-click-sim');
      setTimeout(() => disclosure.classList.remove('tour-click-sim'), motionMs(420));
      disclosure.click();
      return motionMs(420);
    } },
    { screen: 'fleet', selector: '#screen-fleet h2', title: 'App fleet', text: 'Every app you\'ve built, with its status. Select rows for bulk actions, or remove an app entirely from here. (Nothing built yet on this machine, so the rows below are example data - they\'ll disappear once you close this tour.)' },
    { screen: 'profiles', selector: '#profile-editor', title: 'Client profiles', text: 'Save a client\'s branding here - logo, banner, org name - then pick it at build time instead of re-entering it every time. The preview on the right shows exactly what a real build will look like; click directly on the logo, banner, or text to edit it.' },
    { screen: 'history', selector: '#screen-history h2', title: 'History', text: 'Every build, deploy-mark, and removal is logged here automatically, most recent first. (Same as Fleet - what\'s showing now is example data since nothing\'s happened here yet.)' },
    { screen: 'worker', selector: '#worker-connect-card', title: 'Connect to Cloudflare?', text: 'Optional. Connecting gets you a live fleet view that updates as devices check in, automatic update checks, and a password-protected status page. You can always change this later from Docs & Help.', type: 'cf-choice' },
    { screen: 'accessibility', selector: '#screen-accessibility h2', title: 'Accessibility', text: 'Reduce-motion and other accessibility options live here, separate from general settings.' },
    { screen: 'docs', selector: '#screen-docs h1', title: 'Docs & help', text: 'Come back here any time to replay this tour, or to show Fleet/Worker & settings again if you hid them.' }
  ];
  let tourIndex = 0;
  function tourStepsForCurrentNav() {
    // Filters out the fleet step if the Fleet nav item is hidden.
    return TOUR_STEPS.filter(s => window._showCfNav !== false || s.screen !== 'fleet');
  }
  function startTour() {
    window._tourActive = true;
    tourIndex = 0;
    // Shows demo data on the Fleet/History screens for the duration of the tour.
    if (lastFleet.length === 0) { window._tourDemoFleet = true; lastFleet = DEMO_FLEET; paintFleet(); }
    if (window._realHistoryEvents.length === 0) { window._tourDemoHistory = true; renderHistory(DEMO_HISTORY); }
    $('#fleet-demo-badge').style.display = window._tourDemoFleet ? 'inline-block' : 'none';
    $('#history-demo-badge').style.display = window._tourDemoHistory ? 'inline-block' : 'none';
    $('#tour-overlay').style.display = 'block';
    showTourStep(0);
  }
  function endTour(markSeen) {
    window._tourActive = false;
    $('#tour-overlay').style.display = 'none';
    if (window._tourDemoFleet) { window._tourDemoFleet = false; lastFleet = []; paintFleet(); }
    if (window._tourDemoHistory) { window._tourDemoHistory = false; renderHistory(window._realHistoryEvents); }
    $('#fleet-demo-badge').style.display = 'none';
    $('#history-demo-badge').style.display = 'none';
    if (markSeen) send('mark-onboarding-seen', {});
  }
  function positionTourSpot(target) {
    const r = target.getBoundingClientRect();
    const pad = 8;
    const spot = $('#tour-spot');
    spot.style.top = (r.top - pad) + 'px';
    spot.style.left = (r.left - pad) + 'px';
    spot.style.width = (r.width + pad * 2) + 'px';
    spot.style.height = (r.height + pad * 2) + 'px';
    const card = $('#tour-card');
    const cardW = 300;
    let cardTop = r.bottom + pad + 12;
    let cardLeft = Math.min(Math.max(r.left, 12), window.innerWidth - cardW - 12);
    if (cardTop + 220 > window.innerHeight) cardTop = Math.max(12, r.top - pad - 12 - 220);
    card.style.top = cardTop + 'px';
    card.style.left = cardLeft + 'px';
  }
  function showTourStep(i) {
    const steps = tourStepsForCurrentNav();
    if (i < 0 || i >= steps.length) { endTour(true); return; }
    tourIndex = i;
    const step = steps[i];
    const proceed = () => {
      // onShow may return a ms delay (e.g. to let a simulated click/expand
      // animation play before the spotlight jumps to the now-visible
      // target) - falsy/undefined means show immediately, as before.
      const delay = step.onShow ? step.onShow() : 0;
      const spotlight = () => {
        const target = document.querySelector(step.selector);
        if (!target) { showTourStep(i + 1); return; }
        positionTourSpot(target);
        $('#tour-step-count').textContent = `Step ${i + 1} of ${steps.length}`;
        $('#tour-title').textContent = step.title;
        $('#tour-text').textContent = step.text;
        const isChoice = step.type === 'cf-choice';
        $('#tour-cf-choice').style.display = isChoice ? 'block' : 'none';
        $('#tour-nav-buttons').style.display = isChoice ? 'none' : 'flex';
        $('#tour-back').style.display = i === 0 ? 'none' : 'inline-flex';
        $('#tour-next').textContent = i === steps.length - 1 ? 'Finish' : 'Next';
        $('#tour-cf-keep-visible').checked = false;
      };
      if (delay) setTimeout(spotlight, delay); else spotlight();
    };
    if (!$('#screen-' + step.screen).classList.contains('on')) { goTo(step.screen); setTimeout(proceed, motionMs(320)); }
    else proceed();
  }
  $('#tour-next').addEventListener('click', () => {
    if (window._miniGuideActive) { endMiniGuide(); return; }
    showTourStep(tourIndex + 1);
  });
  $('#tour-back').addEventListener('click', () => showTourStep(tourIndex - 1));
  // A scoped one-step spotlight (reuses the tour overlay/spot/card) for
  // guiding into Client Profiles from wherever "not set yet" is shown -
  // deliberately does NOT touch the real guided-tour step index or its
  // mark-onboarding-seen completion, since this isn't the first-run tour.
  function showProfileGuide() {
    goTo('profiles');
    window._tourActive = true;
    window._miniGuideActive = true;
    $('#tour-overlay').style.display = 'block';
    setTimeout(() => {
      const target = document.querySelector('#profile-editor');
      if (!target) return;
      positionTourSpot(target);
      $('#tour-step-count').textContent = 'Quick guide';
      $('#tour-title').textContent = 'Set up a client profile';
      $('#tour-text').textContent = 'Save a client\'s branding here - logo, banner, org name - then pick it at build time, or set it as your default from Settings.';
      $('#tour-cf-choice').style.display = 'none';
      $('#tour-nav-buttons').style.display = 'flex';
      $('#tour-back').style.display = 'none';
      $('#tour-next').textContent = 'Got it';
    }, motionMs(320));
  }
  function endMiniGuide() {
    window._miniGuideActive = false;
    window._tourActive = false;
    $('#tour-overlay').style.display = 'none';
  }
  $('#tour-skip').addEventListener('click', () => { if (window._miniGuideActive) endMiniGuide(); else endTour(true); });
  document.addEventListener('keydown', (e) => {
    if ($('#tour-overlay').style.display !== 'block') return;
    if ($('#tour-cf-choice').style.display === 'block') return; // let Tab reach the Yes/No buttons instead of hijacking arrows
    if (window._miniGuideActive) {
      if (e.key === 'Escape' || e.key === 'ArrowRight' || e.key === 'Enter') { endMiniGuide(); e.preventDefault(); }
      return;
    }
    if (e.key === 'Escape') { endTour(true); }
    else if (e.key === 'ArrowRight' || e.key === 'Enter') { showTourStep(tourIndex + 1); }
    else if (e.key === 'ArrowLeft') { showTourStep(tourIndex - 1); }
    else return;
    e.preventDefault();
  });
  $('#tour-cf-yes').addEventListener('click', () => {
    endTour(true);
    goTo('worker');
    setTimeout(() => openWorkerOptions($('#btn-worker-options')), motionMs(350));
  });
  $('#tour-cf-no').addEventListener('click', () => {
    const keepVisible = $('#tour-cf-keep-visible').checked;
    window._showCfNav = keepVisible ? true : false;
    $('#tgl-cf-nav').classList.toggle('on', window._showCfNav);
    applyCfNavVisibility();
    showTourStep(tourIndex + 1);
  });
  function applyCfNavVisibility() {
    const show = window._showCfNav !== false;
    document.querySelectorAll('.nav-btn[data-go="fleet"], .nav-btn[data-go="worker"]').forEach(b => {
      b.style.display = show ? '' : 'none';
    });
  }
  $('#getting-started-tour').addEventListener('click', startTour);
  $('#docs-replay-tour').addEventListener('click', startTour);
  $('#docs-reset-onboarding').addEventListener('click', () => {
    if (confirm('Reset the guided tour and first-run hints? Close and reopen AppUpdater afterward to see them again.')) {
      send('reset-onboarding', {});
      toast('Guide reset', 'Close and reopen AppUpdater to see it again.');
    }
  });
  $('#tgl-cf-nav').addEventListener('click', function(){
    $('#tgl-cf-nav').classList.toggle('on');
    window._showCfNav = $('#tgl-cf-nav').classList.contains('on');
    applyCfNavVisibility();
    saveSettingsNow(); flashSaved();
  });

  function renderFleet(apps) {
    // Array.isArray guard, not just `|| []`: a PS-side serialization edge case
    // can send an empty fleet as {} instead of [], which is truthy and would
    // otherwise slip through `|| []` and crash paintFleet()'s .filter() call.
    lastFleet = Array.isArray(apps) ? apps : [];
    paintFleet();
    renderHomeStats(lastFleet);
    renderGettingStarted();
    const banner = $('#worker-banner'), dot = $('#worker-dot'), bannerText = $('#worker-banner-text');
    const connectCard = $('#connect-card'), workerStatus = $('#worker-status');
    const actionsConnected = $('#worker-actions-connected'), actionsDisconnected = $('#worker-actions-disconnected'), actionsHint = $('#worker-actions-hint');
    if (window._workerUrl) {
      banner.style.display = 'flex';
      connectCard.style.display = 'none';
      dot.style.background = 'var(--ok)';
      bannerText.style.color = 'var(--ok)';
      bannerText.textContent = `${window._workerUrl} â€” connected`;
      workerStatus.innerHTML = `<span style="display:flex;align-items:center;gap:10px"><span style="width:8px;height:8px;border-radius:50%;background:var(--ok)"></span><span style="font-family:var(--font-m);font-size:12px;color:var(--ok)">${window._workerUrl}</span></span>`;
      actionsConnected.style.display = 'flex';
      actionsDisconnected.style.display = 'none';
      actionsHint.style.display = 'block';
    } else {
      banner.style.display = 'flex';
      dot.style.background = 'var(--faint)';
      bannerText.style.color = 'var(--dim)';
      bannerText.textContent = 'Not yet connected to Cloudflare';
      connectCard.style.display = window._showCfAdvert ? 'block' : 'none';
      workerStatus.textContent = 'Not connected yet.';
      actionsConnected.style.display = 'none';
      actionsDisconnected.style.display = 'block';
      actionsHint.style.display = 'none';
    }
  }
  function fleetEmptyHtml() {
    if (window._workerUrl || !window._showCfAdvert) {
      return `<tr><td style="color:var(--faint);padding:18px 14px">No apps tracked yet - build your first package.</td></tr>`;
    }
    return `<tr><td style="padding:22px 18px">
      <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:16px">
        <div style="flex:1;min-width:220px">
          <div style="font-weight:600;font-size:13.5px;color:var(--dim)">No apps tracked yet</div>
          <div style="font-size:12px;color:var(--faint);margin-top:3px">Build your first package below - or connect to Cloudflare first for a live fleet view that updates as devices check in, not just this machine's local records.</div>
        </div>
        <button class="btn primary sm" data-go="build">Build your first package</button>
        <button class="btn sm" data-go="worker">Connect</button>
        <button class="btn ghost sm" data-fleet-advert-dismiss>Dismiss</button>
      </div>
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">
        <span style="width:7px;height:7px;border-radius:50%;background:var(--ok);animation:livepulse 1.6s infinite"></span>
        <span style="font-family:var(--font-m);font-size:10.5px;color:var(--dim)">example - what this table looks like once connected</span>
      </div>
      <div style="background:var(--panel-2);border:1px solid var(--edge);border-radius:8px;padding:14px 16px;font-family:var(--font-m);font-size:11px">
        <div style="display:flex;align-items:center;gap:10px;padding:6px 0">
          <span class="badge ok"><i></i>online</span>
          <span style="color:var(--ink);flex:1">VLC media player</span>
          <span style="color:var(--faint)">3.0.20 &#8594; 3.0.21</span>
        </div>
        <div style="display:flex;align-items:center;gap:10px;padding:6px 0">
          <span class="badge ok"><i></i>online</span>
          <span style="color:var(--ink);flex:1">7-Zip</span>
          <span style="color:var(--faint)">up to date</span>
        </div>
        <div style="display:flex;align-items:center;gap:10px;padding:6px 0">
          <span class="badge wn"><i></i>checking</span>
          <span style="color:var(--ink);flex:1">Notepad++</span>
          <span style="color:var(--faint)">last seen 4m ago</span>
        </div>
      </div>
    </td></tr>`;
  }
  function paintFleet() {
    const q = ($('#fleet-filter') ? $('#fleet-filter').value : '').toLowerCase();
    const apps = lastFleet.filter(a => !q || a.name.toLowerCase().includes(q));
    const rowsHtml = apps.map(a => {
      const actions = a.status === 'built - not deployed' || a.status === 'unknown'
        ? `<button class="btn sm" data-rebuild="${a.id}">Preview</button><button class="btn primary sm" data-mark-deployed="${a.id}">Mark deployed</button>`
        : a.status === 'update available'
        ? `<button class="btn sm" data-rebuild="${a.id}">Rebuild</button>`
        : `<button class="btn sm" data-rebuild="${a.id}">Preview</button>`;
      const testBtn = a.outputDir ? `<button class="btn sm" data-test="${a.id}" title="Run the real install/detect scripts on this machine">Test locally</button>` : '';
      const removeBtn = `<button class="btn sm danger" data-remove="${a.id}" title="Remove from the manifest, with the option to also clean up this machine">Remove</button>`;
      const checked = selectedFleetIds.has(a.id) ? ' checked' : '';
      return `
      <tr class="r"><td style="width:26px"><input type="checkbox" data-select="${a.id}"${checked}></td>
      <td style="width:32%"><b style="font-weight:600">${a.name}</b><div class="mono">${a.id}${a.profile ? ' &middot; ' + a.profile : ''}</div></td>
      <td class="mono">${a.version || 'auto'}</td><td class="mono">${a.type || '&mdash;'}</td>
      <td style="text-align:right">${badgeHtml(a.status)}</td>
      <td style="text-align:right;white-space:nowrap">${actions} ${testBtn} ${removeBtn}</td></tr>`;
    }).join('');
    const presentIds = new Set(apps.map(a => a.id));
    for (const id of Array.from(selectedFleetIds)) if (!presentIds.has(id)) selectedFleetIds.delete(id);
    $('#fleet-table').innerHTML = apps.length
      ? `<tr><th style="width:26px"></th><th style="width:32%">App</th><th>Version</th><th>Target</th><th style="text-align:right" title="Reflects local build/deploy records only, not live device state">Status</th><th></th></tr>${rowsHtml}`
      : fleetEmptyHtml();
    $('#home-fleet-table').innerHTML = rowsHtml || `<tr><td style="color:var(--faint);padding:18px 14px">No apps tracked yet - build your first package.</td></tr>`;
    $('#fleet-summary').textContent = `${lastFleet.length} app${lastFleet.length === 1 ? '' : 's'} in the fleet`;
    paintBulkBar();
  }
  function paintBulkBar() {
    const bar = $('#fleet-bulk-bar');
    if (!bar) return;
    const n = selectedFleetIds.size;
    bar.style.display = n ? 'flex' : 'none';
    if (n) $('#fleet-bulk-count').textContent = `${n} selected`;
  }
  function historyBadgeHtml(ev) {
    if (ev.indexOf('deployed') === 0) return `<span class="badge ok"><i></i>${ev}</span>`;
    if (ev.indexOf('removed') === 0) return `<span class="badge wn"><i></i>${ev}</span>`;
    return `<span class="badge" style="color:var(--signal);border-color:rgba(94,162,255,.3);background:rgba(94,162,255,.07)"><i style="background:currentColor"></i>${ev}</span>`;
  }
  function renderHistory(events) {
    const has = events && events.length;
    $('#history-empty').style.display = has ? 'none' : 'block';
    $('#history-table').style.display = has ? '' : 'none';
    if (!has) { $('#history-table').innerHTML = ''; return; }
    const rowsHtml = events.map(ev => `
      <tr class="r"><td class="mono" style="white-space:nowrap;color:var(--dim)">${new Date(ev.at).toLocaleString()}</td>
      <td><b style="font-weight:600">${ev.name}</b><div class="mono">${ev.id}</div></td>
      <td>${historyBadgeHtml(ev.event)}</td>
      <td class="mono">${ev.target || '&mdash;'}</td><td class="mono">${ev.profile || '&mdash;'}</td></tr>`).join('');
    $('#history-table').innerHTML = `<tr><th>When</th><th>App</th><th>Event</th><th>Target</th><th>Profile</th></tr>${rowsHtml}`;
  }
  document.addEventListener('click', e => {
    const rb = e.target.closest('[data-rebuild]');
    if (rb) {
      const app = lastFleet.find(a => a.id === rb.dataset.rebuild);
      if (app) {
        goTo('build');
        $('#f-appid').value = app.id;
        $('#f-displayname').value = app.name;
        updateSummary();
        toast('Rebuild', 'Fields pre-filled - pick the installer again to continue.');
      }
    }
    const md = e.target.closest('[data-mark-deployed]');
    if (md) send('mark-deployed', { id: md.dataset.markDeployed });
    const tb = e.target.closest('[data-test]');
    if (tb) openTestModal(tb.dataset.test);
    const rmv = e.target.closest('[data-remove]');
    if (rmv) send('remove-from-fleet', { id: rmv.dataset.remove });
    if (e.target.closest('[data-fleet-advert-dismiss]')) {
      window._showCfAdvert = false;
      $('#tgl-cf-advert').classList.remove('on');
      send('dismiss-cloudflare-advert', {});
      paintFleet();
      toast('Hidden', 'Bring it back any time from Worker & settings.');
    }
  });
  document.addEventListener('change', e => {
    const cb = e.target.closest('[data-select]');
    if (cb) {
      if (cb.checked) selectedFleetIds.add(cb.dataset.select); else selectedFleetIds.delete(cb.dataset.select);
      paintBulkBar();
    }
  });
  const fleetBulkMarkBtn = $('#fleet-bulk-mark-deployed');
  if (fleetBulkMarkBtn) fleetBulkMarkBtn.addEventListener('click', () => {
    const ids = Array.from(selectedFleetIds);
    if (!ids.length) return;
    if (!confirm(`Mark ${ids.length} app${ids.length === 1 ? '' : 's'} as deployed?`)) return;
    ids.forEach(id => send('mark-deployed', { id }));
    selectedFleetIds.clear();
    paintBulkBar();
  });
  const fleetBulkClearBtn = $('#fleet-bulk-clear');
  if (fleetBulkClearBtn) fleetBulkClearBtn.addEventListener('click', () => { selectedFleetIds.clear(); paintFleet(); });

  let currentTestId = null;
  function openTestModal(id) {
    currentTestId = id;
    const app = lastFleet.find(a => a.id === id);
    $('#test-modal-title').textContent = 'Test locally' + (app ? ' - ' + app.name : '');
    $('#test-log').innerHTML = '';
    $('#test-also-uninstall').checked = false;
    $('#test-modal').style.display = 'flex';
  }
  $('#test-modal-close').addEventListener('click', () => { $('#test-modal').style.display = 'none'; });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && $('#test-modal').style.display !== 'none') $('#test-modal').style.display = 'none';
  });
  $('#test-modal-start').addEventListener('click', () => {
    $('#test-log').innerHTML = '';
    logTestLine('Starting...', 'ac');
    send('test-locally', { id: currentTestId, alsoUninstall: $('#test-also-uninstall').checked, simulateSystem: $('#test-simulate-system').checked });
  });
  function logTestLine(text, cls) {
    const log = $('#test-log');
    const row = document.createElement('div');
    row.innerHTML = '<span class="' + (cls||'in') + '">' + text + '</span>';
    log.appendChild(row);
    log.scrollTop = log.scrollHeight;
  }
  if ($('#fleet-filter')) $('#fleet-filter').addEventListener('input', paintFleet);

  /* ---------- worker & settings ---------- */
  $('#connect-preview-btn').addEventListener('click', () => {
    const demo = $('#connect-demo');
    demo.style.display = demo.style.display === 'none' ? 'block' : 'none';
  });
  $('#connect-card-dismiss').addEventListener('click', () => {
    window._showCfAdvert = false;
    $('#tgl-cf-advert').classList.remove('on');
    send('dismiss-cloudflare-advert', {});
    renderFleet(lastFleet);
    toast('Hidden', 'Bring it back any time from Worker & settings.');
  });
  $('#getting-started-dismiss').addEventListener('click', () => {
    window._showGettingStarted = false;
    $('#tgl-getting-started').classList.remove('on');
    send('dismiss-getting-started', {});
    renderGettingStarted();
    toast('Hidden', 'Bring it back any time from Worker & settings.');
  });
  function openWorkerOptions(btn) {
    const label = btn.textContent;
    btn.disabled = true;
    btn.dataset.origLabel = label;
    btn.textContent = 'Openingâ€¦';
    window._workerOptionsPending = true;
    send('open-worker-options', {});
  }
  function resetWorkerOptionsButtons() {
    if (!window._workerOptionsPending) return;
    window._workerOptionsPending = false;
    ['#connect-btn', '#btn-worker-options', '#btn-worker-connect'].forEach(sel => {
      const btn = $(sel);
      if (btn && btn.dataset.origLabel) { btn.disabled = false; btn.textContent = btn.dataset.origLabel; }
    });
  }
  $('#connect-btn').addEventListener('click', (e) => openWorkerOptions(e.currentTarget));
  $('#btn-worker-connect').addEventListener('click', (e) => openWorkerOptions(e.currentTarget));

  $('#btn-open-status').addEventListener('click', () => send('open-status-dashboard', {}));
  $('#btn-worker-options').addEventListener('click', (e) => openWorkerOptions(e.currentTarget));
  $('#btn-disconnect').addEventListener('click', () => {
    if (confirm('Disconnect this worker? You will need to reconnect via the setup wizard to restore the URL and manifest token.')) send('disconnect-worker', {});
  });

  // Loads initial data for Home, Worker & settings, Profiles, and History.
  send('get-fleet', {});
  send('get-settings', {});
  send('get-profiles', {});
  send('get-history', {});
  send('get-psadt-stock-assets', {});

  // Falls back to an empty fleet if fleet-data doesn't arrive within 5s.
  window._gotFleetData = false;
  setTimeout(() => {
    if (!window._gotFleetData) renderFleet([]);
  }, 5000);
</script>
</body>
</html>

'@

# ---------------------------------------------------------------------------
# Requests administrator elevation if not already running as admin.
# $env:APPUPDATER_NO_ELEVATE=1 skips this for automated/unattended test runs
# (e.g. click-test.ps1) where the caller is already running as a non-admin
# and can't answer a UAC prompt. Not for normal use - anything the app does
# that genuinely needs admin will just fail without it.
# ---------------------------------------------------------------------------
$__principal = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if (-not $__principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) -and -not $env:APPUPDATER_NO_ELEVATE) {
  $__args = @('-Sta', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', ('"{0}"' -f $PSCommandPath))
  Start-Process (Join-Path $PSHOME 'powershell.exe') -Verb RunAs -ArgumentList ($__args -join ' ')
  exit 0
}

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase

# ---------------------------------------------------------------------------
# Embedded copy of the AppUpdaterV520.ps1 core script, base64-encoded and
# decoded here into a script block.
# ---------------------------------------------------------------------------
$__CoreB64Chunks = @(
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  ''
)
try {
  $__CoreSrc = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(($__CoreB64Chunks -join '')))
} catch {
  $__CoreSrc = ''
  try { Add-Content -LiteralPath (Join-Path $PSScriptRoot 'AppUpdater.log') -Value "$(Get-Date -Format s) [FATAL] Base64 decode of core blob threw: $($_.Exception.Message)" -ErrorAction Stop } catch {}
}
try { Add-Content -LiteralPath (Join-Path $PSScriptRoot 'AppUpdater.log') -Value "$(Get-Date -Format s) [DIAG] CoreSrc length after decode: $($__CoreSrc.Length); ChunkCount=$($__CoreB64Chunks.Count)" -ErrorAction Stop } catch {}

# Written to a real file (not an in-memory ScriptBlock) so the core script's
# own $MyInvocation.MyCommand.Path / $PSCommandPath resolve to a real path
# instead of silently falling through to a garbage CWD-relative guess.
$__CoreTempFile = Join-Path ([System.IO.Path]::GetTempPath()) 'AppUpdaterCore.generated.ps1'
try {
  [System.IO.File]::WriteAllText($__CoreTempFile, $__CoreSrc, [System.Text.Encoding]::UTF8)
} catch {
  try { Add-Content -LiteralPath (Join-Path $PSScriptRoot 'AppUpdater.log') -Value "$(Get-Date -Format s) [FATAL] Failed to write core temp file: $($_.Exception.Message)" -ErrorAction Stop } catch {}
}

# Downloads the WebView2 SDK assemblies from nuget.org if not already
# present. Returns $true if the assemblies are available, $false otherwise.
function Ensure-WebView2Assemblies {
  param([string]$Dir, [string]$LoaderDestDir)

  $core   = Join-Path $Dir 'Microsoft.Web.WebView2.Core.dll'
  $wpf    = Join-Path $Dir 'Microsoft.Web.WebView2.Wpf.dll'
  $loader = Join-Path $LoaderDestDir 'WebView2Loader.dll'
  if ((Test-Path $core) -and (Test-Path $wpf) -and (Test-Path $loader)) { return $true }

  try {
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    $tmpZip = Join-Path ([System.IO.Path]::GetTempPath()) "webview2_$([guid]::NewGuid()).zip"
    $tmpExtract = Join-Path ([System.IO.Path]::GetTempPath()) "webview2_$([guid]::NewGuid())"

    # Pinned WebView2 SDK version.
    $version = '1.0.2792.45'
    $url = "https://www.nuget.org/api/v2/package/Microsoft.Web.WebView2/$version"

    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    Invoke-WebRequest -Uri $url -OutFile $tmpZip -UseBasicParsing -TimeoutSec 30

    Add-Type -AssemblyName System.IO.Compression.FileSystem
    [System.IO.Compression.ZipFile]::ExtractToDirectory($tmpZip, $tmpExtract)

    Copy-Item (Join-Path $tmpExtract 'lib\net462\Microsoft.Web.WebView2.Core.dll') $core -Force
    Copy-Item (Join-Path $tmpExtract 'lib\net462\Microsoft.Web.WebView2.Wpf.dll') $wpf -Force
    Copy-Item (Join-Path $tmpExtract 'runtimes\win-x64\native\WebView2Loader.dll') $loader -Force

    Remove-Item $tmpZip, $tmpExtract -Recurse -Force -ErrorAction SilentlyContinue
    return (Test-Path $core) -and (Test-Path $wpf) -and (Test-Path $loader)
  } catch {
    Write-Warning "WebView2 assembly auto-download failed: $($_.Exception.Message)"
    return $false
  }
}

$__wv2Ready = Ensure-WebView2Assemblies -Dir $Wv2AssemblyDir -LoaderDestDir $PSScriptRoot

# ---------------------------------------------------------------------------
# Checks for the WebView2 Runtime and installs it if missing.
# ---------------------------------------------------------------------------
function Test-WebView2RuntimeInstalled {
  $keys = @(
    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}',
    'HKLM:\SOFTWARE\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}',
    'HKCU:\SOFTWARE\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}'
  )
  foreach ($k in $keys) {
    if (Test-Path $k) {
      $pv = (Get-ItemProperty -Path $k -Name 'pv' -ErrorAction SilentlyContinue).pv
      if ($pv -and $pv -ne '0.0.0.0') { return $true }
    }
  }
  return $false
}

function Install-WebView2Runtime {
  try {
    $setupExe = Join-Path ([System.IO.Path]::GetTempPath()) "MicrosoftEdgeWebview2Setup_$([guid]::NewGuid()).exe"
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    # Microsoft Edge WebView2 Runtime Evergreen Bootstrapper.
    Invoke-WebRequest -Uri 'https://go.microsoft.com/fwlink/p/?LinkId=2124703' -OutFile $setupExe -UseBasicParsing -TimeoutSec 60
    $p = Start-Process -FilePath $setupExe -ArgumentList '/silent', '/install' -Wait -PassThru
    Remove-Item $setupExe -Force -ErrorAction SilentlyContinue
    return ($p.ExitCode -eq 0) -or (Test-WebView2RuntimeInstalled)
  } catch {
    Write-Warning "WebView2 runtime install failed: $($_.Exception.Message)"
    return $false
  }
}

if (-not (Test-WebView2RuntimeInstalled)) {
  $__wv2RuntimeReady = Install-WebView2Runtime
  if (-not $__wv2RuntimeReady) { $__wv2Ready = $false }
}

if (-not $__wv2Ready) {
  # Falls back to the classic AppUpdater interface if WebView2 is unavailable.
  Add-Type -AssemblyName PresentationFramework
  [System.Windows.MessageBox]::Show(
    "Could not fetch the WebView2 runtime files automatically (no internet, or the download was blocked).`n`n" +
    "Falling back to the classic AppUpdater interface for this run.",
    'AppUpdater', 'OK', 'Information'
  ) | Out-Null
  & $__CoreTempFile
  exit 0
}

$__wv2Core = Join-Path $Wv2AssemblyDir 'Microsoft.Web.WebView2.Core.dll'
$__wv2Wpf  = Join-Path $Wv2AssemblyDir 'Microsoft.Web.WebView2.Wpf.dll'
Add-Type -Path $__wv2Core
Add-Type -Path $__wv2Wpf

# Adds the script folder to PATH so WebView2Loader.dll can be located.
$env:PATH = "$PSScriptRoot;$env:PATH"

# Loads the core script's functions into scope. Dot-sourced from the real
# temp file written above (not an in-memory ScriptBlock).
try {
  . $__CoreTempFile -LoadFunctionsOnly
} catch {
  $__coreLoadErr = "Core -LoadFunctionsOnly dot-source threw: $($_.Exception.Message)`n$($_.ScriptStackTrace)"
  try { Add-Content -LiteralPath (Join-Path $PSScriptRoot 'AppUpdater.log') -Value "$(Get-Date -Format s) [FATAL] $__coreLoadErr" -ErrorAction Stop } catch {}
}

# Path to the app manifest used by the status dashboard.
$ManifestPath = Join-Path $env:ProgramData 'AppUpdater\appVersions.xml'

# ---------------------------------------------------------------------------
# Runs a script block on a background runspace and streams its output to
# the page via Write-Host/Write-OK/Write-Warn/Write-Fail/Write-Step.
# ---------------------------------------------------------------------------
function Start-BackgroundJob {
  param($Wv, [scriptblock]$Body, [hashtable]$Vars = @{}, [string[]]$CaptureFunctions = @(), [scriptblock]$OnDone)

  $q = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
  $d = [System.Collections.Generic.List[string]]::new()

  $rs = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
  $rs.ApartmentState = 'MTA'; $rs.ThreadOptions = 'ReuseThread'; $rs.Open()
  $rs.SessionStateProxy.SetVariable('_q', $q)
  $rs.SessionStateProxy.SetVariable('_d', $d)
  $rs.SessionStateProxy.SetVariable('_vars', $Vars)
  foreach ($vn in @('CF_API','WorkerName','KVNamespace','WorkerSource','XmlFile','ManifestTokenFile','ConfigFile')) {
    $rs.SessionStateProxy.SetVariable($vn, (Get-Variable $vn -ValueOnly -Scope Script -ErrorAction SilentlyContinue))
  }
  $fnSrc = ($CaptureFunctions | ForEach-Object {
    $fn = Get-Item "Function:\$_" -ErrorAction SilentlyContinue
    if ($fn) { "function $_ {`n$($fn.ScriptBlock)`n}" }
  }) -join "`n"
  $rs.SessionStateProxy.SetVariable('_fnSrc', $fnSrc)
  $rs.SessionStateProxy.SetVariable('_body', $Body)

  $ps = [powershell]::Create()
  $ps.Runspace = $rs
  [void]$ps.AddScript({
    function Write-Host  { param([object]$Object,[string]$ForegroundColor='Gray',[switch]$NoNewline)
      $c = switch ($ForegroundColor) {'Green'{'ok'}'Cyan'{'info'}'Yellow'{'warn'}'Red'{'err'}'DarkGray'{'dim'}default{'gray'}}
      $_q.Enqueue("$c|$Object") }
    function Write-OK    { param([string]$M) Write-Host "  [OK]  $M" -ForegroundColor Green }
    function Write-Warn  { param([string]$M) Write-Host "  [!!]  $M" -ForegroundColor Yellow }
    function Write-Fail  { param([string]$M) Write-Host "  [XX]  $M" -ForegroundColor Red }
    function Write-Step  { param([string]$n,[string]$M) Write-Host "  [$n] $M" -ForegroundColor Cyan }
    function Write-Info  { param([string]$M) Write-Host "        $M" -ForegroundColor DarkGray }
    function Write-AppLog{ param([string]$Message,[string]$Level='INFO') }
    try { Invoke-Expression $_fnSrc } catch { $_q.Enqueue("err|Load failed: $($_.Exception.Message)"); $_d.Add('error'); return }
    & $_body
  })
  $handle = $ps.BeginInvoke()

  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(150)
  $timer.Add_Tick({
    $line = ''
    while ($q.TryDequeue([ref]$line)) {
      $parts = $line -split '\|', 2
      Send-ToPage $Wv 'job-log' @{ tone = $parts[0]; line = $(if ($parts.Count -gt 1) { $parts[1] } else { $line }) }
    }
    if ($d.Count -gt 0) {
      $timer.Stop()
      $ps.EndInvoke($handle) | Out-Null
      $ps.Dispose(); $rs.Close()
      if ($OnDone) { & $OnDone $d[0] }
    }
  })
  $timer.Start()
}

# ---------------------------------------------------------------------------
# Tracks per-app deploy status (built vs deployed) in a local JSON file.
# ---------------------------------------------------------------------------
$DeployStatusFile = Join-Path $env:ProgramData 'AppUpdater\deploy-status.json'

# Converts a PSCustomObject to a hashtable.
function ConvertTo-HashtableShallow($Obj) {
  $ht = @{}
  if ($Obj) { foreach ($p in $Obj.PSObject.Properties) { $ht[$p.Name] = $p.Value } }
  $ht
}

function Get-DeployStatusStore {
  try {
    if (Test-Path $DeployStatusFile) { return (ConvertTo-HashtableShallow (Get-Content $DeployStatusFile -Raw | ConvertFrom-Json)) }
  } catch { }
  return @{}
}

function Save-DeployStatusStore {
  param([hashtable]$Store)
  try {
    New-Item -ItemType Directory -Path (Split-Path $DeployStatusFile) -Force -ErrorAction SilentlyContinue | Out-Null
    ($Store | ConvertTo-Json -Depth 6) | Set-Content $DeployStatusFile -Encoding UTF8 -Force
  } catch { Write-Warning "Could not write deploy-status.json: $($_.Exception.Message)" }
}

# ---------------------------------------------------------------------------
# Append-only log of build/deploy/remove events, for the History screen.
# ---------------------------------------------------------------------------
$DeployHistoryFile = Join-Path $env:ProgramData 'AppUpdater\deploy-history.json'
$DeployHistoryMaxEvents = 500

function Get-DeployHistory {
  try {
    if (Test-Path $DeployHistoryFile) { return @(Get-Content $DeployHistoryFile -Raw | ConvertFrom-Json) }
  } catch { }
  return @()
}

function Add-DeployHistoryEvent {
  param([string]$AppID, [string]$AppName, [string]$Event, [string]$Target, [string]$ProfileName)
  $history = @(Get-DeployHistory)
  $history += [ordered]@{
    id = $AppID; name = (if ($AppName) { $AppName } else { $AppID })
    event = $Event; at = (Get-Date -Format 'o')
    target = $Target; profile = $ProfileName
  }
  if ($history.Count -gt $DeployHistoryMaxEvents) {
    $history = $history[($history.Count - $DeployHistoryMaxEvents)..($history.Count - 1)]
  }
  try {
    New-Item -ItemType Directory -Path (Split-Path $DeployHistoryFile) -Force -ErrorAction SilentlyContinue | Out-Null
    ($history | ConvertTo-Json -Depth 6) | Set-Content $DeployHistoryFile -Encoding UTF8 -Force
  } catch { Write-Warning "Could not write deploy-history.json: $($_.Exception.Message)" }
}

# =============================================================================
# BUILT-IN PRINTER DRIVER FAMILIES
# Curated metadata only (no vendor .zip files bundled - same rule the driver
# library already follows for user-imported drivers) for common vendor driver
# families, one INF/driver package shared across many printer models. This is
# baked directly into host.ps1 - single-file distribution stays intact, no
# side-car data file host.ps1 depends on - so seeding the library never
# requires anything beyond host.ps1 itself.
# =============================================================================
$script:BuiltInPrinterDriverFamilies = @(
  @{ DriverID = 'BROTHER_HL_SERIES'; DisplayName = 'Brother HL Series'; Manufacturer = 'Brother'; InfRelativePath = 'BROHL17A.INF'
     Models = @('Brother HL-2290','Brother HL-2295D','Brother HL-L2590DN','Brother HL-L2595DW','Brother HL-B2000D','Brother HL-B2050DN','Brother HL-B2080DW','Brother HL-L2310D','Brother HL-L2325DW','Brother HL-L2330D','Brother HL-L2335D','Brother HL-L2350DW','Brother HL-L2357DW','Brother HL-L2370DN','Brother HL-L2370DW','Brother HL-L2375DW','Brother HL-L2379DW','Brother HL-L2385DW') }
  @{ DriverID = 'BROTHER_TD_SERIES'; DisplayName = 'Brother TD Series'; Manufacturer = 'Brother'; InfRelativePath = 'BST18AV.INF'
     Models = @('Brother TD-4410D','Brother TD-4420DN','Brother TD-4510D','Brother TD-4520DN','Brother TD-4550DNWB','Brother TD-4210D') }
  @{ DriverID = 'FUJI_XEROX_PRIMELINK_C9000_SERIES'; DisplayName = 'Fuji Xerox PrimeLink C9000 Series'; Manufacturer = 'Fuji'; InfRelativePath = 'FF6PRAL.inf'
     Models = @('FF K549p for PrimeLink C9065 PCL 6','FF K549p for PrimeLink C9070 PCL 6') }
  @{ DriverID = 'FUJI_XEROX_APEOSPORT_SERIES'; DisplayName = 'Fuji Xerox ApeosPort Series'; Manufacturer = 'Fuji'; InfRelativePath = 'FF6BSAL.inf'
     Models = @('FF K505p for ApeosPort C3070 PCL 6','FF K505p for ApeosPort C3570 PCL 6','FF K505p for ApeosPort C4570 PCL 6','FF K505p for ApeosPort C5570 PCL 6','FF K505p for ApeosPort C6570 PCL 6','FF K505p for ApeosPort C7070 PCL 6') }
  @{ DriverID = 'HP_LASERJET_PRO_M304_M305_M404_M405_SERIES'; DisplayName = 'HP LaserJet Pro M304/M305/M404/M405 Series'; Manufacturer = 'HP'; InfRelativePath = 'hpmoC12A4_x64.inf'
     Models = @('HP LaserJet Pro M404-M405 PCL-6 (V4)','HP LaserJet Pro M304-M305 PCL-6 (V4)') }
  @{ DriverID = 'HP_COLOR_LASERJET_PRO_M478F_M479_SERIES'; DisplayName = 'HP Color LaserJet Pro M478f/M479 Series'; Manufacturer = 'HP'; InfRelativePath = 'hpclC62A4_x64.inf'
     Models = @('HP Color LaserJet Pro M479 PCL-6 (V4)','HP Color LaserJet Pro M478f-9f PCL-6 (V4)') }
  @{ DriverID = 'HP'; DisplayName = 'HP'; Manufacturer = 'HP'; InfRelativePath = 'hpcu340u.inf'
     Models = @('HP Universal Printing PCL 6 (v7.8.0)') }
  @{ DriverID = 'CANON'; DisplayName = 'Canon'; Manufacturer = 'Canon'; InfRelativePath = 'CNP60MA64.INF'
     Models = @('Canon Generic Plus PCL6') }
  @{ DriverID = 'RICOH_MP_SERIES'; DisplayName = 'Ricoh MP Series'; Manufacturer = 'Ricoh'; InfRelativePath = 'MPC4504_.inf'
     Models = @('RICOH MP C4504 PCL 6') }
  @{ DriverID = 'RICOH_P_SERIES'; DisplayName = 'Ricoh P Series'; Manufacturer = 'Ricoh'; InfRelativePath = 'SP_501__.inf'
     Models = @('RICOH P 501 PCL 6','RICOH P 502 PCL 6') }
  @{ DriverID = 'RICOH_SP_SERIES'; DisplayName = 'Ricoh SP Series'; Manufacturer = 'Ricoh'; InfRelativePath = 'GXE6M.inf'
     Models = @('RICOH SP 3710DN PCL 6') }
)

# Upserts $BuiltInPrinterDriverFamilies into driverLibrary.json. Idempotent by
# DriverID: an already-imported entry keeps its DateAdded and (crucially) its
# SourceURL/extracted files untouched if a real driver package was supplied
# for it since, rather than clobbering it back to metadata-only.
function Import-BuiltInDriverFamilies {
  $data = Get-DriverLibrary
  # Builds the merged list by walking the EXISTING array in its own on-disk
  # order first (so unrelated entries never reshuffle), then appends brand-new
  # built-in families in their fixed definition order. Deliberately avoids
  # rebuilding from a @{} hashtable's .Values, whose enumeration order is not
  # guaranteed stable across calls and would make re-running produce a
  # spurious diff despite identical data.
  $builtInById = @{}
  foreach ($f in $script:BuiltInPrinterDriverFamilies) { $builtInById[$f.DriverID] = $f }

  $merged = [System.Collections.Generic.List[hashtable]]::new()
  $seen = @{}
  $updated = 0
  foreach ($d in @($data.Drivers)) {
    $seen[$d.DriverID] = $true
    $f = $builtInById[$d.DriverID]
    if ($f) {
      $updated++
      $merged.Add(@{
        DriverID = $f.DriverID; DisplayName = $f.DisplayName; Manufacturer = $f.Manufacturer
        DriverType = $d.DriverType; Architecture = $d.Architecture
        InfRelativePath = $f.InfRelativePath
        ExpectedPublisher = $d.ExpectedPublisher; Version = $d.Version
        DateAdded = $d.DateAdded; SourceURL = $d.SourceURL
        Models = $f.Models
      })
    } else {
      $merged.Add($d)
    }
  }

  $added = 0
  foreach ($f in $script:BuiltInPrinterDriverFamilies) {
    if ($seen[$f.DriverID]) { continue }
    $added++
    $merged.Add(@{
      DriverID = $f.DriverID; DisplayName = $f.DisplayName; Manufacturer = $f.Manufacturer
      DriverType = ''; Architecture = ''
      InfRelativePath = $f.InfRelativePath
      ExpectedPublisher = ''; Version = ''
      DateAdded = (Get-Date -Format 'yyyy-MM-dd'); SourceURL = ''
      Models = $f.Models
    })
  }

  $data.Drivers = @($merged)
  if (-not (Write-DriverLibrary -Data $data)) { throw 'Failed to write driverLibrary.json' }
  return @{ Added = $added; Updated = $updated; Total = $merged.Count }
}

# Converts a local image file to a data: URI for display in the page.
function Get-ImageDataUrl {
  param([string]$Path)
  if (-not $Path -or -not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
  try {
    $ext = [System.IO.Path]::GetExtension($Path).ToLowerInvariant()
    $mime = switch ($ext) {
      '.png'  { 'image/png' }
      '.jpg'  { 'image/jpeg' }
      '.jpeg' { 'image/jpeg' }
      '.svg'  { 'image/svg+xml' }
      default { $null }
    }
    if (-not $mime) { return $null }
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -gt 5MB) { return $null }
    return "data:$mime;base64,$([Convert]::ToBase64String($bytes))"
  } catch { return $null }
}

function Set-DeployStatus {
  param([string]$AppID, [string]$AppName, [string]$Target, [string]$ProfileName, [string]$OutputDir, [switch]$MarkDeployed)
  $store = Get-DeployStatusStore
  if (-not $store.ContainsKey($AppID)) { $store[$AppID] = @{} }
  if ($MarkDeployed) {
    $store[$AppID]['deployedAt'] = (Get-Date -Format 'o')
    Add-DeployHistoryEvent -AppID $AppID -AppName $AppName -Event 'deployed' -Target $store[$AppID]['target'] -ProfileName $store[$AppID]['profile']
  } else {
    $store[$AppID]['builtAt'] = (Get-Date -Format 'o')
    $store[$AppID]['target'] = $Target
    $store[$AppID]['profile'] = $ProfileName
    $store[$AppID]['outputDir'] = $OutputDir
    $store[$AppID]['deployedAt'] = $null
    Add-DeployHistoryEvent -AppID $AppID -AppName $AppName -Event 'built' -Target $Target -ProfileName $ProfileName
  }
  Save-DeployStatusStore -Store $store
}

function Get-FleetPayload {
  param([hashtable]$Config)
  $manifestResult = Get-LocalManifest -XmlFile $ManifestPath
  $deployStore = Get-DeployStatusStore
  # Wrapped in @(...) around the WHOLE if/else (not just inside each branch):
  # PowerShell's pipeline output capture collapses "zero objects emitted" to
  # AutomationNull, not a real empty array - ConvertTo-Json then renders that
  # as {} instead of [], and JS's `apps || []` guard doesn't catch a truthy {}.
  $fleet = @(if ($manifestResult.Ok) {
    @($manifestResult.Apps | ForEach-Object {
      $id = $_.ID
      $ds = if ($deployStore.ContainsKey($id)) { $deployStore[$id] } else { $null }
      $status = if (-not $ds) { 'unknown' }
                elseif ($ds.deployedAt) { 'deployed' }
                else { 'built - not deployed' }
      @{
        id = $id; name = $_.DisplayName; version = $_.Version
        type = if ($ds -and $ds.target) { $ds.target } else { 'runtime' }
        profile = if ($ds) { $ds.profile } else { '' }
        status = $status
        builtAt = if ($ds) { $ds.builtAt } else { '' }
        outputDir = if ($ds) { $ds.outputDir } else { '' }
      }
    })
  } else {
    Write-AppLog "get-fleet: $($manifestResult.Reason)" WARN
    @()
  })
  @{ apps = $fleet; workerUrl = $Config.WorkerURL }
}

$window = New-Object System.Windows.Window
$window.Title           = 'AppUpdater'
# Sizes the window to the visible work area, not the raw screen size.
$workArea = [System.Windows.SystemParameters]::WorkArea
$window.Width           = [Math]::Min(1280, $workArea.Width - 40)
$window.Height          = [Math]::Min(800, $workArea.Height - 40)
$window.MinWidth        = 860
$window.MinHeight       = 640
$window.WindowStyle     = 'None'
$window.ResizeMode      = 'CanResize'
$window.AllowsTransparency = $false
$window.Background      = [System.Windows.Media.Brushes]::Black
$window.WindowStartupLocation = 'CenterScreen'

# GlassFrameThickness=0 kills a stray white sliver WPF draws along the top
# of borderless windows otherwise.
$chrome = New-Object System.Windows.Shell.WindowChrome
$chrome.CaptionHeight = 0
$chrome.GlassFrameThickness = New-Object System.Windows.Thickness(0)
$chrome.ResizeBorderThickness = New-Object System.Windows.Thickness(5)
[System.Windows.Shell.WindowChrome]::SetWindowChrome($window, $chrome)

# Native window-move support for the custom title bar.
Add-Type -Name Win32Drag -Namespace AppUpdater -MemberDefinition @'
[DllImport("user32.dll")] public static extern bool ReleaseCapture();
[DllImport("user32.dll")] public static extern int SendMessage(IntPtr hWnd, int msg, int wParam, int lParam);
'@

$wv = New-Object Microsoft.Web.WebView2.Wpf.WebView2
$window.Content = $wv
# Allows normal mouse input to pass through to the WebView2 control.
[System.Windows.Shell.WindowChrome]::SetIsHitTestVisibleInChrome($wv, $true)

$window.Add_Loaded({
  # Initializes WebView2 once the window has loaded.
try {
  # Synchronously waits for a Task to complete without blocking the UI thread.
  function Wait-UiTask($Task) {
    $frame = New-Object System.Windows.Threading.DispatcherFrame
    $continuation = [Action[System.Threading.Tasks.Task]]{ $frame.Continue = $false }
    $Task.ContinueWith($continuation, [System.Threading.Tasks.TaskScheduler]::FromCurrentSynchronizationContext()) | Out-Null
    [System.Windows.Threading.Dispatcher]::PushFrame($frame)
    if ($Task.IsFaulted) { throw $Task.Exception.GetBaseException() }
  }

  # Remote debugging port, enabled via the APPUPDATER_DEBUG_PORT env var.
  $envOptions = [Microsoft.Web.WebView2.Core.CoreWebView2EnvironmentOptions]::new()
  if ($env:APPUPDATER_DEBUG_PORT) {
    $envOptions.AdditionalBrowserArguments = "--remote-debugging-port=$($env:APPUPDATER_DEBUG_PORT)"
  }
  $envTask = [Microsoft.Web.WebView2.Core.CoreWebView2Environment]::CreateAsync(
    $null, (Join-Path $env:LOCALAPPDATA 'AppUpdater\WebView2'), $envOptions
  )
  Wait-UiTask $envTask
  $env = $envTask.Result

  $initTask = $wv.EnsureCoreWebView2Async($env)
  Wait-UiTask $initTask
  $wv.CoreWebView2.Settings.AreDevToolsEnabled = $false
  $wv.CoreWebView2.Settings.AreDefaultContextMenusEnabled = $false

  $wv.CoreWebView2.NavigateToString($__UiHtml)

  # -----------------------------------------------------------------
  # Handles messages posted from the page via window.chrome.webview.postMessage.
  # -----------------------------------------------------------------
  $wv.CoreWebView2.Add_WebMessageReceived({
    param($s, $e)
    $msg = $e.WebMessageAsJson | ConvertFrom-Json
    try {
      switch ($msg.action) {
            'browse-installer' {
              $ofd = New-Object Microsoft.Win32.OpenFileDialog
              $ofd.Filter = 'Installers (*.exe;*.msi)|*.exe;*.msi|All files (*.*)|*.*'
              $ok = $ofd.ShowDialog($window)
              if ($ok) {
                # Inspects the installer and shapes the result for the Build screen.
                $d = Invoke-InstallerInspector -InstallerPath $ofd.FileName
                $chips = @()
                if ($d.InstallerType) { $chips += @{ label = $d.InstallerType; tone = 'g' } }
                if ($d.Version) { $chips += @{ label = "version $($d.Version)" } }
                if ($d.SilentArgs) { $chips += @{ label = $d.SilentArgs } }
                if ($d.Publisher) { $chips += @{ label = $d.Publisher; tone = 'g' } }
                $detected = @{
                  summary = (@($d.Version, $d.Publisher) | Where-Object { $_ }) -join ' - '
                  appId = $d.AppID; displayName = $d.DisplayName; registryName = $d.RegistryName
                  processesToKill = $d.ProcessesToKill; chips = $chips
                }
                Send-ToPage $wv 'browse-installer-result' @{ ok = $true; path = $ofd.FileName; detected = $detected }
              } else {
                Send-ToPage $wv 'browse-installer-result' @{ ok = $false }
              }
            }
            'get-fleet' {
              # Sends the local fleet data, or an empty result on failure.
              try {
                Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
              } catch {
                Send-ToPage $wv 'fleet-data' @{ apps = @(); workerUrl = $config.WorkerURL; checkFailed = $true }
                Send-ToPage $wv 'error' @{ message = "Couldn't read the local fleet: $($_.Exception.Message)" }
              }
            }
            'get-history' {
              $hist = @(Get-DeployHistory)
              [array]::Reverse($hist)
              Send-ToPage $wv 'history-data' @{ events = $hist }
            }
            'build-package' {
              # Starts the package build on a background job.
              Start-PackageBuildJob -Wv $wv -Config $config -FormData (ConvertTo-HashtableShallow $msg.payload)
            }
            'get-driver-library' {
              # HasFiles mirrors the exact directory-existence gate Invoke-PackageBuilder
              # itself checks before a Printer build - not SourceURL, which is blank for
              # perfectly valid local-zip/folder imports too, only URL-based ones set it.
              $__drivers = @((Get-DriverLibrary).Drivers | ForEach-Object {
                $_.HasFiles = Test-Path -LiteralPath (Join-Path $DriverStoreBase $_.DriverID) -PathType Container
                $_
              })
              Send-ToPage $wv 'driver-library-data' @{ drivers = $__drivers }
            }
            'import-builtin-driver-families' {
              try {
                $result = Import-BuiltInDriverFamilies
                Send-ToPage $wv 'driver-library-data' @{ drivers = @((Get-DriverLibrary).Drivers) }
                Send-ToPage $wv 'builtin-families-imported' @{ ok = $true; added = $result.Added; updated = $result.Updated; total = $result.Total }
              } catch {
                Send-ToPage $wv 'builtin-families-imported' @{ ok = $false; message = $_.Exception.Message }
              }
            }
            'add-driver-to-library' {
              # Synchronous (may briefly block the UI thread on a network import) -
              # mirrors the other synchronous handlers in this switch; only the
              # multi-minute package build itself is backgrounded.
              $p = $msg.payload
              try {
                $entry = Add-LibraryDriver -DriverID $p.driverId -DisplayName $p.displayName -SourcePath $p.sourcePath `
                  -InfRelativePath $p.infRelativePath -Manufacturer $p.manufacturer -DriverType $p.driverType `
                  -Architecture $p.architecture -ExpectedPublisher $p.expectedPublisher -Version $p.version `
                  -Models @($p.models | Where-Object { $_ })
                if ($entry) { Send-ToPage $wv 'driver-added' @{ ok = $true; entry = $entry } }
                else { Send-ToPage $wv 'driver-added' @{ ok = $false; message = 'Import failed â€” check AppUpdater.log for details.' } }
              } catch {
                Send-ToPage $wv 'driver-added' @{ ok = $false; message = $_.Exception.Message }
              }
            }
            'get-config' {
              Send-ToPage $wv 'config-data' @{ orgName = $config.OrgName }
            }
            'set-org-name' {
              $config.OrgName = $msg.payload.orgName
              try { $config | ConvertTo-Json -Depth 5 | Set-Content $ConfigFile -Encoding UTF8 -Force } catch {
                Send-ToPage $wv 'error' @{ message = $_.Exception.Message }
              }
            }
            'open-status-dashboard' {
              if ($config.WorkerURL) { Start-Process "$($config.WorkerURL)/status" }
            }
            'setup-custom-domain' {
              # Unused - superseded by 'open-worker-options'.
            }
            'open-worker-options' {
              # Opens the legacy Worker options menu.
              try {
                $rdResult = Invoke-RedeployWorker -Config $config
                # Reloads the config in case the dialog changed it.
                $reloaded = Read-PersistedConfig -Path $ConfigFile
                if ($reloaded) { $config = $reloaded }
                Send-ToPage $wv 'config-data' @{ orgName = $config.OrgName }
              } catch {
                Write-AppLog "open-worker-options failed: $($_.Exception.Message)" ERROR
                Send-ToPage $wv 'error' @{ message = "Worker options failed to open: $($_.Exception.Message)" }
              }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'disconnect-worker' {
              $config.WorkerURL = ''; $config.WorkerDevURL = ''; $config.ManifestToken = ''
              try { $config | ConvertTo-Json -Depth 5 | Set-Content $ConfigFile -Encoding UTF8 -Force } catch { }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'get-profiles' {
              $pd = Get-PackagingProfiles
              Send-ToPage $wv 'profiles-data' @{ profiles = $pd.Profiles; lastUsed = $pd.LastUsed }
            }
            'save-profile' {
              $p = $msg.payload
              $ok = Save-PackagingProfile -Profile @{
                Name = $p.Name; OrgName = $p.OrgName
                LogoImagePath = $p.LogoImagePath; BannerImagePath = $p.BannerImagePath
                DefaultTarget = $p.DefaultTarget
              }
              $pd = Get-PackagingProfiles
              Send-ToPage $wv 'profiles-data' @{ profiles = $pd.Profiles; lastUsed = $pd.LastUsed; saveOk = $ok }
            }
            'delete-profile' {
              Remove-PackagingProfile -Name $msg.payload.name
              $pd = Get-PackagingProfiles
              Send-ToPage $wv 'profiles-data' @{ profiles = $pd.Profiles; lastUsed = $pd.LastUsed }
            }
            'browse-image' {
              $ifd = New-Object Microsoft.Win32.OpenFileDialog
              $ifd.Filter = 'Images (*.png;*.jpg;*.jpeg;*.svg)|*.png;*.jpg;*.jpeg;*.svg|All files (*.*)|*.*'
              if ($ifd.ShowDialog($window)) {
                Send-ToPage $wv 'browse-image-result' @{ ok = $true; field = $msg.payload.field; path = $ifd.FileName; dataUrl = (Get-ImageDataUrl -Path $ifd.FileName) }
              } else {
                Send-ToPage $wv 'browse-image-result' @{ ok = $false; field = $msg.payload.field }
              }
            }
            'get-image-preview' {
              Send-ToPage $wv 'image-preview-result' @{ field = $msg.payload.field; dataUrl = (Get-ImageDataUrl -Path $msg.payload.path) }
            }
            'get-psadt-stock-assets' {
              # Sends the cached PSADT stock banner/icon for the branding preview.
              try {
                $bannerPath = Join-Path $PSADTCacheDir 'PSAppDeployToolkit\Assets\Banner.Classic.png'
                $iconPath   = Join-Path $PSADTCacheDir 'PSAppDeployToolkit\Assets\AppIcon.png'
                if ((Test-Path $bannerPath) -and (Test-Path $iconPath)) {
                  Send-ToPage $wv 'psadt-stock-assets' @{ ok = $true; banner = (Get-ImageDataUrl -Path $bannerPath); icon = (Get-ImageDataUrl -Path $iconPath) }
                } else {
                  Send-ToPage $wv 'psadt-stock-assets' @{ ok = $false }
                }
              } catch {
                Send-ToPage $wv 'psadt-stock-assets' @{ ok = $false }
              }
            }
            'mark-deployed' {
              $mdManifest = Get-LocalManifest -XmlFile $ManifestPath
              $mdApp = if ($mdManifest.Ok) { $mdManifest.Apps | Where-Object { $_.ID -eq $msg.payload.id } | Select-Object -First 1 } else { $null }
              Set-DeployStatus -AppID $msg.payload.id -AppName (if ($mdApp) { $mdApp.DisplayName } else { $msg.payload.id }) -MarkDeployed
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'remove-from-fleet' {
              # Prompts for removal scope, then removes the app.
              $rmId = $msg.payload.id
              $rmManifest = Get-LocalManifest -XmlFile $ManifestPath
              $rmApp = if ($rmManifest.Ok) { $rmManifest.Apps | Where-Object { $_.ID -eq $rmId } | Select-Object -First 1 } else { $null }
              $rmName = if ($rmApp) { $rmApp.DisplayName } else { $rmId }
              $rmChoice = Show-WpfDeleteChoice -AppName $rmName -AppID $rmId
              if (-not $rmChoice -or $rmChoice -eq 'cancel') {
                Send-ToPage $wv 'remove-from-fleet-result' @{ ok = $false; cancelled = $true }
              } else {
                $rmReport = $null
                if ($rmChoice -eq 'everything') {
                  $rmReport = Remove-AppLocalArtifacts -AppID $rmId -DisplayName $rmName
                }
                try {
                  [xml]$rmXml = Get-Content $ManifestPath -Raw -Encoding UTF8 -ErrorAction Stop
                  $rmNodes = @($rmXml.AppManifest.App | Where-Object { $_.ID -eq $rmId })
                  foreach ($rmNode in $rmNodes) { $rmXml.AppManifest.RemoveChild($rmNode) | Out-Null }
                  $rmXml.Save($ManifestPath)
                  $rmRemaining = @($rmXml.AppManifest.App | Where-Object { $_ -ne $null -and $_.ID })
                  if ($rmRemaining.Count -eq 0) { Remove-Item $ManifestPath -Force -ErrorAction SilentlyContinue }
                  $rmStore = Get-DeployStatusStore
                  if ($rmStore.ContainsKey($rmId)) { $rmStore.Remove($rmId); Save-DeployStatusStore -Store $rmStore }
                  Add-DeployHistoryEvent -AppID $rmId -AppName $rmName -Event ('removed' + $(if ($rmChoice -eq 'everything') { ' (+ local cleanup)' } else { '' }))
                  Send-ToPage $wv 'remove-from-fleet-result' @{ ok = $true; everything = ($rmChoice -eq 'everything') }
                } catch {
                  Send-ToPage $wv 'remove-from-fleet-result' @{ ok = $false; message = $_.Exception.Message }
                }
              }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'test-locally' {
              # Runs the generated install/detect/uninstall scripts on this machine.
              $store = Get-DeployStatusStore
              $entry = $store[$msg.payload.id]
              if (-not $entry -or -not $entry.outputDir -or -not (Test-Path $entry.outputDir)) {
                Send-ToPage $wv 'test-log' @{ line = 'No output folder on record for this app - rebuild it first.'; done = $true; ok = $false }
              } else {
                Start-LocalTestJob -Wv $wv -AppID $msg.payload.id -OutputDir $entry.outputDir -Target $entry.target -AlsoUninstall:([bool]$msg.payload.alsoUninstall) -SimulateSystem:([bool]$msg.payload.simulateSystem)
              }
            }
            'get-settings' {
              Send-ToPage $wv 'settings-data' @{
                orgName = $config.OrgName
                reduceMotion = [bool]$config.ReduceMotion
                highContrast = [bool]$config.HighContrast
                colorblindSafe = [bool]$config.ColorblindSafe
                releaseCheckEnabled = -not [bool]$config.DisableReleaseCheck
                showCloudflareAdvert = -not [bool]$config.HideCloudflareAdvert
                showGettingStarted = -not [bool]$config.HideGettingStarted
                showCloudflareNav = -not [bool]$config.HideCloudflareNav
                onboardingSeen = [bool]$config.OnboardingSeen
                modeExplainerSeen = [bool]$config.ModeExplainerSeen
                version = $global:Version
                newerAvailable = [bool]($global:_relCheck -and $global:_relCheck.Newer -and $global:_relCheck.Latest)
                latestVersion = if ($global:_relCheck) { $global:_relCheck.Latest } else { '' }
                releaseInfo = if ($global:_relCheck -and $global:_relCheck.Newer -and $global:_relCheck.Latest) {
                  "Update available: v$($global:_relCheck.Latest) on GitHub"
                } elseif ($global:_relCheck -and $global:_relCheck.Latest) {
                  "Up to date (latest release: v$($global:_relCheck.Latest))"
                } else { 'Release check pending or offline.' }
              }
            }
            'save-settings' {
              $config.OrgName = $msg.payload.orgName
              $config.ReduceMotion = [bool]$msg.payload.reduceMotion
              $global:ReduceMotion = $config.ReduceMotion
              $config.HighContrast = [bool]$msg.payload.highContrast
              $config.ColorblindSafe = [bool]$msg.payload.colorblindSafe
              $config.DisableReleaseCheck = -not [bool]$msg.payload.releaseCheckEnabled
              $config.HideCloudflareAdvert = -not [bool]$msg.payload.showCloudflareAdvert
              $config.HideGettingStarted = -not [bool]$msg.payload.showGettingStarted
              $config.HideCloudflareNav = -not [bool]$msg.payload.showCloudflareNav
              $ok = Save-PersistedConfig -Config $config
              Send-ToPage $wv 'settings-saved' @{ ok = $ok }
              Send-ToPage $wv 'fleet-data' (Get-FleetPayload -Config $config)
            }
            'dismiss-cloudflare-advert' {
              $config.HideCloudflareAdvert = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'dismiss-getting-started' {
              $config.HideGettingStarted = $true
              [void](Save-PersistedConfig -Config $config)
            }
            'mark-onboarding-seen' {
              try {
                $config.OnboardingSeen = $true
                [void](Save-PersistedConfig -Config $config)
              } catch {
                try { Add-Content -LiteralPath (Join-Path $PSScriptRoot 'AppUpdater.log') -Value "$(Get-Date -Format s) [DIAG] mark-onboarding-seen failed; `$config type = $($config.GetType().FullName); error = $($_.Exception.Message)" -ErrorAction Stop } catch {}
                throw
              }
            }
            'mark-mode-explainer-seen' {
              try {
                $config.ModeExplainerSeen = $true
                [void](Save-PersistedConfig -Config $config)
              } catch {
                try { Add-Content -LiteralPath (Join-Path $PSScriptRoot 'AppUpdater.log') -Value "$(Get-Date -Format s) [DIAG] mark-mode-explainer-seen failed; `$config type = $($config.GetType().FullName); error = $($_.Exception.Message)" -ErrorAction Stop } catch {}
                throw
              }
            }
            'reset-onboarding' {
              try {
                $config.OnboardingSeen = $false
                $config.ModeExplainerSeen = $false
                [void](Save-PersistedConfig -Config $config)
              } catch {
                try { Add-Content -LiteralPath (Join-Path $PSScriptRoot 'AppUpdater.log') -Value "$(Get-Date -Format s) [DIAG] reset-onboarding failed; `$config type = $($config.GetType().FullName); error = $($_.Exception.Message)" -ErrorAction Stop } catch {}
                throw
              }
            }
            'client-error' {
              # Surfaces otherwise-invisible JS exceptions (DevTools are off in
              # production) into the same log file everything else uses.
              Write-AppLog "Client-side JS error: $($msg.payload.message) at $($msg.payload.source)`n$($msg.payload.stack)" ERROR
            }
            'open-folder' {
              switch ($msg.payload.which) {
                'output' { try { Start-Process explorer.exe $global:OutputBase } catch { } }
                'cache'  { try { Start-Process explorer.exe $PSADTCacheDir } catch { } }
                'log'    { try { Start-Process notepad.exe $global:LogFile } catch { } }
              }
            }
            'open-github-releases' {
              try { Start-Process 'https://github.com/Lyvvy-xyz/Appupdater/releases' } catch { }
            }
            'drag-window' {
              try {
                $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($window)).Handle
                [AppUpdater.Win32Drag]::ReleaseCapture() | Out-Null
                [AppUpdater.Win32Drag]::SendMessage($hwnd, 0xA1, 0x2, 0) | Out-Null   # WM_NCLBUTTONDOWN, HTCAPTION
              } catch { }
            }
            'minimize-window' {
              $window.WindowState = 'Minimized'
            }
            'close-window' {
              $window.Close()
            }
            'export-recovery-bundle' {
              # Prompts for a passphrase, then exports an encrypted recovery bundle.
              $pw = Show-WpfPassphrase -Title 'Protect recovery bundle' -Confirm
              if ($pw) {
                $sfd = New-Object Microsoft.Win32.SaveFileDialog
                $sfd.Title = 'Save recovery bundle'
                $sfd.FileName = "AppUpdater-recovery-$(Get-Date -Format 'yyyyMMdd').aurb"
                $sfd.Filter = 'AppUpdater recovery bundle (*.aurb)|*.aurb'
                if ($sfd.ShowDialog($window)) {
                  $json = Export-RecoveryState -Config $config
                  $ok = Protect-RecoveryBundle -PlainJson $json -Passphrase $pw -OutFile $sfd.FileName
                  Send-ToPage $wv 'recovery-export-result' @{ ok = $ok; path = $sfd.FileName }
                }
              }
            }
            'import-recovery-bundle' {
              $ofd2 = New-Object Microsoft.Win32.OpenFileDialog
              $ofd2.Title = 'Select recovery bundle'
              $ofd2.Filter = 'AppUpdater recovery bundle (*.aurb)|*.aurb|All files (*.*)|*.*'
              if ($ofd2.ShowDialog($window)) {
                $pw2 = Show-WpfPassphrase -Title 'Unlock recovery bundle'
                if ($pw2) {
                  try {
                    $json2 = Unprotect-RecoveryBundle -InFile $ofd2.FileName -Passphrase $pw2
                    $newCfg = Import-RecoveryState -StateJson $json2
                    Send-ToPage $wv 'recovery-import-result' @{ ok = $true }
                  } catch {
                    Send-ToPage $wv 'recovery-import-result' @{ ok = $false; message = $_.Exception.Message }
                  }
                }
              }
            }
            default {
              Write-AppLog "Unhandled shell action: $($msg.action)" WARN
            }
          }
        } catch {
          Send-ToPage $wv 'error' @{ message = $_.Exception.Message }
        }
      }.GetNewClosure())
} catch {
  $__err = $_.Exception
  $__detail = if ($__err.InnerException) { "$($__err.Message)`n`nInner: $($__err.InnerException.Message)" } else { $__err.ToString() }
  [System.Windows.MessageBox]::Show(
    "The app window failed to start up.`n`n$__detail",
    'AppUpdater - startup error', 'OK', 'Error'
  ) | Out-Null
  $window.Close()
}
})

function Start-LocalTestJob {
  param($Wv, [string]$AppID, [string]$OutputDir, [string]$Target, [switch]$AlsoUninstall, [switch]$SimulateSystem)

  $tq = [System.Collections.Queue]::Synchronized((New-Object System.Collections.Queue))
  $td = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))

  $rs = [runspacefactory]::CreateRunspace()
  $rs.Open()
  $rs.SessionStateProxy.SetVariable('_tq', $tq)
  $rs.SessionStateProxy.SetVariable('_td', $td)
  $rs.SessionStateProxy.SetVariable('_out', $OutputDir)
  $rs.SessionStateProxy.SetVariable('_appId', $AppID)
  $rs.SessionStateProxy.SetVariable('_target', $Target)
  $rs.SessionStateProxy.SetVariable('_alsoUninstall', [bool]$AlsoUninstall)
  $rs.SessionStateProxy.SetVariable('_simulateSystem', [bool]$SimulateSystem)

  $ps = [powershell]::Create()
  $ps.Runspace = $rs
  [void]$ps.AddScript({
    function Log($m) { $_tq.Enqueue($m) }
    function RunAndLog($exe, $argsList, $label) {
      Log "> $label"
      if ($_simulateSystem) {
        return Invoke-AsSystemViaTask $exe $argsList $label
      }
      try {
        $p = Start-Process -FilePath $exe -ArgumentList $argsList -Wait -PassThru -NoNewWindow
        Log "  exit code $($p.ExitCode)"
        return $p.ExitCode
      } catch { Log "  FAILED: $($_.Exception.Message)"; return -1 }
    }
    function RunScriptAndLog($path, $argStr, $label) {
      if (-not (Test-Path $path)) { Log "  (skipped - $([System.IO.Path]::GetFileName($path)) not found)"; return $null }
      return RunAndLog 'powershell.exe' "-NoProfile -ExecutionPolicy Bypass -File `"$path`" $argStr" $label
    }

    # ---------------------------------------------------------------------
    # Runs a command as SYSTEM via a temporary scheduled task.
    # ---------------------------------------------------------------------
    function Invoke-AsSystemViaTask($exe, $argsList, $label) {
      $taskName = "AppUpdaterLocalTest_$([guid]::NewGuid().ToString('N').Substring(0,8))"
      $outFile = Join-Path ([System.IO.Path]::GetTempPath()) "$taskName.out.txt"
      $wrapped = "$exe $argsList > `"$outFile`" 2>&1; exit `$LASTEXITCODE"
      $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -WindowStyle Hidden -Command `"$wrapped`""
      $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
      try {
        Register-ScheduledTask -TaskName $taskName -Action $action -Principal $principal -Force -ErrorAction Stop | Out-Null
        Start-ScheduledTask -TaskName $taskName
        $waited = 0
        do { Start-Sleep -Milliseconds 500; $waited += 500; $info = Get-ScheduledTask -TaskName $taskName | Get-ScheduledTaskInfo }
        while ($info.LastTaskResult -eq 267009 -and $waited -lt 600000)   # 267009 = still running; 10 min cap
        $exitCode = $info.LastTaskResult
        if (Test-Path $outFile) { (Get-Content $outFile -Raw) -split "`n" | Where-Object { $_.Trim() } | ForEach-Object { Log "    [SYSTEM] $_" } }
        Log "  exit code $exitCode (ran as SYSTEM)"
        return $exitCode
      } catch {
        Log "  FAILED to run as SYSTEM: $($_.Exception.Message)"
        return -1
      } finally {
        Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue
        Remove-Item $outFile -Force -ErrorAction SilentlyContinue
      }
    }

    # ---------------------------------------------------------------------
    # Decrypts and extracts an .intunewin package's contents.
    # ---------------------------------------------------------------------
    function Expand-IntuneWinForTest($IntuneWinPath, $DestDir) {
      Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
      $outerDir = Join-Path ([System.IO.Path]::GetTempPath()) "iwt_outer_$([guid]::NewGuid())"
      [System.IO.Compression.ZipFile]::ExtractToDirectory($IntuneWinPath, $outerDir)
      $detXml = Join-Path $outerDir 'IntuneWinPackage\Metadata\Detection.xml'
      if (-not (Test-Path $detXml)) { throw 'Not a recognized .intunewin file (Detection.xml missing).' }
      [xml]$xml = Get-Content $detXml -Raw
      $encInfo = $xml.ApplicationInfo.EncryptionInfo
      $encFile = Get-ChildItem (Join-Path $outerDir 'IntuneWinPackage\Contents') -File -ErrorAction Stop | Select-Object -First 1
      $encBytes = [System.IO.File]::ReadAllBytes($encFile.FullName)
      $key = [Convert]::FromBase64String($encInfo.EncryptionKey)
      $iv = New-Object byte[] 16
      [Array]::Copy($encBytes, 32, $iv, 0, 16)
      $cipherLen = $encBytes.Length - 48
      $cipherBytes = New-Object byte[] $cipherLen
      [Array]::Copy($encBytes, 48, $cipherBytes, 0, $cipherLen)
      $aes = [System.Security.Cryptography.Aes]::Create()
      $aes.Mode = 'CBC'; $aes.Key = $key; $aes.IV = $iv
      $decryptor = $aes.CreateDecryptor()
      $plainBytes = $decryptor.TransformFinalBlock($cipherBytes, 0, $cipherBytes.Length)
      $tmpZip = Join-Path ([System.IO.Path]::GetTempPath()) "iwt_content_$([guid]::NewGuid()).zip"
      [System.IO.File]::WriteAllBytes($tmpZip, $plainBytes)
      New-Item -ItemType Directory -Path $DestDir -Force | Out-Null
      [System.IO.Compression.ZipFile]::ExtractToDirectory($tmpZip, $DestDir)
      Remove-Item $outerDir -Recurse -Force -ErrorAction SilentlyContinue
      Remove-Item $tmpZip -Force -ErrorAction SilentlyContinue
    }

    try {
      # Tests the packaged .intunewin artifact if one exists, otherwise the loose scripts.
      $intuneWinFile = Get-ChildItem $_out -Filter '*.intunewin' -ErrorAction SilentlyContinue | Select-Object -First 1
      $testDir = $_out
      if ($intuneWinFile) {
        Log "Found $($intuneWinFile.Name) - decrypting and extracting for a real test..."
        $testDir = Join-Path ([System.IO.Path]::GetTempPath()) "iwt_extracted_$([guid]::NewGuid())"
        try {
          Expand-IntuneWinForTest $intuneWinFile.FullName $testDir
          Log "  Decrypted OK -> testing the actual packaged contents"
        } catch {
          Log "  Could not decrypt $($intuneWinFile.Name): $($_.Exception.Message)"
          Log '  Falling back to the loose staging scripts instead.'
          $testDir = $_out
        }
      } else {
        Log 'No .intunewin file found in the output folder - testing the loose scripts instead.'
      }

      if ($_target -eq 'psadt' -or $_target -eq 'psadt-v3' -or $_target -eq 'psadt-v4' -or $_target -eq 'both') {
        # Runs the PSADT deployment script directly.
        $deployApp = Join-Path $testDir 'Deploy-Application.ps1'
        $deployMode = if ($_simulateSystem) { 'Silent' } else { 'Interactive' }
        RunScriptAndLog $deployApp "-DeploymentType Install -DeployMode $deployMode" "Install (PSADT, $deployMode)" | Out-Null
        if ($_alsoUninstall) {
          RunScriptAndLog $deployApp "-DeploymentType Uninstall -DeployMode $deployMode" "Uninstall (PSADT, $deployMode)" | Out-Null
        }
      } else {
        # Locates and runs the detect/install/uninstall scripts.
        $detect = Get-ChildItem $testDir -Filter 'detect.ps1' -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $detect) { $detect = Get-ChildItem $testDir -Filter "Detect-$_appId.ps1" -ErrorAction SilentlyContinue | Select-Object -First 1 }
        $install = Get-ChildItem $testDir -Filter 'install.ps1' -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $install) { $install = Get-ChildItem $testDir -Filter "Deploy-$_appId.ps1" -ErrorAction SilentlyContinue | Select-Object -First 1 }
        $uninstall = Get-ChildItem $testDir -Filter 'uninstall.ps1' -ErrorAction SilentlyContinue | Select-Object -First 1

        if ($detect) {
          $r0 = RunScriptAndLog $detect.FullName '' 'Pre-check (detect.ps1)'
          Log "  --> $(if ($r0 -eq 0) { 'Already detected as installed' } else { 'Not detected (expected before install)' })"
        }
        if ($install) {
          RunScriptAndLog $install.FullName '' 'Install' | Out-Null
        } else {
          Log '  No install script found in this output folder.'
        }
        if ($detect) {
          $r1 = RunScriptAndLog $detect.FullName '' 'Post-install check (detect.ps1)'
          Log "  --> $(if ($r1 -eq 0) { 'PASS - detected after install' } else { 'FAIL - NOT detected after install (detection rule or install command is wrong)' })"
        }
        if ($_alsoUninstall -and $uninstall) {
          RunScriptAndLog $uninstall.FullName '' 'Uninstall' | Out-Null
          if ($detect) {
            $r2 = RunScriptAndLog $detect.FullName '' 'Post-uninstall check (detect.ps1)'
            Log "  --> $(if ($r2 -ne 0) { 'PASS - no longer detected' } else { 'FAIL - still detected after uninstall' })"
          }
        }
      }
      if ($testDir -ne $_out) { Remove-Item $testDir -Recurse -Force -ErrorAction SilentlyContinue }
      Log '=== Local test complete ==='
      $td.Add(@{ ok = $true }) | Out-Null
    } catch {
      Log "ERROR: $($_.Exception.Message)"
      $td.Add(@{ ok = $false }) | Out-Null
    }
  })
  $handle = $ps.BeginInvoke()

  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(150)
  $timer.Add_Tick({
    while ($tq.Count -gt 0) { Send-ToPage $Wv 'test-log' @{ line = $tq.Dequeue(); done = $false } }
    if ($td.Count -gt 0) {
      $timer.Stop()
      Send-ToPage $Wv 'test-log' @{ line = ''; done = $true; ok = $td[0].ok }
      $ps.EndInvoke($handle) | Out-Null
      $ps.Dispose(); $rs.Close()
    }
  })
  $timer.Start()
}

function Send-ToPage {
  param($Wv, [string]$Type, [hashtable]$Payload)
  $json = (@{ type = $Type; payload = $Payload } | ConvertTo-Json -Depth 8 -Compress)
  $Wv.Dispatcher.Invoke([action]{
    $Wv.CoreWebView2.PostWebMessageAsJson($json)
  })
}

# ---------------------------------------------------------------------------
# Runs the package build on a background job and streams progress to the page.
# ---------------------------------------------------------------------------
function Start-PackageBuildJob {
  param($Wv, [hashtable]$Config, [hashtable]$FormData)

  $bq = [System.Collections.Queue]::Synchronized((New-Object System.Collections.Queue))
  $bd = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))

  # Resolved here (main scope) rather than inside the runspace below, since
  # Get-PackagingProfiles is only loaded in THIS scope (via the top-level
  # -LoadFunctionsOnly dot-source), not automatically in a fresh runspace.
  $_profile = @{ OrgName = ''; LogoImagePath = ''; BannerImagePath = '' }
  if ($FormData.ProfileName) {
    $_pp = (Get-PackagingProfiles).Profiles | Where-Object { $_.Name -eq $FormData.ProfileName } | Select-Object -First 1
    if ($_pp) {
      if ($_pp.OrgName) { $_profile.OrgName = $_pp.OrgName }
      $_profile.LogoImagePath   = $_pp.LogoImagePath
      $_profile.BannerImagePath = $_pp.BannerImagePath
    }
  }
  # Ephemeral per-build overrides from the Build screen - apply on top of the
  # saved profile without touching profiles.json (saving back, if the user
  # opts in, is a separate explicit 'save-profile' message from the UI).
  if ($FormData.OverrideOrgName)         { $_profile.OrgName = $FormData.OverrideOrgName }
  if ($FormData.OverrideLogoImagePath)   { $_profile.LogoImagePath = $FormData.OverrideLogoImagePath }
  if ($FormData.OverrideBannerImagePath) { $_profile.BannerImagePath = $FormData.OverrideBannerImagePath }

  # Only the specific build-time functions are reflected into the child
  # runspace below (mirrors Start-BackgroundJob above) - never Invoke-Expression
  # the raw $__CoreSrc here. That string is the ENTIRE original standalone app:
  # self-elevation, a single-instance mutex guard, and its own infinite legacy
  # WPF main-menu loop with several `exit` calls. Running it wholesale meant
  # that legacy mutex guard - already held by this same process's own startup
  # load (the `-LoadFunctionsOnly` dot-source near the top of the file) - always
  # failed from this second thread and called `exit`, which kills the entire
  # process before Invoke-PackageBuilder below was ever reached. That was the
  # "Build Package closes the app, regardless of selection" bug.
  $_buildFnNames = @(
    'Invoke-PackageBuilder','Export-PSADTPackage','Invoke-InstallerInspector',
    'Get-PSADTToolkit','Get-PSADTModuleOnly','Import-PSADTToolkitSource',
    'Get-InstallerType','Get-SilentArgs','Read-MsiProperties',
    'Unprotect-ManifestToken','Test-SafeAppId','Test-SafeHttpsUrl',
    'Resolve-SafeChildPath','ConvertTo-PSQ','Test-DownloadAuthenticode',
    'Get-DriverLibrary','Write-DriverLibrary'
  )
  $_buildFnSrc = ($_buildFnNames | ForEach-Object {
    $fn = Get-Item "Function:\$_" -ErrorAction SilentlyContinue
    if ($fn) { "function $_ {`n$($fn.ScriptBlock)`n}" }
  }) -join "`n"

  $rs = [runspacefactory]::CreateRunspace()
  $rs.Open()
  $rs.SessionStateProxy.SetVariable('_bq', $bq)
  $rs.SessionStateProxy.SetVariable('_bd', $bd)
  $rs.SessionStateProxy.SetVariable('_cfg', $Config)
  $rs.SessionStateProxy.SetVariable('_fd', $FormData)
  $rs.SessionStateProxy.SetVariable('_profile', $_profile)
  $rs.SessionStateProxy.SetVariable('_fnSrc', $_buildFnSrc)
  foreach ($vn in @('XmlFile','IntuneWinUtilPath','IntuneWinUtilURL','TempBase','OutputBase',
                     'PSADTCacheDir','PSADTv3URL','PSADTModOnlyURL',
                     'DriverStoreBase','DriverLibraryFile')) {
    $rs.SessionStateProxy.SetVariable($vn, (Get-Variable $vn -ValueOnly -Scope Script -ErrorAction SilentlyContinue))
  }

  $ps = [powershell]::Create()
  $ps.Runspace = $rs
  [void]$ps.AddScript({
    # Fixed constants Unprotect-ManifestToken needs - $global: vars aren't
    # shared across runspaces (unlike Add-Type'd types, which are process-wide).
    $global:_DpapiPrefix = 'DPAPI:'
    $global:_CredMgrSentinel = 'CREDMGR'
    # Redirects the builder's logging functions to the progress queue.
    function Write-AppLog { param([string]$Message,[string]$Level='INFO') $_bq.Enqueue("log|$Message") }
    function Write-Host   { param([object]$O,[string]$ForegroundColor='Gray',[switch]$NoNewline) $_bq.Enqueue("line|$O") }
    function Write-OK     { param([string]$M) Write-Host "  [OK]  $M" }
    function Write-Warn   { param([string]$M) Write-Host "  [!!]  $M" }
    function Write-Fail   { param([string]$M) Write-Host "  [XX]  $M" }
    function Write-Info   { param([string]$M) Write-Host "  [--]  $M" }
    function Write-Step   { param([string]$N,[string]$M) $_bq.Enqueue("step|$N|$M") }
    # No-op replacements for the builder's legacy WPF dialogs - none of these
    # should ever pop a window from a background runspace.
    function Show-WpfMsg  { param([string]$Title='',[string]$Message='',[string]$Type='info',[switch]$Confirm) $_bq.Enqueue("line|[$Title] $Message"); return $true }
    function Show-WpfAppForm { param([hashtable]$Defaults=@{},[bool]$HasWorker=$false,[string]$OrgName='',[switch]$AmendMode) return $null }
    function Show-WpfPSADTExport { param([string]$AppID='',[string]$DisplayName='',[string]$ProcessesToKill='',[string]$ExpectedPub='',[string]$OrgName='') }

    try {
      Invoke-Expression $_fnSrc
      # Applies the selected profile's org name to a copy of the config.
      $_buildCfg = $_cfg
      if ($_profile.OrgName) {
        $_buildCfg = @{}; foreach ($k in $_cfg.Keys) { $_buildCfg[$k] = $_cfg[$k] }
        $_buildCfg.OrgName = $_profile.OrgName
      }
      $result = Invoke-PackageBuilder -Config $_buildCfg -FormData $_fd
      # Wraps the build as a PSADT package if requested.
      if ($_fd.Mode -ne 'simple' -and $_fd.SimplePkgTarget -eq 'psadt') {
        $_bq.Enqueue("step|5/5|Wrapping as PSADT package")
        $psadtVer = if ($_fd.PSADTVersion) { $_fd.PSADTVersion } else { 'v3' }
        $result = Export-PSADTPackage -AppID $_fd.AppID -DisplayName $_fd.DisplayName `
          -ProcessesToKill $_fd.ProcessesToKill -ExpectedPub $_fd.ExpectedPublisher `
          -OrgName $_buildCfg.OrgName -PSADTVersion $psadtVer `
          -LogoImagePath $_profile.LogoImagePath -BannerImagePath $_profile.BannerImagePath
      }
      $_bd.Add(@{ ok = $true; path = $result.OutputDir; appId = $_fd.AppID; displayName = $_fd.DisplayName; target = $_fd.SimplePkgTarget; profile = $_fd.ProfileName }) | Out-Null
    } catch {
      $_bd.Add(@{ ok = $false; message = $_.Exception.Message }) | Out-Null
    }
  })
  $handle = $ps.BeginInvoke()

  $timer = New-Object System.Windows.Threading.DispatcherTimer
  $timer.Interval = [TimeSpan]::FromMilliseconds(150)
  $timer.Add_Tick({
    while ($bq.Count -gt 0) {
      $line = $bq.Dequeue()
      $parts = $line -split '\|', 3
      switch ($parts[0]) {
        'step' { Send-ToPage $Wv 'build-progress' @{ step = $parts[1]; label = $parts[2] } }
        default { Send-ToPage $Wv 'build-log' @{ line = $parts[1] } }
      }
    }
    if ($bd.Count -gt 0) {
      $timer.Stop()
      $done = $bd[0]
      if ($done.ok) {
        if ($done.appId) { Set-DeployStatus -AppID $done.appId -AppName $done.displayName -Target $done.target -ProfileName $done.profile -OutputDir $done.path }
        Send-ToPage $Wv 'build-done' @{ path = $done.path }
      }
      else { Send-ToPage $Wv 'error' @{ message = $done.message } }
      $ps.EndInvoke($handle) | Out-Null
      $ps.Dispose(); $rs.Close()
    }
  })
  $timer.Start()
}

$window.ShowDialog() | Out-Null
